/**
 * The Pixi stage: one WebGL renderer, a world-unit scene graph and the frame loop.
 *
 * Layers, bottom to top: video, mask overlay (debug), bubbles, pop effects, coverage
 * (debug), the round's tags, scores and messages. Everything lives under one container scaled by `view.screenScale`, so all
 * placement is in world units and comes from the ViewTransform.
 */
import { autoDetectRenderer, Container, Ticker, WebGLRenderer } from 'pixi.js';
import type { Tunables } from '../config/tunables';
import { Emitter, type Unsubscribe } from '../core/events';
import type { PersonMask } from '../core/mask';
import type { ViewTransform } from '../core/view';
import type { GameEvent, Round, RoundEvent, World } from '../game/types';
import type { DisplaySource } from '../vision/types';
import { BubbleLayer } from './bubbles';
import { CoverageOverlay } from './coverage';
import { PopEffects } from './effects';
import { FrameStats } from './frameStats';
import { MaskOverlay } from './maskOverlay';
import { capResolution } from './resolution';
import { RoundHud } from './roundHud';
import { createStageTextures, type StageTextures } from './textures';
import type { RenderStats, Stage, StageOptions } from './types';
import { VideoLayer } from './videoLayer';

/** Longest frame the simulation is stepped by; a stall longer than this slows time instead. */
const MAX_DT_MS = 50;

/** Everything that exists only after `init`. */
interface Scene {
  renderer: WebGLRenderer;
  textures: StageTextures;
  bubbles: BubbleLayer;
  effects: PopEffects;
  coverage: CoverageOverlay;
  hud: RoundHud;
}

class PixiStage implements Stage {
  readonly stats: RenderStats = {
    fps: 0,
    frameMsP95: 0,
    bufferWidth: 0,
    bufferHeight: 0,
    resolution: 1,
    bubbles: 0,
    particles: 0,
    glRenderer: null,
  };

  private readonly container: HTMLElement;
  private readonly tunables: Tunables;
  private readonly resized = new Emitter<[number, number]>();
  private readonly contextLost = new Emitter<void>();
  private readonly contextRestored = new Emitter<void>();
  private readonly frameStats = new FrameStats();

  private readonly root = new Container();
  private readonly world = new Container();
  private readonly video = new VideoLayer();
  private readonly mask: MaskOverlay;
  private scene: Scene | null = null;

  private view: ViewTransform | null = null;
  private tick: ((dtMs: number, nowMs: number) => void) | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private cssWidth = 1;
  private cssHeight = 1;
  /** What the renderer was last sized to (Pixi rounds its own screen size). */
  private appliedWidth = 0;
  private appliedHeight = 0;
  private running = false;
  private lost = false;
  private disposed = false;
  private raf = 0;
  private lastFrameMs = 0;

  constructor(options: StageOptions) {
    this.container = options.container;
    this.tunables = options.tunables;
    this.mask = new MaskOverlay(options.tunables);
    this.root.addChild(this.world);
    this.world.addChild(this.video.sprite, this.mask.sprite);
  }

  get screenWidth(): number {
    return this.scene?.renderer.screen.width ?? this.cssWidth;
  }

  get screenHeight(): number {
    return this.scene?.renderer.screen.height ?? this.cssHeight;
  }

  async init(): Promise<void> {
    if (this.scene || this.disposed) return;
    this.measure();
    // WebGL only: a list with one entry means no fallback to WebGPU or canvas.
    const renderer = await autoDetectRenderer({
      preference: ['webgl'],
      width: this.cssWidth,
      height: this.cssHeight,
      resolution: this.targetResolution(),
      autoDensity: true,
      antialias: false,
      background: 0x000000,
      // Input comes from the camera: no Pixi pointer hit-testing, and no accessibility layer
      // popping up over the canvas when someone tabs to the Start button.
      eventFeatures: { move: false, globalMove: false, click: false, wheel: false },
      accessibilityOptions: { activateOnTab: false },
    });
    if (this.disposed || !(renderer instanceof WebGLRenderer)) {
      renderer.destroy();
      if (this.disposed) return;
      throw new Error('WebGL is not available');
    }
    this.appliedWidth = this.cssWidth;
    this.appliedHeight = this.cssHeight;
    const canvas = renderer.canvas;
    canvas.addEventListener('webglcontextlost', this.handleContextLost);
    canvas.addEventListener('webglcontextrestored', this.handleContextRestored);
    this.container.appendChild(canvas);
    this.stats.glRenderer = readGlRenderer(renderer.gl);

    const textures = createStageTextures();
    const scene: Scene = {
      renderer,
      textures,
      bubbles: new BubbleLayer(textures.shells, textures.light),
      effects: new PopEffects(textures.effects),
      coverage: new CoverageOverlay(textures.glyphs, textures.dash),
      hud: new RoundHud(textures.capsule),
    };
    this.world.addChild(
      scene.bubbles.container,
      scene.effects.container,
      scene.coverage.container,
      scene.hud.container,
    );
    this.scene = scene;
    if (this.view) this.setView(this.view);
    this.updateBufferStats();

    this.resizeObserver = new ResizeObserver(() => this.applySize());
    this.resizeObserver.observe(this.container);
    // Pixi's own system ticker runs its texture GC; it pauses with the stage.
    if (!this.running) Ticker.system.stop();
  }

  onResize(listener: (screenWidth: number, screenHeight: number) => void): Unsubscribe {
    return this.resized.on(([width, height]) => listener(width, height));
  }

  onContextLost(listener: () => void): Unsubscribe {
    return this.contextLost.on(() => listener());
  }

  onContextRestored(listener: () => void): Unsubscribe {
    return this.contextRestored.on(() => listener());
  }

  setView(view: ViewTransform): void {
    this.view = view;
    this.world.scale.set(view.screenScale);
    this.video.setView(view);
    this.mask.setView(view);
    const scene = this.scene;
    if (!scene) return;
    scene.hud.setView(view);
    scene.hud.setPixelsPerUnit(view.screenScale * scene.renderer.resolution);
  }

  setVideoSource(source: DisplaySource | null): void {
    this.video.setSource(source);
  }

  setPairedFrame(frame: VideoFrame | null): void {
    if (this.disposed) {
      frame?.close();
      return;
    }
    this.video.setPairedFrame(frame);
  }

  setMaskOverlay(mask: PersonMask | null, ignored?: Uint8Array | null): void {
    this.mask.setMask(mask, ignored ?? null);
  }

  setTick(handler: ((dtMs: number, nowMs: number) => void) | null): void {
    this.tick = handler;
  }

  update(world: World, events: readonly GameEvent[], dtMs: number): void {
    const scene = this.scene;
    if (!scene) return;
    const dtS = dtMs / 1000;
    for (let i = 0; i < events.length; i++) {
      const event = events[i] as GameEvent;
      // Spawns need nothing (sprites follow the world) and expiries are already off screen.
      if (event.type !== 'pop') continue;
      scene.bubbles.pop(event.id);
      scene.effects.burst(event.x, event.y, event.r, event.hue);
    }
    scene.bubbles.sync(world.bubbles, dtS);
    scene.effects.update(dtS);
    scene.coverage.sync(world.bubbles, this.tunables.showCoverage);
    this.stats.bubbles = scene.bubbles.count;
    this.stats.particles = scene.effects.count;
  }

  updateRound(round: Round, events: readonly RoundEvent[], dtMs: number): void {
    const scene = this.scene;
    if (!scene) return;
    scene.hud.update(round, events, dtMs / 1000, this.confetti);
  }

  clear(): void {
    const scene = this.scene;
    if (!scene) return;
    scene.bubbles.clear();
    scene.effects.clear();
    scene.coverage.clear();
    scene.hud.reset();
    this.stats.bubbles = 0;
    this.stats.particles = 0;
  }

  start(): void {
    if (this.running || this.disposed) return;
    this.running = true;
    this.lastFrameMs = 0;
    this.frameStats.reset();
    this.video.start();
    Ticker.system.start();
    this.raf = requestAnimationFrame(this.frame);
  }

  stop(): void {
    if (!this.running) return;
    this.running = false;
    cancelAnimationFrame(this.raf);
    this.video.stop();
    Ticker.system.stop();
  }

  dispose(): void {
    if (this.disposed) return;
    this.stop();
    this.disposed = true;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
    this.resized.clear();
    this.contextLost.clear();
    this.contextRestored.clear();
    this.tick = null;
    this.video.dispose();
    this.mask.dispose();
    const scene = this.scene;
    this.scene = null;
    if (!scene) return;
    scene.bubbles.dispose();
    scene.effects.dispose();
    scene.coverage.dispose();
    scene.hud.dispose();
    scene.textures.destroy();
    this.root.destroy({ children: true });
    const canvas = scene.renderer.canvas;
    canvas.removeEventListener('webglcontextlost', this.handleContextLost);
    canvas.removeEventListener('webglcontextrestored', this.handleContextRestored);
    scene.renderer.destroy({ removeView: true });
    // The renderer was the system ticker's only user; leave it as Pixi expects to find it.
    Ticker.system.start();
  }

  private readonly frame = (now: number): void => {
    if (!this.running) return;
    this.raf = requestAnimationFrame(this.frame);
    const scene = this.scene;
    if (!scene || this.lost) return;

    const dtMs = this.lastFrameMs > 0 ? now - this.lastFrameMs : 1000 / 60;
    if (this.lastFrameMs > 0) this.frameStats.add(dtMs);
    this.lastFrameMs = now;

    // The pixel cap and the display's pixel ratio can change at any time.
    if (this.targetResolution() !== scene.renderer.resolution) this.applySize();

    this.tick?.(Math.min(dtMs, MAX_DT_MS), now);
    this.video.sync(now);
    this.mask.sync();
    scene.renderer.render(this.root);

    this.stats.fps = this.frameStats.fps;
    this.stats.frameMsP95 = this.frameStats.frameMsP95;
  };

  private readonly confetti = (x: number, y: number, r: number, hue: number): void => {
    this.scene?.effects.burst(x, y, r, hue);
  };

  private measure(): void {
    this.cssWidth = Math.max(1, Math.round(this.container.clientWidth));
    this.cssHeight = Math.max(1, Math.round(this.container.clientHeight));
  }

  private targetResolution(): number {
    return capResolution(
      this.cssWidth,
      this.cssHeight,
      window.devicePixelRatio,
      this.tunables.maxRenderPixels,
    );
  }

  /** Match the canvas to the container at the capped resolution; tell the owner if it moved. */
  private applySize(): void {
    const scene = this.scene;
    if (!scene) return;
    this.measure();
    const { renderer } = scene;
    const resolution = this.targetResolution();
    const sizeChanged =
      this.cssWidth !== this.appliedWidth || this.cssHeight !== this.appliedHeight;
    if (!sizeChanged && resolution === renderer.resolution) return;
    this.appliedWidth = this.cssWidth;
    this.appliedHeight = this.cssHeight;
    renderer.resize(this.cssWidth, this.cssHeight, resolution);
    this.updateBufferStats();
    if (this.view) scene.hud.setPixelsPerUnit(this.view.screenScale * resolution);
    if (sizeChanged) this.resized.emit([renderer.screen.width, renderer.screen.height]);
  }

  private updateBufferStats(): void {
    const renderer = this.scene?.renderer;
    if (!renderer) return;
    this.stats.bufferWidth = renderer.canvas.width;
    this.stats.bufferHeight = renderer.canvas.height;
    this.stats.resolution = renderer.resolution;
  }

  private readonly handleContextLost = (): void => {
    this.lost = true;
    this.contextLost.emit();
  };

  private readonly handleContextRestored = (): void => {
    // Pixi rebuilds its GL state; everything we draw re-uploads from what it still holds.
    this.lost = false;
    this.lastFrameMs = 0;
    this.contextRestored.emit();
  };
}

function readGlRenderer(gl: WebGL2RenderingContext | WebGLRenderingContext): string | null {
  try {
    const info = gl.getExtension('WEBGL_debug_renderer_info');
    const value = gl.getParameter(info ? info.UNMASKED_RENDERER_WEBGL : gl.RENDERER);
    return typeof value === 'string' ? value : null;
  } catch {
    return null;
  }
}

export function createStage(options: StageOptions): Stage {
  return new PixiStage(options);
}
