import { Container, Matrix, Sprite, type Texture } from 'pixi.js';
import type { Bubble } from '../game/types';
import { SHELL_EDGE } from './art';
import { hslToRgb, mixRgb } from './color';

/** Pop-in on spawn: scale up with a little overshoot, fade in, and jiggle. */
const SPAWN_GROW_S = 0.3;
const SPAWN_FADE_S = 0.18;
const SPAWN_SCALE_FROM = 0.45;
const SPAWN_JIGGLE = 0.06;
const SPAWN_JIGGLE_DECAY = 4;
/** Resting wobble: peak squash as a fraction of the radius. */
const WOBBLE = 0.022;
/** How far the film pattern turns back and forth, in radians. */
const SWIRL = 0.45;
/** How strongly a bubble's hue tints its film (0 keeps the natural interference colours). */
const HUE_TINT = 0.28;
/** A popped bubble swells and vanishes this fast, under the burst effect, instead of blinking out. */
const BURST_S = 0.1;
const BURST_SWELL = 0.18;

interface BubbleView {
  id: number;
  shell: Sprite;
  light: Sprite;
  /** Frame counter value when the bubble was last seen in the world. */
  seen: number;
  /** Seconds since it popped, or -1 while it is alive. */
  burstS: number;
  /** Last pose, kept so a popped bubble can finish its burst after leaving the world. */
  x: number;
  y: number;
  r: number;
  ageS: number;
  wobbleHz1: number;
  wobbleHz2: number;
  wobblePhase1: number;
  wobblePhase2: number;
  swirlBase: number;
  swirlPhase: number;
}

const easeOutBack = (t: number): number => {
  const c = 1.6;
  const u = t - 1;
  return 1 + (c + 1) * u * u * u + c * u * u;
};

/**
 * Soap-bubble sprites that follow `world.bubbles` by id, pooled. Each bubble is two sprites
 * sharing one wobble: the shell (body, film, rim) turns slowly so its colours swirl, and the
 * lighting stays fixed so highlights keep pointing at the same window.
 */
export class BubbleLayer {
  readonly container = new Container();

  private readonly shells: readonly Texture[];
  private readonly light: Texture;
  private readonly views = new Map<number, BubbleView>();
  private readonly active: BubbleView[] = [];
  private readonly pool: BubbleView[] = [];
  private readonly matrix = new Matrix();
  private frame = 0;

  constructor(shells: readonly Texture[], light: Texture) {
    this.shells = shells;
    this.light = light;
  }

  get count(): number {
    return this.active.length;
  }

  /** A bubble popped: its sprite plays a short burst before going back to the pool. */
  pop(id: number): void {
    const view = this.views.get(id);
    if (view && view.burstS < 0) view.burstS = 0;
  }

  sync(bubbles: readonly Bubble[], dtS: number): void {
    const frame = ++this.frame;
    for (let i = 0; i < bubbles.length; i++) {
      const bubble = bubbles[i] as Bubble;
      const view = this.views.get(bubble.id) ?? this.acquire(bubble);
      view.seen = frame;
      view.x = bubble.x;
      view.y = bubble.y;
      view.r = bubble.r;
      view.ageS = bubble.ageS;
      this.pose(view, 1, 1);
    }
    for (let i = this.active.length - 1; i >= 0; i--) {
      const view = this.active[i] as BubbleView;
      if (view.seen === frame) continue;
      if (view.burstS >= 0 && view.burstS < BURST_S) {
        const e = view.burstS / BURST_S;
        view.burstS += dtS;
        this.pose(view, 1 + BURST_SWELL * e * (2 - e), (1 - e) * (1 - e));
        continue;
      }
      // Gone (popped and burst, or drifted off): back to the pool.
      this.release(i);
    }
  }

  /**
   * Release every sprite, bursts included. Ids restart with each world, so nothing may
   * survive into the next one: a new bubble would inherit a stale view.
   */
  clear(): void {
    for (let i = this.active.length - 1; i >= 0; i--) this.release(i);
  }

  dispose(): void {
    this.views.clear();
    this.active.length = 0;
    this.pool.length = 0;
    this.container.destroy({ children: true });
  }

  private release(index: number): void {
    const view = this.active[index] as BubbleView;
    view.shell.visible = false;
    view.light.visible = false;
    this.views.delete(view.id);
    this.active[index] = this.active[this.active.length - 1] as BubbleView;
    this.active.pop();
    this.pool.push(view);
  }

  private acquire(bubble: Bubble): BubbleView {
    let view = this.pool.pop();
    if (!view) {
      const shell = new Sprite({ anchor: 0.5 });
      const light = new Sprite({ texture: this.light, anchor: 0.5 });
      this.container.addChild(shell, light);
      view = {
        id: 0,
        shell,
        light,
        seen: 0,
        burstS: -1,
        x: 0,
        y: 0,
        r: 0,
        ageS: 0,
        wobbleHz1: 0,
        wobbleHz2: 0,
        wobblePhase1: 0,
        wobblePhase2: 0,
        swirlBase: 0,
        swirlPhase: 0,
      };
    }
    // Everything per-bubble derives from its seed, so a bubble looks the same every frame.
    const seed = bubble.seed;
    const hue = ((bubble.hue % 360) + 360) % 360;
    const variant = Math.floor((hue / 360) * this.shells.length) % this.shells.length;
    view.id = bubble.id;
    view.burstS = -1;
    view.shell.texture = this.shells[variant] as Texture;
    view.shell.tint = mixRgb(0xffffff, hslToRgb(hue, 0.9, 0.62), HUE_TINT);
    view.wobbleHz1 = 0.7 + 0.5 * fract(seed * 7.13);
    view.wobbleHz2 = 0.9 + 0.5 * fract(seed * 3.71);
    view.wobblePhase1 = 2 * Math.PI * fract(seed * 13.7);
    view.wobblePhase2 = 2 * Math.PI * fract(seed * 29.3);
    view.swirlBase = (fract(seed * 5.9) * 2 - 1) * 0.6;
    view.swirlPhase = 2 * Math.PI * fract(seed * 17.1);
    view.shell.visible = true;
    view.light.visible = true;
    this.views.set(bubble.id, view);
    this.active.push(view);
    return view;
  }

  /** Place both sprites from the view's last pose; `swell` and `fade` drive the burst. */
  private pose(view: BubbleView, swell: number, fade: number): void {
    const t = view.ageS;
    const grow = Math.min(1, t / SPAWN_GROW_S);
    const appear = SPAWN_SCALE_FROM + (1 - SPAWN_SCALE_FROM) * easeOutBack(grow);
    const alpha = Math.min(1, t / SPAWN_FADE_S) * fade;
    // The texture's edge sits at SHELL_EDGE of its half-width; scale so the edge lands on r.
    const k = (swell * appear * view.r) / ((view.shell.texture.width / 2) * SHELL_EDGE);

    // Two squash modes (along the axes and the diagonals) make an ellipse whose axis wanders.
    const amplitude = WOBBLE + SPAWN_JIGGLE * Math.exp(-t * SPAWN_JIGGLE_DECAY);
    const w1 = amplitude * Math.sin(2 * Math.PI * view.wobbleHz1 * t + view.wobblePhase1);
    const w2 = amplitude * 0.7 * Math.sin(2 * Math.PI * view.wobbleHz2 * t + view.wobblePhase2);
    const swirl = view.swirlBase + SWIRL * Math.sin(0.35 * t + view.swirlPhase);
    const cos = Math.cos(swirl);
    const sin = Math.sin(swirl);

    // Shell: wobble · rotation, so the film turns inside an outline shared with the light.
    const m = this.matrix;
    m.a = k * ((1 + w1) * cos + w2 * sin);
    m.b = k * (w2 * cos + (1 - w1) * sin);
    m.c = k * (w2 * cos - (1 + w1) * sin);
    m.d = k * ((1 - w1) * cos - w2 * sin);
    m.tx = view.x;
    m.ty = view.y;
    view.shell.setFromMatrix(m);
    view.shell.alpha = alpha;

    // Light: the same wobble, no rotation.
    m.a = k * (1 + w1);
    m.b = k * w2;
    m.c = k * w2;
    m.d = k * (1 - w1);
    view.light.setFromMatrix(m);
    view.light.alpha = alpha;
  }
}

const fract = (x: number): number => x - Math.floor(x);
