import { Particle, ParticleContainer, type Texture } from 'pixi.js';
import type { EffectFrameName } from './art';
import { hslToRgb, mixRgb, rgbToBgr } from './color';

/** Hard cap on live particles; a pop uses about 20, so this covers a couple dozen at once. */
export const MAX_PARTICLES = 512;

const RING = 0;
const FLASH = 1;
const DROPLET = 2;
const SPARK = 3;

/** Radius of each effect's visible shape inside its atlas cell, in texels. */
const RING_RADIUS_PX = 0.84 * 128;
const FLASH_RADIUS_PX = 0.6 * 64;
const DROPLET_RADIUS_PX = 0.78 * 32;
const SPARK_RADIUS_PX = 0.6 * 32;

const RING_LIFE_S = 0.3;
const FLASH_LIFE_S = 0.14;
const DROPLET_LIFE_S = [0.26, 0.4] as const;
const SPARK_LIFE_S = 0.34;
/** Droplet physics, world units and seconds. */
const GRAVITY = 1400;
const DRAG = 3.2;

/**
 * Pop bursts: a flash and an expanding ring at the bubble, droplets flung outward from the
 * rim, and a few glints. Everything is sized to the bubble and gone within 0.4 s. Particles
 * are a fixed pool that never leaves the container (dead ones are invisible) with their
 * state in typed arrays, so bursts and updates create no objects of their own.
 */
export class PopEffects {
  readonly container: ParticleContainer;

  private readonly textures: Record<EffectFrameName, Texture>;
  private readonly particles: Particle[] = [];
  private readonly kind = new Uint8Array(MAX_PARTICLES);
  private readonly age = new Float32Array(MAX_PARTICLES);
  private readonly life = new Float32Array(MAX_PARTICLES);
  private readonly vx = new Float32Array(MAX_PARTICLES);
  private readonly vy = new Float32Array(MAX_PARTICLES);
  /** Ring/flash: start and end radius. Droplet/spark: radius, unused. */
  private readonly size0 = new Float32Array(MAX_PARTICLES);
  private readonly size1 = new Float32Array(MAX_PARTICLES);
  private readonly spin = new Float32Array(MAX_PARTICLES);
  private readonly bgr = new Uint32Array(MAX_PARTICLES);
  /** Slots in use, packed; and the free slots as a stack. */
  private readonly live = new Int32Array(MAX_PARTICLES);
  private liveCount = 0;
  private readonly free = new Int32Array(MAX_PARTICLES);
  private freeCount = MAX_PARTICLES;
  private readonly random: () => number;

  constructor(textures: Record<EffectFrameName, Texture>, random: () => number = Math.random) {
    this.textures = textures;
    this.random = random;
    this.container = new ParticleContainer({
      // Slots are reused for different effects, so texture frames (uvs) change too.
      dynamicProperties: { vertex: true, position: true, rotation: true, uvs: true, color: true },
    });
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const particle = new Particle({ texture: textures.droplet, anchorX: 0.5, anchorY: 0.5 });
      hide(particle);
      this.particles.push(particle);
      this.free[i] = MAX_PARTICLES - 1 - i;
    }
    this.container.addParticle(...this.particles);
    this.container.visible = false;
  }

  get count(): number {
    return this.liveCount;
  }

  /** Start a pop burst for a bubble of radius `r` at (x, y). */
  burst(x: number, y: number, r: number, hue: number): void {
    const random = this.random;
    const tint = hslToRgb(hue, 0.95, 0.66);
    const pale = rgbToBgr(mixRgb(0xffffff, tint, 0.3));
    const vivid = rgbToBgr(mixRgb(0xffffff, tint, 0.75));
    // A second colour a third of the way round the wheel, like the film's own bands.
    const accent = rgbToBgr(mixRgb(0xffffff, hslToRgb(hue + 120, 0.95, 0.66), 0.7));

    this.spawn(FLASH, x, y, 0, 0, r * 0.6, r * 1.1, 0, FLASH_LIFE_S, pale);
    this.spawn(RING, x, y, 0, 0, r * 0.95, r * 1.55, 0, RING_LIFE_S, vivid);

    const droplets = Math.min(24, Math.max(12, Math.round(10 + r / 8)));
    const offset = random() * 2 * Math.PI;
    for (let i = 0; i < droplets; i++) {
      // Stratified around the rim so there are no gaps, but jittered across the whole slot
      // and at mixed speeds and starting depths, so the spray never looks like a clock face.
      const angle = offset + (2 * Math.PI * (i + random())) / droplets;
      const cos = Math.cos(angle);
      const sin = Math.sin(angle);
      const speed = r * (1.3 + 3.2 * random() * random()) + 50;
      const start = r * (0.7 + 0.28 * random());
      const life = DROPLET_LIFE_S[0] + (DROPLET_LIFE_S[1] - DROPLET_LIFE_S[0]) * random();
      const radius = r * (0.035 + 0.07 * random() * random()) + 3;
      const pick = random();
      const color = pick < 0.3 ? pale : pick < 0.75 ? vivid : accent;
      this.spawn(
        DROPLET,
        x + cos * start,
        y + sin * start,
        cos * speed,
        sin * speed - r * 0.6,
        radius,
        0,
        0,
        life,
        color,
      );
    }

    const sparks = r > 70 ? 4 : 3;
    for (let i = 0; i < sparks; i++) {
      const angle = random() * 2 * Math.PI;
      const cos = Math.cos(angle);
      const sin = Math.sin(angle);
      const speed = r * (0.6 + 0.6 * random());
      this.spawn(
        SPARK,
        x + cos * r * (0.6 + 0.35 * random()),
        y + sin * r * (0.6 + 0.35 * random()),
        cos * speed,
        sin * speed,
        r * (0.16 + 0.1 * random()) + 8,
        0,
        (random() * 2 - 1) * 6,
        SPARK_LIFE_S * (0.8 + 0.4 * random()),
        0xffffff,
      );
    }
    this.container.visible = this.liveCount > 0;
  }

  update(dtS: number): void {
    const decay = Math.exp(-DRAG * dtS);
    for (let n = this.liveCount - 1; n >= 0; n--) {
      const i = this.live[n] as number;
      const age = (this.age[i] as number) + dtS;
      const life = this.life[i] as number;
      const particle = this.particles[i] as Particle;
      if (age >= life) {
        hide(particle);
        this.live[n] = this.live[this.liveCount - 1] as number;
        this.liveCount--;
        this.free[this.freeCount++] = i;
        continue;
      }
      this.age[i] = age;
      const t = age / life;
      let alpha = 1;
      switch (this.kind[i]) {
        case RING: {
          const e = 1 - (1 - t) ** 3;
          const radius =
            (this.size0[i] as number) + ((this.size1[i] as number) - (this.size0[i] as number)) * e;
          particle.scaleX = particle.scaleY = radius / RING_RADIUS_PX;
          alpha = (1 - t) * (1 - t);
          break;
        }
        case FLASH: {
          const radius =
            (this.size0[i] as number) + ((this.size1[i] as number) - (this.size0[i] as number)) * t;
          particle.scaleX = particle.scaleY = radius / FLASH_RADIUS_PX;
          alpha = 0.55 * (1 - t) * (1 - t);
          break;
        }
        case DROPLET: {
          const vx = (this.vx[i] as number) * decay;
          const vy = (this.vy[i] as number) * decay + GRAVITY * dtS;
          this.vx[i] = vx;
          this.vy[i] = vy;
          particle.x += vx * dtS;
          particle.y += vy * dtS;
          const radius = (this.size0[i] as number) * (1 - 0.45 * t);
          // Streak along the motion while fast, settle into a bead as it slows.
          const speed = Math.sqrt(vx * vx + vy * vy);
          const stretch = 1 + Math.min(1.4, speed / (radius * 30 + 1));
          const base = radius / DROPLET_RADIUS_PX;
          particle.scaleX = base * stretch;
          particle.scaleY = base / Math.sqrt(stretch);
          particle.rotation = Math.atan2(vy, vx);
          alpha = t < 0.45 ? 1 : 1 - (t - 0.45) / 0.55;
          break;
        }
        default: {
          const vx = (this.vx[i] as number) * decay;
          const vy = (this.vy[i] as number) * decay;
          this.vx[i] = vx;
          this.vy[i] = vy;
          particle.x += vx * dtS;
          particle.y += vy * dtS;
          particle.rotation += (this.spin[i] as number) * dtS;
          const twinkle = Math.sin(Math.PI * t);
          particle.scaleX = particle.scaleY =
            ((this.size0[i] as number) / SPARK_RADIUS_PX) * twinkle;
          alpha = twinkle;
        }
      }
      particle.color = (this.bgr[i] as number) + (((alpha * 255) | 0) << 24);
    }
    this.container.visible = this.liveCount > 0;
  }

  /** Remove every live particle (e.g. on reset). */
  clear(): void {
    for (let n = 0; n < this.liveCount; n++) {
      const i = this.live[n] as number;
      hide(this.particles[i] as Particle);
      this.free[this.freeCount++] = i;
    }
    this.liveCount = 0;
    this.container.visible = false;
  }

  dispose(): void {
    this.clear();
    this.container.destroy();
    this.particles.length = 0;
  }

  private spawn(
    kind: number,
    x: number,
    y: number,
    vx: number,
    vy: number,
    size0: number,
    size1: number,
    spin: number,
    life: number,
    bgr: number,
  ): void {
    // At the cap a burst simply gets fewer particles; nothing older is cut short.
    if (this.freeCount === 0) return;
    const i = this.free[--this.freeCount] as number;
    this.live[this.liveCount++] = i;
    const particle = this.particles[i] as Particle;
    particle.texture = this.textureFor(kind);
    particle.x = x;
    particle.y = y;
    particle.rotation = kind === SPARK ? this.random() * Math.PI : 0;
    particle.scaleX = 0;
    particle.scaleY = 0;
    particle.color = bgr;
    this.kind[i] = kind;
    this.age[i] = 0;
    this.life[i] = life;
    this.vx[i] = vx;
    this.vy[i] = vy;
    this.size0[i] = size0;
    this.size1[i] = size1;
    this.spin[i] = spin;
    this.bgr[i] = bgr;
  }

  private textureFor(kind: number): Texture {
    switch (kind) {
      case RING:
        return this.textures.ring;
      case FLASH:
        return this.textures.flash;
      case DROPLET:
        return this.textures.droplet;
      default:
        return this.textures.spark;
    }
  }
}

function hide(particle: Particle): void {
  particle.scaleX = 0;
  particle.scaleY = 0;
  particle.color = 0;
}
