/** Small helpers shared by the HUD, the panel and the recorder. */

/** `m:ss`. */
export function formatDuration(ms: number): string {
  const totalS = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(totalS / 60)}:${String(totalS % 60).padStart(2, '0')}`;
}

export function formatBytes(bytes: number): string {
  return bytes < 1_000_000
    ? `${Math.round(bytes / 1000)} kB`
    : `${(bytes / 1_000_000).toFixed(1)} MB`;
}

export function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
  return typeof (value as { then?: unknown } | null | undefined)?.then === 'function';
}

const VIDEO_EXTENSION = /\.(webm|mp4|m4v|mov|mkv|ogv)$/i;

/** Browsers leave `type` empty for some containers (.mkv), so the extension counts too. */
export function isVideoFile(file: { name: string; type: string }): boolean {
  return file.type.startsWith('video/') || VIDEO_EXTENSION.test(file.name);
}
