/**
 * Where new bubbles enter and which way they head. Bubbles always start just off screen so
 * they never appear on top of a player, and every heading is chosen so the bubble crosses
 * the band of heights that both small and tall children can reach before it leaves.
 *
 * Spawning is two steps. `planSpawn` makes the random choices that set the mix of bubbles
 * (edge, size, low or high); `placeSpawn` then looks for room on that edge and may fail when
 * it is crowded, in which case the caller retries the same plan on a later step. Keeping the
 * plan across retries means crowding can delay a spawn but never skew the mix.
 */
import type { Tunables } from '../config/tunables';
import type { Rng } from '../core/rng';
import type { ViewTransform } from '../core/view';
import { SEPARATION_GAP } from './motion';

/** Heights (fractions of world height) reachable by both small and tall children. */
export const REACH_TOP = 0.45;
export const REACH_BOTTOM = 0.85;
/** Share of side entries in the lower two thirds of the screen. */
const SIDE_LOW_SHARE = 0.8;
/** Steepest heading: top entries within 25° of straight down, side entries of level. */
const MAX_SLOPE = Math.tan((25 * Math.PI) / 180);
/** Side entries are inside the reachable band by this fraction of the way across. */
const SIDE_REACH_BY = 0.6;
/** Top entries aim at a point on the bottom edge inside this inset, so they head inwards. */
const TOP_AIM_INSET = 0.15;
/** Gap between a new bubble's edge and the screen edge, as a fraction of its radius. */
const SPAWN_GAP = 0.2;
/** Entry points tried per attempt; the one with most room around it wins. */
const ENTRY_CANDIDATES = 4;

export type EntryEdge = 'top' | 'left' | 'right';

export interface SpawnPlan {
  edge: EntryEdge;
  r: number;
  /** Side entries only: enter in the lower two thirds of the screen. */
  low: boolean;
}

export interface Entry {
  x: number;
  y: number;
  /** Unit heading. */
  dirX: number;
  dirY: number;
}

interface Circle {
  readonly x: number;
  readonly y: number;
  readonly r: number;
}

/** Make the random choices for the next bubble, writing into `out`. */
export function planSpawn(rng: Rng, tunables: Tunables, out: SpawnPlan): void {
  const side = rng.chance(tunables.sideEntryFraction);
  out.edge = !side ? 'top' : rng.chance(0.5) ? 'left' : 'right';
  out.r = rng.range(
    Math.min(tunables.radiusMin, tunables.radiusMax),
    Math.max(tunables.radiusMin, tunables.radiusMax),
  );
  out.low = rng.chance(SIDE_LOW_SHARE);
}

/**
 * Find an entry point for `plan` that is clear of every other bubble's push zone, so a new
 * bubble neither stacks on a recent one nor shoves it, and write it with a heading into
 * `out`. Returns false when every candidate is crowded.
 */
export function placeSpawn(
  rng: Rng,
  plan: SpawnPlan,
  view: ViewTransform,
  others: readonly Circle[],
  out: Entry,
): boolean {
  const { edge, r } = plan;
  const width = view.worldWidth;
  const height = view.worldHeight;
  const offset = r * (1 + SPAWN_GAP);

  // The span along the entry edge.
  let lo: number;
  let hi: number;
  if (edge === 'top') {
    lo = Math.min(r, width / 2);
    hi = Math.max(width - r, width / 2);
  } else {
    // Clear of the top and bottom so the disc can become fully visible, and on a narrow
    // screen close enough to the reachable band to reach it before crossing.
    const reach = 0.9 * MAX_SLOPE * width;
    lo = Math.max(r, REACH_TOP * height - reach);
    hi = Math.max(lo, Math.min(height - r, REACH_BOTTOM * height + reach));
    const split = Math.min(hi, Math.max(lo, height / 3));
    if (plan.low || split <= lo) lo = split;
    else hi = split;
  }

  let bestRoom = 1;
  let found = false;
  for (let k = 0; k < ENTRY_CANDIDATES; k++) {
    const along = rng.range(lo, hi);
    const x = edge === 'top' ? along : edge === 'left' ? -offset : width + offset;
    const y = edge === 'top' ? -offset : along;
    const room = spacing(x, y, r, others);
    if (room >= bestRoom) {
      bestRoom = room;
      found = true;
      out.x = x;
      out.y = y;
    }
  }
  if (!found) return false;

  if (edge === 'top') {
    // Falls through every height; aiming inwards keeps it from leaving by a side first.
    const aimX = rng.range(TOP_AIM_INSET * width, (1 - TOP_AIM_INSET) * width);
    setHeading(out, clamp((aimX - out.x) / height, -MAX_SLOPE, MAX_SLOPE), 1);
  } else {
    // Mostly sideways. The height at the far edge is chosen so that the bubble is inside the
    // reachable band by SIDE_REACH_BY of the way across, yet still leaves by the far side
    // rather than through the floor or ceiling. If the slope limit makes that impossible
    // (only on narrow screens), it heads for the band as steeply as allowed.
    const y0 = out.y;
    const run = width + offset;
    const steepLo = Math.max(r, y0 - MAX_SLOPE * run);
    const steepHi = Math.min(height - r, y0 + MAX_SLOPE * run);
    const bandLo = y0 + (REACH_TOP * height - y0) / SIDE_REACH_BY;
    const bandHi = y0 + (REACH_BOTTOM * height - y0) / SIDE_REACH_BY;
    const farLo = clamp(bandLo, steepLo, steepHi);
    const farHi = clamp(bandHi, steepLo, steepHi);
    setHeading(out, edge === 'left' ? 1 : -1, (rng.range(farLo, farHi) - y0) / run);
  }
  return true;
}

/**
 * Distance to the most crowding neighbour, relative to where the push between the two
 * starts: 1 is the edge of the push zone, larger is clear.
 */
function spacing(x: number, y: number, r: number, others: readonly Circle[]): number {
  let room = Number.POSITIVE_INFINITY;
  for (let i = 0; i < others.length; i++) {
    const other = others[i] as Circle;
    const zone = (other.r + r) * (1 + SEPARATION_GAP);
    room = Math.min(room, Math.hypot(other.x - x, other.y - y) / zone);
  }
  return room;
}

function setHeading(out: Entry, dx: number, dy: number): void {
  const length = Math.hypot(dx, dy);
  out.dirX = dx / length;
  out.dirY = dy / length;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
