/**
 * How much of a bubble the person mask covers.
 *
 * A world-space disc maps to an axis-aligned ellipse in mask space (texels are only square
 * for tiled masks), so each mask row inside it is one contiguous span and the cost is one
 * square root per row plus one read per texel.
 */
import type { Tunables } from '../config/tunables';
import type { PersonMask } from '../core/mask';
import { type ViewTransform, worldToMaskU, worldToMaskV } from '../core/view';

/** Floor on the pop threshold so a zero `popFraction` cannot divide by zero. */
const MIN_POP_AREA = 1;

/** Covered area (world units²) at which a bubble of radius `r` pops. */
export function popThresholdArea(r: number, tunables: Tunables): number {
  // The absolute term lets a hand pop a big bubble: a fraction alone would need a torso.
  return Math.max(
    MIN_POP_AREA,
    Math.min(tunables.popFraction * Math.PI * r * r, tunables.popAreaAbs),
  );
}

/**
 * Measures discs against one mask at a time. Results land in fields rather than a returned
 * object so that measuring every bubble on every mask allocates nothing.
 */
export class DiscProbe {
  /** On-screen texels whose centre lies inside the disc (last `measure`). */
  texels = 0;
  /** Of those, the ones at or above the threshold and not ignored as static. */
  covered = 0;
  /** World units² per texel of the current mask. */
  texelArea = 0;

  private view: ViewTransform | null = null;
  private data: Uint8Array = new Uint8Array(0);
  private ignored: Uint8Array | null = null;
  private width = 0;
  private threshold = 0;
  private scaleX = 1;
  private scaleY = 1;
  /** Inclusive texel ranges whose centres are on screen; cropped texels never count. */
  private uMin = 0;
  private uMax = -1;
  private vMin = 0;
  private vMax = -1;

  /**
   * @param ignored Per texel of `mask`, 1 where "person" does not count (static), or null.
   * @param threshold Probability (0..1) at which a texel counts as person.
   */
  setMask(
    view: ViewTransform,
    mask: PersonMask,
    ignored: Uint8Array | null,
    threshold: number,
  ): void {
    this.view = view;
    // A mask always covers the whole source frame, so one that arrives before setView has
    // caught up with its size can still be read by rescaling the view's texel coordinates.
    this.scaleX = mask.width / view.maskWidth;
    this.scaleY = mask.height / view.maskHeight;
    this.texelArea = view.maskTexelArea / (this.scaleX * this.scaleY);
    this.data = mask.data;
    this.width = mask.width;
    this.ignored = ignored && ignored.length === mask.data.length ? ignored : null;
    this.threshold = threshold * 255;

    // Texel i is centred on i + 0.5. Mirroring makes the u range run backwards.
    const left = worldToMaskU(view, 0) * this.scaleX;
    const right = worldToMaskU(view, view.worldWidth) * this.scaleX;
    this.uMin = Math.max(0, Math.ceil(Math.min(left, right) - 0.5));
    this.uMax = Math.min(mask.width - 1, Math.floor(Math.max(left, right) - 0.5));
    this.vMin = Math.max(0, Math.ceil(worldToMaskV(view, 0) * this.scaleY - 0.5));
    this.vMax = Math.min(
      mask.height - 1,
      Math.floor(worldToMaskV(view, view.worldHeight) * this.scaleY - 0.5),
    );
  }

  /** Measure the disc at (x, y) of radius r. */
  measure(x: number, y: number, r: number): void {
    let texels = 0;
    let covered = 0;
    const view = this.view;
    if (view && r > 0) {
      const data = this.data;
      const ignored = this.ignored;
      const threshold = this.threshold;
      const cu = worldToMaskU(view, x) * this.scaleX;
      const cv = worldToMaskV(view, y) * this.scaleY;
      const ru = Math.abs(view.maskScaleX * this.scaleX) * r;
      const rv = view.maskScaleY * this.scaleY * r;
      const vFirst = Math.max(this.vMin, Math.ceil(cv - rv - 0.5));
      const vLast = Math.min(this.vMax, Math.floor(cv + rv - 0.5));
      for (let v = vFirst; v <= vLast; v++) {
        const dv = (v + 0.5 - cv) / rv;
        const half = ru * Math.sqrt(Math.max(0, 1 - dv * dv));
        const uFirst = Math.max(this.uMin, Math.ceil(cu - half - 0.5));
        const uLast = Math.min(this.uMax, Math.floor(cu + half - 0.5));
        if (uLast < uFirst) continue;
        const start = v * this.width + uFirst;
        const end = v * this.width + uLast;
        texels += uLast - uFirst + 1;
        if (ignored) {
          for (let i = start; i <= end; i++) {
            if ((data[i] as number) >= threshold && ignored[i] === 0) covered++;
          }
        } else {
          for (let i = start; i <= end; i++) {
            if ((data[i] as number) >= threshold) covered++;
          }
        }
      }
    }
    this.texels = texels;
    this.covered = covered;
  }
}
