/**
 * What the two segmenter backends (worker and main thread) share: their options, their
 * failure type and their time limits. `ResilientSegmenter` creates backends from these and
 * decides when one has to be replaced; a backend only reports what happened.
 */
import type { Delegate, FaultSpec, RegionLayout, SegmenterEngine } from './protocol';
import { type Segmenter, VisionError } from './types';

/**
 * Compiling the WASM runtime, loading the model and the warm-up inference, on a slow
 * machine. Downloads are not part of it: they happen before, with a stall timeout.
 */
export const INIT_TIMEOUT_MS = 30_000;
/** A frame normally takes ~25 ms; this long without a reply means the backend is wedged. */
export const SEGMENT_TIMEOUT_MS = 1_500;
/**
 * A timeout that fires this much later than scheduled means the main thread itself was
 * stalled (hidden tab, long task), so the backend's silence proves nothing yet.
 */
export const LATE_TIMER_MS = 250;

/** MediaPipe ships one WASM build for module workers and a classic one for the page. */
export type WasmBuild = 'module' | 'classic';

export interface WasmFiles {
  /** Absolute, versioned URL of the loader script. */
  loaderUrl: string;
  /** The binary, already downloaded, typed `application/wasm`. */
  binary: Blob;
}

export interface BackendOptions {
  engine: SegmenterEngine;
  delegate: Delegate;
  /**
   * The WASM files for `build`, downloading the binary if it is not in hand yet (with a
   * stall timeout). Only called for the `mediapipe` engine, before the init timeout starts.
   */
  loadWasm(build: WasmBuild): Promise<WasmFiles>;
  /** Model bytes, downloaded once by the pipeline; null for the chroma engine. */
  modelBuffer: ArrayBuffer | null;
  inputSize: number;
  layout: RegionLayout;
  fault: FaultSpec | null;
  /**
   * Told the outcome of every segment call that settles while the backend is alive: null
   * for a mask, otherwise the failure. Not called for calls cut short by `dispose()`.
   */
  monitor?: (failure: SegmentFailure | null) => void;
}

/**
 * A failed segment call. `fatal` means the backend is wedged or gone (timeout, crashed
 * worker, lost GPU context) and must be replaced; otherwise only this frame failed.
 * `contextLost` says the GPU context went away, which a replacement should give the
 * browser a moment to recover from.
 */
export class SegmentFailure extends VisionError {
  readonly fatal: boolean;
  readonly contextLost: boolean;

  constructor(
    message: string,
    fatal: boolean,
    options?: { cause?: unknown; contextLost?: boolean },
  ) {
    super('segmenter-failed', message, options);
    this.fatal = fatal;
    this.contextLost = options?.contextLost ?? false;
  }
}

export interface Backend extends Segmenter {
  /** Hand back a mask buffer nobody has seen, so the next result can reuse it. */
  recycle(data: Uint8Array): void;
}
