import {
  DEFAULT_TUNABLES,
  TUNABLE_SPECS,
  TUNABLES_VERSION,
  type TunableKey,
  type Tunables,
} from './tunables';

const STORAGE_KEY = 'bubble-game.tunables';

interface Saved {
  version: number;
  values: Partial<Record<TunableKey, unknown>>;
}

/** Copy valid, in-range values from `source` onto `target`. Unknown keys and bad types are ignored. */
export function applyTunableValues(target: Tunables, source: Record<string, unknown>): void {
  const writable = target as unknown as Record<string, number | boolean>;
  for (const key of Object.keys(TUNABLE_SPECS) as TunableKey[]) {
    const value = source[key];
    const spec = TUNABLE_SPECS[key];
    if (spec.kind === 'boolean') {
      if (typeof value === 'boolean') writable[key] = value;
    } else if (typeof value === 'number' && Number.isFinite(value)) {
      writable[key] = Math.min(spec.max, Math.max(spec.min, value));
    }
  }
}

/** Load saved values into `target`. Saves from an older schema version are discarded. */
export function loadSavedTunables(target: Tunables): void {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return;
    const saved = JSON.parse(raw) as Saved;
    if (saved?.version !== TUNABLES_VERSION || typeof saved.values !== 'object') {
      localStorage.removeItem(STORAGE_KEY);
      return;
    }
    applyTunableValues(target, saved.values as Record<string, unknown>);
  } catch {
    // Storage unavailable or corrupt: run with defaults.
  }
}

/** Persist only the values that differ from the defaults. */
export function saveTunables(tunables: Tunables): void {
  try {
    const values: Partial<Record<TunableKey, unknown>> = {};
    for (const key of Object.keys(TUNABLE_SPECS) as TunableKey[]) {
      if (tunables[key] !== DEFAULT_TUNABLES[key]) values[key] = tunables[key];
    }
    const saved: Saved = { version: TUNABLES_VERSION, values };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // Ignore: persistence is a convenience.
  }
}

export function resetTunables(tunables: Tunables): void {
  Object.assign(tunables, DEFAULT_TUNABLES);
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // Ignore.
  }
}

/** JSON of the values that differ from defaults, for pasting into a chat or issue. */
export function tunablesDiffJson(tunables: Tunables): string {
  const diff: Partial<Record<TunableKey, unknown>> = {};
  for (const key of Object.keys(TUNABLE_SPECS) as TunableKey[]) {
    if (tunables[key] !== DEFAULT_TUNABLES[key]) diff[key] = tunables[key];
  }
  return JSON.stringify(diff, null, 2);
}
