/**
 * Which parts of a frame are fed to the model, and where each result lands in the mask.
 *
 * The model takes a square input and only segments people well when they are undistorted
 * and reasonably large in that input. So instead of squashing the whole wide frame into one
 * square, the default layout runs it on overlapping square tiles and stitches the results.
 *
 * Pure and worker-safe: no DOM.
 */

export type RegionLayout =
  /** One inference on the whole frame squashed to a square (non-square mask texels). */
  | { mode: 'stretch' }
  /**
   * Square tiles, neighbours overlapping by at least `minOverlap` of a tile.
   *
   * `tileHeight` 1 covers the whole frame. Tiles are as large as the frame's shorter side
   * allows: a landscape frame gets one row of them, a portrait frame one column, a square
   * frame a single tile.
   *
   * `tileHeight` below 1 zooms in so people look larger to the model: tiles are that
   * fraction of the frame height on a side (at most the frame width), in one row anchored
   * to the bottom of the frame. The strip above that row is deliberately left uncovered.
   */
  | { mode: 'tiles'; tileHeight: number; minOverlap: number };

export const DEFAULT_LAYOUT: RegionLayout = { mode: 'tiles', tileHeight: 1, minOverlap: 0.2 };

export interface Region {
  /** Source rectangle in frame pixels. */
  sx: number;
  sy: number;
  sw: number;
  sh: number;
  /** Top-left texel in the stitched mask where this region's `inputSize`² result goes. */
  dx: number;
  dy: number;
}

export interface RegionPlan {
  /** Size of the stitched mask covering the whole frame. */
  maskWidth: number;
  maskHeight: number;
  regions: Region[];
}

export function layoutsEqual(a: RegionLayout, b: RegionLayout): boolean {
  if (a.mode === 'stretch' || b.mode === 'stretch') return a.mode === b.mode;
  return a.tileHeight === b.tileHeight && a.minOverlap === b.minOverlap;
}

export function planRegions(
  layout: RegionLayout,
  frameWidth: number,
  frameHeight: number,
  inputSize: number,
): RegionPlan {
  if (layout.mode === 'stretch') {
    return {
      maskWidth: inputSize,
      maskHeight: inputSize,
      regions: [{ sx: 0, sy: 0, sw: frameWidth, sh: frameHeight, dx: 0, dy: 0 }],
    };
  }

  const fraction = Math.min(1, Math.max(0.3, layout.tileHeight));
  const overlap = Math.min(0.8, Math.max(0, layout.minOverlap));
  // Tile side in frame pixels; never wider than the frame. At `tileHeight` 1 it is the
  // shorter side, so a portrait frame is covered by a column of tiles.
  const side = Math.max(1, Math.min(Math.round(fraction * frameHeight), frameWidth));
  // Texels per frame pixel: every tile maps `side` pixels onto `inputSize` texels.
  const scale = inputSize / side;
  const maskWidth = Math.max(inputSize, Math.round(frameWidth * scale));
  const maskHeight = Math.max(inputSize, Math.round(frameHeight * scale));

  const columns = spans(frameWidth, side, overlap, maskWidth, inputSize, 0.5);
  // Zoomed tiles sit in one row at the bottom, where a standing player's body is.
  const rows =
    fraction < 1
      ? [{ start: frameHeight - side, dest: maskHeight - inputSize }]
      : spans(frameHeight, side, overlap, maskHeight, inputSize, 1);

  const regions: Region[] = [];
  for (const row of rows) {
    for (const column of columns) {
      regions.push({
        sx: column.start,
        sy: row.start,
        sw: side,
        sh: side,
        dx: column.dest,
        dy: row.dest,
      });
    }
  }
  return { maskWidth, maskHeight, regions };
}

/**
 * Positions along one axis for tiles of `side` pixels covering `length` pixels, with at
 * least `overlap` of a tile shared between neighbours. A single tile that is shorter than
 * the axis sits at `alone` (0 start, 0.5 centre, 1 end).
 */
function spans(
  length: number,
  side: number,
  overlap: number,
  maskLength: number,
  inputSize: number,
  alone: number,
): Array<{ start: number; dest: number }> {
  const count =
    length <= side ? 1 : Math.max(2, Math.ceil((length - side * overlap) / (side * (1 - overlap))));
  const result: Array<{ start: number; dest: number }> = [];
  for (let i = 0; i < count; i++) {
    const t = count === 1 ? alone : i / (count - 1);
    result.push({
      start: Math.round(t * (length - side)),
      // Derived from the same fraction so the outer tiles land exactly on the mask edges
      // regardless of rounding.
      dest: Math.round(t * (maskLength - inputSize)),
    });
  }
  return result;
}
