import { type Backend, type BackendOptions, SEGMENT_TIMEOUT_MS, SegmentFailure } from './backend';
import { GpuContextLost, injectedFault, type RegionLayout } from './protocol';
import type { SegmenterCore } from './segmenterCore';
import { type SegmenterInfo, type SegmentResult, type StartProgress, VisionError } from './types';

interface Job {
  frame: VideoFrame;
  resolve(result: SegmentResult): void;
  reject(error: VisionError): void;
}

/**
 * The same segmenter core as the worker, run on the main thread: the fallback when the
 * worker cannot start or keeps failing. Each frame blocks the main thread for the whole
 * inference, so it runs in its own task rather than inside the caller's frame callback,
 * letting the frame that triggered it paint first.
 *
 * Like the worker, one instance is never restarted in place; the owner replaces it.
 */
export class MainThreadSegmenter implements Backend {
  info: SegmenterInfo | null = null;

  private core: SegmenterCore | null = null;
  private readonly queue: Job[] = [];
  private scheduled = false;
  private spare: Uint8Array | null = null;
  private segmentCalls = 0;
  private broken = false;
  private disposed = false;
  private started = false;
  /** Calls swallowed by an injected hang: their timeout timers and how to reject them. */
  private readonly hung = new Map<ReturnType<typeof setTimeout>, (error: VisionError) => void>();

  constructor(private readonly options: BackendOptions) {}

  async init(onProgress?: (progress: StartProgress) => void): Promise<SegmenterInfo> {
    if (this.started || this.disposed) {
      throw new VisionError('segmenter-init', 'A segmenter can only be started once.');
    }
    this.started = true;
    const { options } = this;
    let core: SegmenterCore;
    try {
      // The classic build: the ES-module one only works inside a module worker.
      const wasm = options.engine === 'mediapipe' ? await options.loadWasm('classic') : null;
      onProgress?.({ stage: 'wasm', fraction: null });
      // Loaded on demand: this fallback is rare, and a static import would put the whole
      // MediaPipe runtime in the main bundle that every visitor downloads.
      const { createSegmenterCore } = await import('./segmenterCore');
      core = await createSegmenterCore(
        {
          engine: options.engine,
          delegate: options.delegate,
          wasmLoaderUrl: wasm?.loaderUrl ?? '',
          wasmBinary: wasm?.binary ?? null,
          modelBuffer: options.modelBuffer,
          inputSize: options.inputSize,
          layout: options.layout,
          fault: options.fault,
        },
        () => onProgress?.({ stage: 'warmup', fraction: null }),
      );
    } catch (cause) {
      throw new VisionError('segmenter-init', describe(cause), { cause });
    }
    if (this.disposed) {
      core.dispose();
      throw new VisionError('segmenter-init', 'The segmenter was stopped.');
    }
    this.core = core;
    this.info = { backend: 'main', ...core.info };
    return this.info;
  }

  setLayout(layout: RegionLayout): void {
    this.spare = null;
    this.core?.setLayout(layout);
  }

  segment(frame: VideoFrame): Promise<SegmentResult> {
    if (!this.core || this.broken) {
      frame.close();
      return Promise.reject(new SegmentFailure('The segmenter is not running.', true));
    }
    return new Promise<SegmentResult>((resolve, reject) => {
      const injected = injectedFault(this.options.fault, ++this.segmentCalls);
      if (injected === 'hang') {
        // Nothing on the main thread can really hang without freezing the page, so a hang
        // is a job that never runs, caught by the same deadline the worker has.
        frame.close();
        const timer = setTimeout(() => {
          this.hung.delete(timer);
          this.broken = true;
          this.fail(reject, new SegmentFailure('The segmenter stopped responding.', true));
        }, SEGMENT_TIMEOUT_MS);
        this.hung.set(timer, reject);
        return;
      }
      if (injected === 'throw') {
        frame.close();
        queueMicrotask(() => this.fail(reject, new SegmentFailure('injected fault', false)));
        return;
      }
      this.queue.push({ frame, resolve, reject });
      if (!this.scheduled) {
        this.scheduled = true;
        setTimeout(this.runQueue, 0);
      }
    });
  }

  recycle(data: Uint8Array): void {
    this.spare = data;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    const stopped = new SegmentFailure('The segmenter was stopped.', true);
    for (const [timer, reject] of this.hung) {
      clearTimeout(timer);
      reject(stopped);
    }
    this.hung.clear();
    for (const job of this.queue.splice(0)) {
      job.frame.close();
      job.reject(stopped);
    }
    this.core?.dispose();
    this.core = null;
  }

  private readonly runQueue = (): void => {
    this.scheduled = false;
    for (let job = this.queue.shift(); job; job = this.queue.shift()) {
      const { core } = this;
      if (!core) {
        job.frame.close();
        job.reject(new SegmentFailure('The segmenter was stopped.', true));
        continue;
      }
      const out = this.spare;
      this.spare = null;
      let result: SegmentResult;
      try {
        // core.segment closes the frame in every outcome.
        result = core.segment(job.frame, out);
      } catch (cause) {
        const contextLost = cause instanceof GpuContextLost;
        if (contextLost) this.broken = true;
        this.fail(
          job.reject,
          new SegmentFailure(describe(cause), contextLost, { cause, contextLost }),
        );
        continue;
      }
      job.resolve(result);
      this.options.monitor?.(null);
    }
  };

  private fail(reject: (error: VisionError) => void, failure: SegmentFailure): void {
    reject(failure);
    if (!this.disposed) this.options.monitor?.(failure);
  }
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
