/**
 * CONTRACT for the vision module (main-thread side). The rest of the app depends only on
 * this file and on `createVision` / `listCameras` exported from `./index`.
 */
import type { Unsubscribe } from '../core/events';
import type { PersonMask } from '../core/mask';
import type { Delegate, FaultSpec, RegionLayout, SegmenterEngine } from './protocol';

export type { Delegate, FaultSpec, RegionLayout, SegmenterEngine } from './protocol';

// ---------------------------------------------------------------------------
// Sources
// ---------------------------------------------------------------------------

export type SourceKind = 'camera' | 'clip' | 'synthetic';

/** Element the renderer shows: a <video> for camera/clip, a <canvas> for synthetic. */
export type DisplaySource = HTMLVideoElement | HTMLCanvasElement;

export interface SourceInfo {
  kind: SourceKind;
  /** Actual frame size in pixels. */
  width: number;
  height: number;
  /** Actual frame rate reported by the device, if known. */
  frameRate: number | null;
  label: string;
  deviceId: string | null;
}

export interface FrameTick {
  /** `performance.now()` for this frame. */
  readonly captureTimeMs: number;
  /** Snapshot the current frame. The caller owns the result and must `close()` it. */
  grab(): VideoFrame;
}

export interface FrameSource {
  readonly kind: SourceKind;
  /** Null until `start()` resolves. */
  readonly info: SourceInfo | null;
  readonly display: DisplaySource | null;
  /** Camera only: the live stream (used by the clip recorder). */
  readonly stream: MediaStream | null;
  /** Resolves once the first frame is available. Rejects with a `VisionError`. */
  start(): Promise<SourceInfo>;
  /** Stop delivering frames but keep the device open. */
  pause(): void;
  resume(): void;
  /** Release the device. The source cannot be restarted. */
  stop(): void;
  /** Called on the main thread once per new source frame. */
  setFrameHandler(handler: ((tick: FrameTick) => void) | null): void;
  /** Called if the source ends unexpectedly (camera unplugged, track ended, clip error). */
  setEndedHandler(handler: ((error: VisionError) => void) | null): void;
}

export interface CameraDevice {
  deviceId: string;
  /** Empty until camera permission has been granted. */
  label: string;
}

/** Test hook for the synthetic source: blobs are in source pixels; `null` restores the default animation. */
export interface SyntheticBlob {
  x: number;
  y: number;
  r: number;
}

export interface SyntheticControl {
  setBlobs(blobs: SyntheticBlob[] | null): void;
}

// ---------------------------------------------------------------------------
// Segmenter
// ---------------------------------------------------------------------------

export type SegmenterBackend = 'worker' | 'main';

export interface SegmenterInfo {
  backend: SegmenterBackend;
  engine: SegmenterEngine;
  delegate: Delegate;
  /** Side of the model's square input. Mask size varies with layout and frame aspect. */
  inputSize: number;
  glRenderer: string | null;
  warmupMs: number;
}

export interface SegmentResult {
  /** P(person) as 0..255 for the whole frame, `width * height` long. Owned by the caller. */
  data: Uint8Array;
  width: number;
  height: number;
  /** Total time for this frame, all regions. */
  inferMs: number;
  /** Number of model runs this frame took. */
  regions: number;
}

export interface Segmenter {
  readonly info: SegmenterInfo | null;
  /** Loads the model and runs a warm-up inference. Rejects with a `VisionError`. */
  init(onProgress?: (progress: StartProgress) => void): Promise<SegmenterInfo>;
  /**
   * Segment one frame. Takes ownership of `frame` and closes it in every outcome.
   * Rejects with a `VisionError`; it must never stay pending forever (implementations
   * time out).
   */
  segment(frame: VideoFrame): Promise<SegmentResult>;
  /** Change which parts of the frame are fed to the model; applies from the next frame. */
  setLayout(layout: RegionLayout): void;
  dispose(): void;
}

// ---------------------------------------------------------------------------
// Pipeline
// ---------------------------------------------------------------------------

export type StartStage = 'camera' | 'download' | 'wasm' | 'warmup';

export interface StartProgress {
  stage: StartStage;
  /** 0..1 within the stage, or null when indeterminate. */
  fraction: number | null;
}

export type VisionErrorCode =
  | 'permission-denied'
  | 'no-camera'
  | 'camera-busy'
  | 'camera-lost'
  | 'clip-failed'
  | 'model-download'
  | 'segmenter-init'
  | 'segmenter-failed'
  | 'unsupported'
  | 'unknown';

export class VisionError extends Error {
  readonly code: VisionErrorCode;

  constructor(code: VisionErrorCode, message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = 'VisionError';
    this.code = code;
  }
}

export type VisionStatus = 'idle' | 'starting' | 'running' | 'paused' | 'error' | 'disposed';

export interface VisionStats {
  /** Source frames per second, measured. */
  cameraFps: number;
  /** Masks delivered per second, measured. */
  maskFps: number;
  inferMsP50: number;
  inferMsP95: number;
  /** Age of the newest mask when it arrived: capture → available on the main thread. */
  maskAgeMs: number;
  /** VideoFrames currently open on the main thread or in flight. Should stay ≤ 2. */
  openFrames: number;
  /** Source frames skipped because the segmenter was busy. */
  droppedFrames: number;
  /** Times the segmenter was restarted or fell back. */
  restarts: number;
  masksDelivered: number;
  /** Model runs per frame with the current layout. */
  regionsPerFrame: number;
}

export interface VisionOptions {
  source: SourceKind;
  /** Preferred camera. Falls back to the default camera if it is unavailable. */
  deviceId: string | null;
  clipUrl: string | null;
  /** `auto` = worker, falling back to the main thread if the worker cannot start. */
  backend: 'auto' | SegmenterBackend;
  engine: SegmenterEngine;
  delegate: Delegate;
  fault: FaultSpec | null;
  assets: { wasmBaseUrl: string; modelUrl: string };
  /** Side of the model's square input (256 for SelfieMulticlass). */
  inputSize: number;
  layout: RegionLayout;
}

export interface FramePair {
  /** The exact frame `mask` was computed from. The taker owns it and must `close()` it. */
  image: VideoFrame;
  mask: PersonMask;
}

export interface VisionPipeline {
  readonly status: VisionStatus;
  readonly display: DisplaySource | null;
  readonly sourceInfo: SourceInfo | null;
  readonly segmenterInfo: SegmenterInfo | null;
  readonly stream: MediaStream | null;
  /** Live object, updated in place; read it whenever. */
  readonly stats: VisionStats;
  /** Present only for the synthetic source. */
  readonly synthetic: SyntheticControl | null;

  /** Open the source, load the model, run a warm-up inference. Rejects with a `VisionError`. */
  start(onProgress?: (progress: StartProgress) => void): Promise<void>;
  /** Stop processing frames (tab hidden). Keeps the camera open. Idempotent. */
  pause(): void;
  resume(): void;
  /** Release everything. Idempotent. */
  dispose(): void;

  /**
   * The newest mask that has not been taken yet, or null. The game calls this once per
   * tick; masks are never pushed into game logic from a message handler.
   */
  takeMask(): PersonMask | null;

  /** Change which parts of the frame are fed to the model; applies from the next frame. */
  setLayout(layout: RegionLayout): void;

  /** Debug: when enabled, each mask's source frame is kept so `takePair` can return it. */
  setPairing(enabled: boolean): void;
  takePair(): FramePair | null;

  /** Switch to another camera without reloading the model. */
  switchCamera(deviceId: string): Promise<SourceInfo>;
  /** Switch to a looping video clip (URL, File or Blob). */
  loadClip(src: string | Blob): Promise<SourceInfo>;

  /** Fatal runtime errors after a successful start (camera lost, segmenter dead). */
  onError(listener: (error: VisionError) => void): Unsubscribe;
  /** Fired when the source or its frame size changes after start. */
  onSourceChange(listener: (info: SourceInfo) => void): Unsubscribe;
}
