/**
 * The HUD's DOM. Rows are built once and then only their text and severity change, so a
 * refresh touches a few dozen text nodes and allocates almost nothing.
 */
import type { HudCell, HudRow, Level } from './hudModel';

interface RowView {
  label: HTMLElement;
  values: HTMLElement;
  cells: HTMLElement[];
}

export interface HudView {
  readonly element: HTMLElement;
  setRows(rows: readonly HudRow[]): void;
  /** One transient line under the stats; null clears it. */
  setNotice(text: string | null, level?: Level): void;
  /** Recording readout; null hides it. */
  setRecording(text: string | null): void;
}

function syncCell(view: HTMLElement, cell: HudCell): void {
  if (view.textContent !== cell.text) view.textContent = cell.text;
  if (view.dataset.level !== cell.level) view.dataset.level = cell.level;
  const full = cell.full ?? '';
  if (view.title !== full) {
    view.title = full;
    view.classList.toggle('dbg-hud-cell-long', full !== '');
  }
}

export function createHudView(): HudView {
  const element = document.createElement('div');
  element.className = 'dbg-hud';
  element.innerHTML = `
    <div class="dbg-hud-head"><span>Debug</span><span>D hides · drop a video to replay it</span></div>
    <div class="dbg-hud-grid"></div>
    <div class="dbg-hud-rec" hidden></div>
    <div class="dbg-hud-notice" hidden></div>
  `;
  const grid = element.querySelector<HTMLElement>('.dbg-hud-grid');
  const recording = element.querySelector<HTMLElement>('.dbg-hud-rec');
  const notice = element.querySelector<HTMLElement>('.dbg-hud-notice');
  if (!grid || !recording || !notice) throw new Error('HUD markup missing');

  const rows: RowView[] = [];

  const addRow = (): RowView => {
    const label = document.createElement('span');
    label.className = 'dbg-hud-label';
    const values = document.createElement('span');
    values.className = 'dbg-hud-values';
    grid.append(label, values);
    const row: RowView = { label, values, cells: [] };
    rows.push(row);
    return row;
  };

  return {
    element,
    setRows(next) {
      next.forEach((row, index) => {
        const view = rows[index] ?? addRow();
        if (view.label.textContent !== row.label) view.label.textContent = row.label;
        while (view.cells.length < row.cells.length) {
          const span = document.createElement('span');
          span.className = 'dbg-hud-cell';
          view.values.appendChild(span);
          view.cells.push(span);
        }
        while (view.cells.length > row.cells.length) view.cells.pop()?.remove();
        for (let i = 0; i < row.cells.length; i++) syncCell(view.cells[i], row.cells[i]);
      });
      while (rows.length > next.length) {
        const view = rows.pop();
        view?.label.remove();
        view?.values.remove();
      }
    },
    setNotice(text, level = 'ok') {
      notice.hidden = text === null;
      notice.textContent = text ?? '';
      notice.dataset.level = level;
    },
    setRecording(text) {
      recording.hidden = text === null;
      if (text !== null && recording.textContent !== text) recording.textContent = text;
    },
  };
}
