/**
 * The pop sound: a pitched "bloop" that drops fast, plus a short band-passed noise burst for
 * the wet snap of the film. Works on any BaseAudioContext so it can also be rendered
 * offline for checks.
 */

export interface PopParams {
  /** Tone pitch at the start and end of the drop. */
  startHz: number;
  endHz: number;
  /** How long the pitch takes to drop. */
  dropS: number;
  /** Tone and noise lengths (to silence). */
  toneS: number;
  noiseS: number;
  /** Centre of the noise band. */
  noiseHz: number;
  toneLevel: number;
  noiseLevel: number;
}

/** Radius (world units) that gets the reference pitch. */
const REFERENCE_RADIUS = 80;
const REFERENCE_HZ = 1050;
/** Random pitch spread, in octaves either way, so repeated pops do not sound mechanical. */
const PITCH_SPREAD_OCTAVES = 0.12;

/** Sound parameters for a bubble of `radius`. `random` is uniform in [0, 1). */
export function popParams(radius: number, random: () => number): PopParams {
  const size = Math.min(3.5, Math.max(0.25, radius / REFERENCE_RADIUS));
  // Bigger is lower, but gently: the sizes in play span about one octave.
  const pitch = REFERENCE_HZ * size ** -0.55 * 2 ** ((random() * 2 - 1) * PITCH_SPREAD_OCTAVES);
  return {
    startHz: pitch,
    endHz: pitch * (0.4 + 0.08 * random()),
    dropS: 0.045 + 0.02 * size,
    toneS: 0.11 + 0.04 * size,
    noiseS: 0.035 + 0.012 * size,
    noiseHz: Math.min(7000, Math.max(1600, pitch * (3 + random()))),
    toneLevel: 0.5 * (0.85 + 0.15 * Math.min(1, size / 2)),
    noiseLevel: 0.32,
  };
}

/** Half a second of white noise; each pop reads it from a random offset. */
export function createNoiseBuffer(context: BaseAudioContext, random: () => number): AudioBuffer {
  const buffer = context.createBuffer(1, Math.round(context.sampleRate * 0.5), context.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = random() * 2 - 1;
  return buffer;
}

/** Volume slider to gain: squared, so the slider feels even across its travel. */
export function volumeToGain(volume: number): number {
  const v = Math.min(1, Math.max(0, volume));
  return v * v;
}

export interface MasterBus {
  /** Voices connect here. Its gain is the master volume (and mute). */
  readonly input: GainNode;
  readonly compressor: DynamicsCompressorNode;
  readonly limiter: WaveShaperNode;
}

/**
 * Volume → compressor → soft limiter → destination. The compressor tames bursts of pops;
 * the limiter's curve is linear up to 0.7 and bends smoothly to never exceed 1, so even ten
 * pops on the same frame cannot clip.
 */
export function createMasterBus(context: BaseAudioContext): MasterBus {
  const input = context.createGain();
  const compressor = context.createDynamicsCompressor();
  compressor.threshold.value = -18;
  compressor.knee.value = 10;
  compressor.ratio.value = 8;
  compressor.attack.value = 0.002;
  compressor.release.value = 0.12;
  const limiter = context.createWaveShaper();
  const curve = new Float32Array(2049);
  for (let i = 0; i < curve.length; i++) {
    const x = (i / (curve.length - 1)) * 2 - 1;
    const magnitude = Math.abs(x);
    const shaped = magnitude < 0.7 ? magnitude : 0.7 + 0.3 * Math.tanh((magnitude - 0.7) / 0.3);
    curve[i] = Math.sign(x) * shaped;
  }
  limiter.curve = curve;
  input.connect(compressor).connect(limiter).connect(context.destination);
  return { input, compressor, limiter };
}

export interface PopVoice {
  readonly startTime: number;
  readonly endTime: number;
  /** Fade out quickly and stop, for voice stealing. */
  cut(at: number): void;
}

/** Schedule one pop at `when` into `destination`. */
export function playPop(
  context: BaseAudioContext,
  destination: AudioNode,
  noise: AudioBuffer,
  params: PopParams,
  pan: number,
  when: number,
  random: () => number,
): PopVoice {
  const end = when + Math.max(params.toneS, params.noiseS);

  const voice = context.createGain();
  const panner = context.createStereoPanner();
  panner.pan.value = Math.min(1, Math.max(-1, pan));
  voice.connect(panner).connect(destination);

  const tone = context.createOscillator();
  tone.type = 'sine';
  tone.frequency.setValueAtTime(params.startHz, when);
  tone.frequency.exponentialRampToValueAtTime(params.endHz, when + params.dropS);
  const toneGain = context.createGain();
  toneGain.gain.setValueAtTime(0, when);
  toneGain.gain.linearRampToValueAtTime(params.toneLevel, when + 0.003);
  toneGain.gain.exponentialRampToValueAtTime(0.0005, when + params.toneS);
  tone.connect(toneGain).connect(voice);

  const burst = context.createBufferSource();
  burst.buffer = noise;
  const band = context.createBiquadFilter();
  band.type = 'bandpass';
  band.frequency.value = params.noiseHz;
  band.Q.value = 0.9;
  const noiseGain = context.createGain();
  // Near-instant attack: the transient is what makes it a pop rather than a beep.
  noiseGain.gain.setValueAtTime(0, when);
  noiseGain.gain.linearRampToValueAtTime(params.noiseLevel, when + 0.001);
  noiseGain.gain.exponentialRampToValueAtTime(0.0005, when + params.noiseS);
  burst.connect(band).connect(noiseGain).connect(voice);

  const offset = random() * (noise.duration - params.noiseS - 0.01);
  tone.start(when);
  burst.start(when, Math.max(0, offset));
  tone.stop(end + 0.01);
  burst.stop(end + 0.01);
  // Release the chain once it has finished so nothing stays connected to the bus.
  tone.onended = () => voice.disconnect();

  return {
    startTime: when,
    endTime: end,
    cut(at) {
      if (at >= end) return;
      voice.gain.cancelScheduledValues(at);
      voice.gain.setValueAtTime(voice.gain.value, at);
      voice.gain.linearRampToValueAtTime(0, at + 0.008);
      tone.stop(at + 0.01);
      burst.stop(at + 0.01);
    },
  };
}
