/**
 * Every live-tunable number in the game. One mutable object is created at boot and shared;
 * modules read values from it each frame (never cache them) so the debug panel takes effect
 * immediately. This file is pure data: no DOM access, so game logic can import it.
 */

/** Bump when a default changes meaning, so stale saved values are discarded. */
export const TUNABLES_VERSION = 3;

export interface Tunables {
  // --- Spawning ---
  /** Bubbles the spawner tries to keep on screen. */
  targetBubbles: number;
  /** Minimum time between spawns. */
  spawnIntervalMs: number;
  /** Fraction of bubbles that enter from the sides instead of the top. */
  sideEntryFraction: number;
  /** Bubble radius range in world units. */
  radiusMin: number;
  radiusMax: number;

  // --- Motion ---
  /** Mean drift speed in world units per second. */
  driftSpeed: number;
  /** Per-bubble speed variation, as a fraction of driftSpeed. */
  speedJitter: number;
  /** Peak lateral meander velocity in world units per second. */
  meanderAmplitude: number;
  meanderPeriodS: number;
  /** Strength of the soft push that keeps bubbles from overlapping (0 disables). */
  separation: number;

  // --- Pop rule ---
  /** A mask texel counts as "person" at or above this probability (0..1). */
  maskThreshold: number;
  /** Pop when covered area ≥ min(popFraction × bubble area, popAreaAbs). */
  popFraction: number;
  /**
   * Covered area (world units²) that pops any bubble, however big: about 35 cm² at 3 m and
   * 65 cm² at 4 m, a child's palm, so part of a hand is enough.
   */
  popAreaAbs: number;
  /** A bubble can pop once at least this fraction of it is on screen. */
  liveVisibleFraction: number;
  /** The pop condition must hold this long before popping (0 = first qualifying mask). */
  popHoldMs: number;
  /**
   * Ignore mask texels that have been "person" in the same place for a while: a coat on a
   * hook, a cushion, a false positive that is on most of the time, the middle of someone
   * standing still. A hand or body arriving somewhere it has not been lately still pops.
   */
  ignoreStatic: boolean;
  /** Time constant of each texel's long-term occupancy (a running average of "person"). */
  staticSeconds: number;
  /** A texel is ignored as static while its occupancy is at or above this (0..1). */
  staticOccupancy: number;

  // --- Round ---
  /** Seconds between the first player being seen and the round starting. */
  countdownS: number;
  /** Length of a round. */
  roundS: number;
  /** How long the results stay up before the next countdown can begin. */
  resultsS: number;
  /**
   * A pop goes to the nearest player whose body is within this many torso lengths of the
   * bubble's edge; farther than that it scores for nobody.
   */
  ownerReach: number;

  // --- Vision ---
  /**
   * Feed the whole frame to the model squashed to a square (one inference). Off = square
   * tiles, which the model segments far better.
   */
  stretchInput: boolean;
  /**
   * Tile side as a fraction of frame height. 1 covers the whole frame; smaller zooms in so
   * small or distant players look bigger to the model, leaving the top of the frame uncovered.
   */
  tileHeight: number;

  // --- View ---
  mirror: boolean;
  /** HUD inset as a fraction of screen height, for TV overscan. */
  safeMargin: number;
  /** Cap on backbuffer pixels (width × height). */
  maxRenderPixels: number;

  // --- Audio ---
  masterVolume: number;
  /** Music level relative to the master volume. */
  musicVolume: number;

  // --- Debug ---
  showMask: boolean;
  maskOpacity: number;
  /** Draw each bubble's coverage and pop threshold. */
  showCoverage: boolean;
  /** Show exact frame/mask pairs instead of the live video (for judging mask quality). */
  pairVideoToMask: boolean;
}

