  popHoldMs: 0,
  ignoreStatic: true,
  staticSeconds: 3,
  staticOccupancy: 0.3,

  countdownS: 10,
  roundS: 30,
  resultsS: 8,
  ownerReach: 1,

  stretchInput: false,
