export type TunableKey = keyof Tunables;

export interface NumberSpec {
  kind: 'number';
  group: string;
  label: string;
  min: number;
  max: number;
  step: number;
}

export interface BooleanSpec {
  kind: 'boolean';
  group: string;
  label: string;
}

export type TunableSpec = NumberSpec | BooleanSpec;

const num = (group: string, label: string, min: number, max: number, step: number): NumberSpec => ({
  kind: 'number',
  group,
  label,
  min,
  max,
  step,
});
const bool = (group: string, label: string): BooleanSpec => ({ kind: 'boolean', group, label });

/** Panel metadata. Iteration order is the display order. */
