/**
 * Synthesized pop sounds, the round's signals and the music loop, over Web Audio. Each pop is a short, self-contained voice into a
 * master bus with a compressor and soft limiter; at most MAX_VOICES play at once and the
 * oldest is cut when a new pop needs room, so a burst of pops stays responsive and clean.
 */
import type { Tunables } from '../config/tunables';
import { playCue } from './cues';
import {
  createMasterBus,
  createNoiseBuffer,
  type MasterBus,
  type PopVoice,
  playPop,
  popParams,
  volumeToGain,
} from './popSynth';
import type { Sfx } from './types';

/** Simultaneous pops. Each lasts under 0.2 s, so this covers a sweep through a cluster. */
export const MAX_VOICES = 8;
/**
 * Pops that arrive together (one frame's worth) are spread this far apart: a quick
 * "pop-pop-pop" reads better than one loud thud, and their transients do not stack.
 */
const STAGGER_S = 0.01;
/**
 * Offsets cycle through this many slots, so a big burst never trails the picture by more
 * than (slots - 1) × STAGGER_S; later pops in the same burst share slots with earlier ones.
 */
const STAGGER_SLOTS = 4;
/** Pops this close together on the main-thread clock count as one burst. */
const BURST_WINDOW_MS = 4;
/** Time constant for volume and mute changes, short enough to feel instant without clicks. */
const GAIN_SMOOTHING_S = 0.015;

/** Music is quieter than this fraction of full scale even with its slider at the top. */
const MUSIC_HEADROOM = 0.5;

interface Engine {
  context: AudioContext;
  bus: MasterBus;
  noise: AudioBuffer;
}

/** The looping track: its own gain straight to the output, so pops never make it pump. */
interface Music {
  url: string;
  gain: GainNode | null;
  source: AudioBufferSourceNode | null;
  buffer: AudioBuffer | null;
  /** Encoded bytes, kept until there is a context to decode them with. */
  encoded: ArrayBuffer | null;
}

export function createSfx(tunables: Tunables): Sfx {
  let engine: Engine | null = null;
  let muted = false;
  /** Paused by the owner (tab hidden); independent of the context's own state. */
  let suspended = false;
  let disposed = false;
  const voices: PopVoice[] = [];
  /** When the current burst began (performance.now) and how many pops it has had. */
  let burstStartMs = Number.NEGATIVE_INFINITY;
  let burstCount = 0;

  /** Delay for the next pop: 0 for the first of a burst, then a few ms per slot. */
  const staggerDelay = (): number => {
    const nowMs = performance.now();
    if (nowMs - burstStartMs > BURST_WINDOW_MS) {
      burstStartMs = nowMs;
      burstCount = 0;
    }
    return (burstCount++ % STAGGER_SLOTS) * STAGGER_S;
  };

  let music: Music | null = null;

  const targetGain = (): number => (muted ? 0 : volumeToGain(tunables.masterVolume));
  const musicGain = (): number =>
    targetGain() * volumeToGain(tunables.musicVolume) * MUSIC_HEADROOM;

  const applyGain = (): void => {
    if (!engine) return;
    const { context, bus } = engine;
    bus.input.gain.setTargetAtTime(targetGain(), context.currentTime, GAIN_SMOOTHING_S);
    music?.gain?.gain.setTargetAtTime(musicGain(), context.currentTime, GAIN_SMOOTHING_S);
  };

  /** Start the loop once both the track and the audio context exist. */
  const playMusic = (): void => {
    const track = music;
    if (!engine || !track || track.source || disposed) return;
    const { context } = engine;
    if (!track.buffer) {
      const encoded = track.encoded;
      if (!encoded) return;
      track.encoded = null;
      context.decodeAudioData(encoded).then(
        (buffer) => {
          track.buffer = buffer;
          playMusic();
        },
        () => {
          // Undecodable: no music.
        },
      );
      return;
    }
    const gain = context.createGain();
    gain.gain.value = musicGain();
    const source = context.createBufferSource();
    source.buffer = track.buffer;
    source.loop = true;
    source.connect(gain).connect(context.destination);
    source.start();
    track.gain = gain;
    track.source = source;
  };

  const build = (): Engine => {
    const context = new AudioContext({ latencyHint: 'interactive' });
    const bus = createMasterBus(context);
    bus.input.gain.value = targetGain();
    return { context, bus, noise: createNoiseBuffer(context, Math.random) };
  };

  /** Drop finished voices; cut the oldest if the cap is still reached. */
  const makeRoom = (now: number): void => {
    for (let i = voices.length - 1; i >= 0; i--) {
      if ((voices[i] as PopVoice).endTime <= now) voices.splice(i, 1);
    }
    while (voices.length >= MAX_VOICES) {
      let oldest = 0;
      for (let i = 1; i < voices.length; i++) {
        if ((voices[i] as PopVoice).startTime < (voices[oldest] as PopVoice).startTime) oldest = i;
      }
      (voices[oldest] as PopVoice).cut(now);
      voices.splice(oldest, 1);
    }
  };

  return {
    get muted() {
      return muted;
    },

    async unlock() {
      if (disposed) return;
      try {
        engine ??= build();
        playMusic();
        if (!suspended && engine.context.state !== 'running') await engine.context.resume();
      } catch {
        // No audio device, or the browser refused: the game simply stays silent.
      }
    },

    pop(radius, pan) {
      if (!engine || muted || suspended || engine.context.state !== 'running') return;
      const { context, bus, noise } = engine;
      const now = context.currentTime;
      makeRoom(now);
      applyGain();
      const when = now + staggerDelay();
      const params = popParams(radius, Math.random);
      voices.push(playPop(context, bus.input, noise, params, pan, when, Math.random));
    },

    cue(cue) {
      if (!engine || muted || suspended || engine.context.state !== 'running') return;
      applyGain();
      playCue(engine.context, engine.bus.input, cue, engine.context.currentTime);
    },

    startMusic(url) {
      if (disposed || music?.url === url) return;
      const track: Music = { url, gain: null, source: null, buffer: null, encoded: null };
      music = track;
      fetch(url)
        .then((response) => {
          if (!response.ok) throw new Error(`HTTP ${response.status}`);
          return response.arrayBuffer();
        })
        .then(
          (encoded) => {
            track.encoded = encoded;
            if (music === track) playMusic();
          },
          () => {
            // No music is not worth interrupting the game for.
          },
        );
    },

    applyVolume() {
      applyGain();
    },

    setMuted(value) {
      muted = value;
      applyGain();
    },

    suspend() {
      suspended = true;
      engine?.context.suspend().catch(() => {});
    },

    resume() {
      suspended = false;
      engine?.context.resume().catch(() => {});
    },

    dispose() {
      disposed = true;
      voices.length = 0;
      music = null;
      engine?.context.close().catch(() => {});
      engine = null;
    },
  };
}
