/**
 * Frame scheduling between a source and the segmenter: which frames get segmented, who
 * owns each VideoFrame, and which results may still be delivered.
 *
 * - At most one frame is in flight. A frame that arrives meanwhile waits in a single
 *   pending slot, where a newer frame replaces (and closes) it, so at most two frames are
 *   open. With pairing on, a clone of the in-flight frame and the untaken pair's frame are
 *   held as well; clones share the original's pixels.
 * - `bumpEpoch()` (pause, source switch, dispose) invalidates everything captured before
 *   it: the pending frame is closed, an untaken mask or pair is discarded, and the
 *   in-flight result is dropped when it arrives.
 * - It never decides that the segmenter is broken; a failed frame is just dropped. Recovery
 *   is `ResilientSegmenter`'s job.
 *
 * Pure (no DOM), so it is unit-tested with fake frames and a fake segmenter.
 */
import type { PersonMask } from '../core/mask';
import { RateMeter, RollingPercentiles } from './stats';
import type { FramePair, FrameTick, SegmentResult, VisionStats } from './types';

export interface FrameSink {
  /** Takes ownership of `frame` and closes it; always settles. */
  segment(frame: VideoFrame): Promise<SegmentResult>;
  /** Takes back the buffer of a mask that was never handed out, for reuse. */
  recycle?(data: Uint8Array): void;
}

export function createStats(): VisionStats {
  return {
    cameraFps: 0,
    maskFps: 0,
    inferMsP50: 0,
    inferMsP95: 0,
    maskAgeMs: 0,
    openFrames: 0,
    droppedFrames: 0,
    restarts: 0,
    masksDelivered: 0,
    regionsPerFrame: 0,
  };
}

/** A frame plus what the mask computed from it needs to know. Reused, never reallocated. */
interface Slot {
  frame: VideoFrame | null;
  seq: number;
  captureTimeMs: number;
  sourceWidth: number;
  sourceHeight: number;
  epoch: number;
  /** Pairing: a clone of `frame`, kept for `takePair`. */
  pairImage: VideoFrame | null;
}

function emptySlot(): Slot {
  return {
    frame: null,
    seq: 0,
    captureTimeMs: 0,
    sourceWidth: 0,
    sourceHeight: 0,
    epoch: 0,
    pairImage: null,
  };
}

export class FrameScheduler {
  /** Grab and segment frames only while true (running, not paused or failed). */
  accepting = false;
  /** Frames whose segmentation failed. Not part of `VisionStats`; used by tests and logs. */
  failedFrames = 0;

  private epoch = 0;
  private seq = 0;
  private busy = false;
  private readonly flight = emptySlot();
  private readonly waiting = emptySlot();
  private latest: PersonMask | null = null;
  /** `latest` has been handed out through `takePair`, so its buffer must not be reused. */
  private latestExposed = false;
  private pair: FramePair | null = null;
  private pairing = false;
  private disposed = false;
  private readonly cameraRate = new RateMeter();
  private readonly maskRate = new RateMeter();
  private readonly inferMs = new RollingPercentiles();

  constructor(
    private readonly sink: FrameSink,
    /** Updated in place. */
    readonly stats: VisionStats,
    private readonly now: () => number = () => performance.now(),
    /** Called with every delivered mask, after it has become available to `takeMask`. */
    private readonly onMask?: (mask: PersonMask) => void,
  ) {}

  /** Source frame handler. */
  onTick(tick: FrameTick): void {
    const { stats } = this;
    const seq = ++this.seq;
    this.cameraRate.record(tick.captureTimeMs);
    stats.cameraFps = this.cameraRate.rate(tick.captureTimeMs);
    // Refreshed here too, so the reading falls when masks stop while frames keep coming.
    stats.maskFps = this.maskRate.rate(this.now());
    if (!this.accepting || this.disposed) return;

    const slot = this.busy ? this.waiting : this.flight;
    if (slot.frame) {
      // Newest wins: the waiting frame will never be segmented. Closed before the grab so
      // that not even momentarily are three frames open.
      slot.frame.close();
      slot.frame = null;
      stats.openFrames--;
      stats.droppedFrames++;
    }
    let frame: VideoFrame;
    try {
      frame = tick.grab();
    } catch {
      // E.g. a clip with no current frame while it seeks back to the start.
      stats.droppedFrames++;
      return;
    }
    stats.openFrames++;
    slot.frame = frame;
    slot.seq = seq;
    slot.captureTimeMs = tick.captureTimeMs;
    slot.sourceWidth = frame.displayWidth;
    slot.sourceHeight = frame.displayHeight;
    slot.epoch = this.epoch;
    if (!this.busy) this.submit();
  }

  /** Invalidate everything captured so far (pause, source switch). */
  bumpEpoch(): void {
    this.epoch++;
    const { waiting, stats } = this;
    if (waiting.frame) {
      waiting.frame.close();
      waiting.frame = null;
      stats.openFrames--;
      stats.droppedFrames++;
    }
    this.dropPair();
    this.dropLatest();
    this.cameraRate.reset();
    this.maskRate.reset();
    stats.cameraFps = 0;
    stats.maskFps = 0;
  }

  /** Forget inference timings, e.g. after the segmenter backend changed. */
  resetTimings(): void {
    this.inferMs.reset();
  }

  takeMask(): PersonMask | null {
    const mask = this.latest;
    this.latest = null;
    this.latestExposed = false;
    return mask;
  }

  setPairing(enabled: boolean): void {
    this.pairing = enabled;
    // A clone already in flight is closed when its result arrives.
    if (!enabled) this.dropPair();
  }

  takePair(): FramePair | null {
    const { pair } = this;
    if (!pair) return null;
    this.pair = null;
    this.stats.openFrames--;
    if (pair.mask === this.latest) this.latestExposed = true;
    return pair;
  }

  /** Stop for good. A frame still in flight is closed and its result dropped when it settles. */
  dispose(): void {
    this.accepting = false;
    this.pairing = false;
    this.bumpEpoch();
    this.disposed = true;
  }

  private submit(): void {
    const { flight, stats } = this;
    const frame = flight.frame;
    if (!frame) return;
    this.busy = true;
    flight.pairImage = null;
    if (this.pairing) {
      try {
        flight.pairImage = frame.clone();
        stats.openFrames++;
      } catch {
        // Pairing is a debug aid; the mask still goes through.
      }
    }
    let result: Promise<SegmentResult>;
    try {
      result = this.sink.segment(frame);
    } catch (error) {
      result = Promise.reject(error);
    }
    result.then(this.onResult, this.onFailure);
  }

  private readonly onResult = (result: SegmentResult): void => {
    const { flight } = this;
    const pairImage = this.settleFlight();
    if (flight.epoch === this.epoch) {
      this.deliver(result, pairImage);
    } else {
      this.sink.recycle?.(result.data);
      this.closeFrame(pairImage);
    }
    this.next();
  };

  private readonly onFailure = (): void => {
    this.closeFrame(this.settleFlight());
    this.failedFrames++;
    this.next();
  };

  /** Release the in-flight frame (the sink has closed it) and return its pairing clone. */
  private settleFlight(): VideoFrame | null {
    const { flight } = this;
    // The sink owns the frame and has closed it; closing again is a harmless safety net.
    flight.frame?.close();
    flight.frame = null;
    this.stats.openFrames--;
    const pairImage = flight.pairImage;
    flight.pairImage = null;
    this.busy = false;
    return pairImage;
  }

  /** Move the pending frame, if any, into flight. */
  private next(): void {
    const { flight, waiting } = this;
    if (!waiting.frame || this.disposed) return;
    flight.frame = waiting.frame;
    flight.seq = waiting.seq;
    flight.captureTimeMs = waiting.captureTimeMs;
    flight.sourceWidth = waiting.sourceWidth;
    flight.sourceHeight = waiting.sourceHeight;
    flight.epoch = waiting.epoch;
    waiting.frame = null;
    this.submit();
  }

  private deliver(result: SegmentResult, pairImage: VideoFrame | null): void {
    const { flight, stats } = this;
    const now = this.now();
    // A new object per mask: consumers may keep masks across frames.
    const mask: PersonMask = {
      data: result.data,
      width: result.width,
      height: result.height,
      seq: flight.seq,
      captureTimeMs: flight.captureTimeMs,
      sourceWidth: flight.sourceWidth,
      sourceHeight: flight.sourceHeight,
    };

    if (pairImage) {
      if (this.pairing) {
        this.dropPair();
        this.pair = { image: pairImage, mask };
      } else {
        this.closeFrame(pairImage);
      }
    }
    this.dropLatest();
    this.latest = mask;

    stats.masksDelivered++;
    this.maskRate.record(now);
    stats.maskFps = this.maskRate.rate(now);
    this.inferMs.add(result.inferMs);
    stats.inferMsP50 = this.inferMs.percentile(0.5);
    stats.inferMsP95 = this.inferMs.percentile(0.95);
    stats.maskAgeMs = now - flight.captureTimeMs;
    this.onMask?.(mask);
  }

  /** Discard an untaken mask, reusing its buffer when nobody has seen it. */
  private dropLatest(): void {
    const { latest } = this;
    if (latest && !this.latestExposed && this.pair?.mask !== latest) {
      this.sink.recycle?.(latest.data);
    }
    this.latest = null;
    this.latestExposed = false;
  }

  private dropPair(): void {
    if (!this.pair) return;
    this.closeFrame(this.pair.image);
    this.pair = null;
  }

  private closeFrame(frame: VideoFrame | null): void {
    if (!frame) return;
    frame.close();
    this.stats.openFrames--;
  }
}
