import { Container, Sprite, type Texture } from 'pixi.js';
import type { Bubble } from '../game/types';
import { mixRgb } from './color';
import { GLYPHS } from './textures';

/** Gauge dashes around each bubble; lit ones show coverage, a full ring means it pops. */
const SEGMENTS = 24;
const GAUGE_GAP = 16;
const DASH_THICKNESS = 10;
const LABEL_CHARS = 4;
const GLYPH_ASPECT = 40 / 64;

const COLOR_LOW = 0x4fd8ff;
const COLOR_HIGH = 0xffc23d;
const COLOR_POP = 0xff3d5a;
const COLOR_UNLIT = 0x1b2230;
const COLOR_IDLE = 0x9aa4ad;

const DOT = GLYPHS.indexOf('.');

interface CoverageView {
  id: number;
  seen: number;
  container: Container;
  dashes: Sprite[];
  glyphs: Sprite[];
  /** What the sprites currently show, to touch them only when it changes. */
  layoutR: number;
  shownHundredths: number;
  shownLit: number;
  shownLive: boolean | null;
}

/** Colour of the lit dashes for a coverage value (1 = pops). */
function gaugeColor(coverage: number): number {
  if (coverage >= 1) return COLOR_POP;
  if (coverage < 0.5) return COLOR_LOW;
  return mixRgb(COLOR_LOW, COLOR_HIGH, (coverage - 0.5) / 0.5);
}

/**
 * Debug: each bubble's coverage as a ring gauge and a number. Live bubbles get a coloured
 * gauge (cyan → amber → red as they approach popping); bubbles that cannot pop yet are grey
 * with every other dash missing.
 */
export class CoverageOverlay {
  readonly container = new Container();

  private readonly glyphTextures: readonly Texture[];
  private readonly dash: Texture;
  private readonly views = new Map<number, CoverageView>();
  private readonly active: CoverageView[] = [];
  private readonly pool: CoverageView[] = [];
  private frame = 0;

  constructor(glyphs: readonly Texture[], dash: Texture) {
    this.glyphTextures = glyphs;
    this.dash = dash;
    this.container.visible = false;
  }

  sync(bubbles: readonly Bubble[], enabled: boolean): void {
    this.container.visible = enabled;
    if (!enabled) {
      if (this.active.length > 0) this.releaseAll();
      return;
    }
    const frame = ++this.frame;
    for (let i = 0; i < bubbles.length; i++) {
      const bubble = bubbles[i] as Bubble;
      const view = this.views.get(bubble.id) ?? this.acquire(bubble.id);
      view.seen = frame;
      this.show(view, bubble);
    }
    for (let i = this.active.length - 1; i >= 0; i--) {
      const view = this.active[i] as CoverageView;
      if (view.seen === frame) continue;
      this.release(view);
      this.active[i] = this.active[this.active.length - 1] as CoverageView;
      this.active.pop();
    }
  }

  /** Drop every gauge (ids restart with the next world) and hide until the next sync. */
  clear(): void {
    this.releaseAll();
    this.container.visible = false;
  }

  dispose(): void {
    this.views.clear();
    this.active.length = 0;
    this.pool.length = 0;
    this.container.destroy({ children: true });
  }

  private acquire(id: number): CoverageView {
    let view = this.pool.pop();
    if (!view) {
      const container = new Container();
      const dashes: Sprite[] = [];
      for (let i = 0; i < SEGMENTS; i++) {
        const sprite = new Sprite({ texture: this.dash, anchor: 0.5 });
        dashes.push(sprite);
        container.addChild(sprite);
      }
      const glyphs: Sprite[] = [];
      for (let i = 0; i < LABEL_CHARS; i++) {
        const sprite = new Sprite({ texture: this.glyphTextures[0] as Texture, anchor: 0.5 });
        glyphs.push(sprite);
        container.addChild(sprite);
      }
      view = {
        id: 0,
        seen: 0,
        container,
        dashes,
        glyphs,
        layoutR: -1,
        shownHundredths: -1,
        shownLit: -1,
        shownLive: null,
      };
    }
    view.id = id;
    view.layoutR = -1;
    view.shownHundredths = -1;
    view.shownLit = -1;
    view.shownLive = null;
    this.container.addChild(view.container);
    this.views.set(id, view);
    this.active.push(view);
    return view;
  }

  private release(view: CoverageView): void {
    this.views.delete(view.id);
    this.container.removeChild(view.container);
    this.pool.push(view);
  }

  private releaseAll(): void {
    for (const view of this.active) this.release(view);
    this.active.length = 0;
  }

  private show(view: CoverageView, bubble: Bubble): void {
    view.container.position.set(bubble.x, bubble.y);
    if (bubble.r !== view.layoutR) this.layout(view, bubble.r);

    const coverage = Number.isFinite(bubble.coverage) ? Math.max(0, bubble.coverage) : 0;
    const hundredths = Math.min(999, Math.round(coverage * 100));
    const lit = Math.min(SEGMENTS, Math.round(Math.min(1, coverage) * SEGMENTS));
    const live = bubble.live;

    if (lit !== view.shownLit || live !== view.shownLive || hundredths !== view.shownHundredths) {
      const color = live ? gaugeColor(coverage) : COLOR_IDLE;
      for (let i = 0; i < SEGMENTS; i++) {
        const dash = view.dashes[i] as Sprite;
        const on = i < lit;
        dash.visible = live || i % 2 === 0;
        dash.tint = on ? color : live ? COLOR_UNLIT : COLOR_IDLE;
        dash.alpha = on ? 1 : live ? 0.6 : 0.35;
      }
      for (const glyph of view.glyphs) {
        glyph.tint = live ? (coverage >= 1 ? COLOR_POP : 0xffffff) : COLOR_IDLE;
        glyph.alpha = live ? 1 : 0.7;
      }
    }
    if (hundredths !== view.shownHundredths) {
      const textures = this.glyphTextures;
      const glyphs = view.glyphs as [Sprite, Sprite, Sprite, Sprite];
      glyphs[0].texture = textures[Math.floor(hundredths / 100)] as Texture;
      glyphs[1].texture = textures[DOT] as Texture;
      glyphs[2].texture = textures[Math.floor(hundredths / 10) % 10] as Texture;
      glyphs[3].texture = textures[hundredths % 10] as Texture;
    }
    view.shownHundredths = hundredths;
    view.shownLit = lit;
    view.shownLive = live;
  }

  /** Place the dashes around a bubble of radius r, starting at 12 o'clock, clockwise. */
  private layout(view: CoverageView, r: number): void {
    view.layoutR = r;
    const radius = r + GAUGE_GAP;
    const dashLength = ((2 * Math.PI * radius) / SEGMENTS) * 0.62;
    const dashTexture = this.dash;
    for (let i = 0; i < SEGMENTS; i++) {
      const angle = -Math.PI / 2 + ((i + 0.5) / SEGMENTS) * 2 * Math.PI;
      const dash = view.dashes[i] as Sprite;
      dash.position.set(Math.cos(angle) * radius, Math.sin(angle) * radius);
      dash.rotation = angle + Math.PI / 2;
      dash.scale.set(dashLength / dashTexture.width, DASH_THICKNESS / dashTexture.height);
    }
    const glyphHeight = Math.min(48, Math.max(26, r * 0.42));
    const glyphWidth = glyphHeight * GLYPH_ASPECT;
    // The decimal point is narrow; pull its neighbours in so the number reads as one word.
    const advances = [glyphWidth, glyphWidth * 0.55, glyphWidth, glyphWidth];
    const total = advances.reduce((sum, advance) => sum + advance, 0);
    let x = -total / 2;
    view.glyphs.forEach((glyph, i) => {
      const advance = advances[i] as number;
      glyph.position.set(x + advance / 2, 0);
      glyph.scale.set(glyphHeight / (glyph.texture.height || 1));
      x += advance;
    });
  }
}
