/**
 * Long-term occupancy of each mask texel, so the pop rule can ignore what has been "person"
 * in the same place for seconds: a coat on a hook, a cushion, a false positive that is on
 * most of the time, the middle of someone standing still. A hand or body arriving where it
 * has not been lately still counts on its first mask.
 *
 * Occupancy is a running average of "person" per texel with time constant `staticSeconds`,
 * stepped by the real time between masks. A texel is static for a mask when its occupancy
 * from the masks before it reaches `staticOccupancy`; that mask is folded in afterwards.
 * Judging by the earlier masks only means that whatever arrives is judged by where it was
 * not, independent of the mask rate and of how long the time constant is.
 */
import type { PersonMask } from '../core/mask';

/** Fixed-point one: 16 bits keep the per-mask step representable even for slow averages. */
const ONE = 65535;
const RATE_BITS = 15;
const RATE_ONE = (1 << RATE_BITS) - 1;
const RATE_HALF = 1 << (RATE_BITS - 1);
/** Longest time between masks taken at face value, so a pause is not one giant step. */
const MAX_GAP_MS = 250;

export class StaticOccupancy {
  /**
   * 1 where the texel was static for the latest mask (the pop rule ignored "person" there),
   * 0 elsewhere. Reused between masks; reallocated only when the mask size changes.
   */
  ignored = new Uint8Array(0);
  /** A mask has been folded in since the last clear. */
  hasState = false;

  private occupancy = new Uint16Array(0);
  private width = 0;
  private height = 0;
  private lastTimeMs = 0;

  /** Forget everything, as at the start of a session. */
  clear(): void {
    this.occupancy.fill(0);
    this.ignored.fill(0);
    this.hasState = false;
  }

  /**
   * Mark the texels that are static for `mask`, judged by the masks before it, then fold
   * `mask` in. A new mask size starts afresh.
   */
  update(
    mask: PersonMask,
    timeMs: number,
    maskThreshold: number,
    staticSeconds: number,
    staticOccupancy: number,
  ): void {
    if (mask.width !== this.width || mask.height !== this.height) {
      this.width = mask.width;
      this.height = mask.height;
      this.occupancy = new Uint16Array(mask.width * mask.height);
      this.ignored = new Uint8Array(mask.width * mask.height);
      this.hasState = false;
    }
    // The first mask has no elapsed time, so it marks nothing and adds nothing.
    const elapsedMs = this.hasState
      ? Math.min(MAX_GAP_MS, Math.max(0, timeMs - this.lastTimeMs))
      : 0;
    this.lastTimeMs = timeMs;
    this.hasState = true;
    const rate = 1 - Math.exp(-elapsedMs / (Math.max(0.05, staticSeconds) * 1000));
    // The step towards the target in Q15, so (target − s) · step stays inside 32-bit integers.
    const step = Math.round(rate * RATE_ONE);
    const limit = staticOccupancy * ONE;
    const threshold = maskThreshold * 255;
    const data = mask.data;
    const occupancy = this.occupancy;
    const ignored = this.ignored;
    for (let i = 0; i < occupancy.length; i++) {
      const s = occupancy[i] as number;
      ignored[i] = s >= limit ? 1 : 0;
      const target = (data[i] as number) >= threshold ? ONE : 0;
      // s + (target − s)·rate, rounded to nearest.
      occupancy[i] = s + (((target - s) * step + RATE_HALF) >> RATE_BITS);
    }
  }
}
