import { BufferImageSource, Sprite, Texture } from 'pixi.js';
import type { Tunables } from '../config/tunables';
import type { PersonMask } from '../core/mask';
import type { ViewTransform } from '../core/view';
import { placeOnVideo } from './videoLayer';

/** Person texels the pop rule counts. */
const COUNTED = 0x19e3ff;
/** Person texels the pop rule is ignoring (e.g. a static shape): amber, striped. */
const IGNORED = 0xffa21f;
/** Below the threshold the tint fades to this, so near-misses are visible but obviously "no". */
const BELOW_THRESHOLD_ALPHA = 0.35;
/** Alpha between the ignored stripes, so they read as different even without colour vision. */
const STRIPE_GAP_ALPHA = 0.4;

/**
 * Debug view of the person mask over the video. Texels the game counts as person (at or
 * above `maskThreshold`) get the full cyan tint, weaker ones a faint ramp, and person texels
 * the pop rule is ignoring amber stripes, so the overlay shows exactly what the pop rule
 * sees. The mask is in camera orientation and covers the whole source frame, so it is
 * placed and mirrored exactly like the video.
 */
export class MaskOverlay {
  readonly sprite = new Sprite();

  private readonly tunables: Tunables;
  private view: ViewTransform | null = null;
  private mask: PersonMask | null = null;
  private source: BufferImageSource | null = null;
  private texture: Texture | null = null;
  private pixels = new Uint32Array(0);
  /**
   * Mask value (0..255) → premultiplied RGBA texel at the current threshold: counted, and
   * ignored on and between the stripes. Written byte by byte, so the order is right on any
   * platform.
   */
  private readonly counted = new Uint32Array(256);
  private readonly ignoredOn = new Uint32Array(256);
  private readonly ignoredGap = new Uint32Array(256);
  private lutThreshold = Number.NaN;
  private placedView: ViewTransform | null = null;

  constructor(tunables: Tunables) {
    this.tunables = tunables;
    this.sprite.visible = false;
  }

  setView(view: ViewTransform): void {
    this.view = view;
  }

  /** Convert and upload once per call; `ignored` is used only if it matches the mask size. */
  setMask(mask: PersonMask | null, ignored: Uint8Array | null): void {
    this.mask = mask;
    if (!mask) return;

    const { width, height } = mask;
    if (!this.source || this.source.width !== width || this.source.height !== height) {
      this.releaseTexture();
      this.pixels = new Uint32Array(width * height);
      this.source = new BufferImageSource({
        resource: new Uint8Array(this.pixels.buffer),
        width,
        height,
        format: 'rgba8unorm',
        alphaMode: 'premultiplied-alpha',
        scaleMode: 'linear',
        label: 'mask-overlay',
      });
      this.texture = new Texture({ source: this.source });
      this.placedView = null;
    }

    this.refreshLuts();
    const { data } = mask;
    const { pixels, counted } = this;
    if (!ignored || ignored.length !== pixels.length) {
      for (let i = 0; i < pixels.length; i++) pixels[i] = counted[data[i] as number] as number;
    } else {
      const { ignoredOn, ignoredGap } = this;
      for (let y = 0, i = 0; y < height; y++) {
        for (let x = 0; x < width; x++, i++) {
          const value = data[i] as number;
          if (ignored[i] === 0) pixels[i] = counted[value] as number;
          // Diagonal stripes, two texels on and two off.
          else pixels[i] = (((x + y) & 3) < 2 ? ignoredOn[value] : ignoredGap[value]) as number;
        }
      }
    }
    this.source.update();
  }

  /** Per frame: follow the opacity tunable and the view. */
  sync(): void {
    const { sprite, view, texture } = this;
    const opacity = this.tunables.maskOpacity;
    sprite.visible = Boolean(this.mask && texture && view) && opacity > 0;
    if (!sprite.visible || !texture || !view) return;
    sprite.alpha = opacity;
    if (sprite.texture !== texture || this.placedView !== view) {
      sprite.texture = texture;
      placeOnVideo(sprite, view);
      this.placedView = view;
    }
  }

  dispose(): void {
    this.releaseTexture();
    this.mask = null;
    this.sprite.destroy();
  }

  private refreshLuts(): void {
    const threshold = this.tunables.maskThreshold;
    if (threshold === this.lutThreshold) return;
    this.lutThreshold = threshold;
    const cut = threshold * 255;
    for (let value = 0; value < 256; value++) {
      const person = value >= cut;
      const faint = (BELOW_THRESHOLD_ALPHA * value) / Math.max(1, cut);
      writeTexel(this.counted, value, COUNTED, person ? 1 : faint);
      // Below the threshold an ignored texel looks like any other: it would not count anyway.
      writeTexel(this.ignoredOn, value, person ? IGNORED : COUNTED, person ? 1 : faint);
      writeTexel(
        this.ignoredGap,
        value,
        person ? IGNORED : COUNTED,
        person ? STRIPE_GAP_ALPHA : faint,
      );
    }
  }

  private releaseTexture(): void {
    this.texture?.destroy();
    this.source?.destroy();
    this.texture = null;
    this.source = null;
  }
}

/** Store colour `rgb` at `alpha` as a premultiplied RGBA texel at `index` of `lut`. */
function writeTexel(lut: Uint32Array, index: number, rgb: number, alpha: number): void {
  const bytes = new Uint8Array(lut.buffer, index * 4, 4);
  bytes[0] = Math.round(((rgb >> 16) & 255) * alpha);
  bytes[1] = Math.round(((rgb >> 8) & 255) * alpha);
  bytes[2] = Math.round((rgb & 255) * alpha);
  bytes[3] = Math.round(alpha * 255);
}
