/**
 * The game world: endless free play with one shared score. Bubbles enter from off screen,
 * drift across it and either pop when the person mask covers enough of them or expire
 * silently once they have left.
 *
 * Deterministic for a given seed and sequence of calls: time comes in through `step` and
 * `applyMask`, randomness from the injected `Rng`. Steady-state stepping and mask tests
 * allocate nothing; only spawns and events create objects.
 */
import type { PersonMask } from '../core/mask';
import type { ViewTransform } from '../core/view';
import type { SimBubble } from './bubble';
import { DiscProbe, popThresholdArea } from './coverage';
import { visibleFraction } from './geometry';
import { advance, driftSpeedOf, pushesVisible } from './motion';
import { type Entry, placeSpawn, planSpawn, type SpawnPlan } from './spawner';
import { StaticOccupancy } from './staticOccupancy';
import type { Bubble, GameEvent, World, WorldOptions } from './types';

/**
 * Steps are split into substeps no longer than this. Drift and meander are exact at any
 * step, but the push is not, so a fixed bound on its step keeps the motion the same at 20,
 * 60 or 144 frames per second.
 */
const MAX_SUBSTEP_S = 1 / 120;
/** Beyond this a step is a stall (e.g. a debugger pause), not time to catch up on. */
const MAX_STEP_S = 1;
/** Hues advance by the golden angle so consecutive bubbles never look alike. */
const GOLDEN_ANGLE = 137.508;
const HUE_JITTER = 20;
/** Each bubble's meander period is the tunable times a factor within this much of 1. */
const MEANDER_PERIOD_SPREAD = 0.2;

export function createWorld(options: WorldOptions): World {
  const { tunables, rng } = options;
  let view: ViewTransform = options.view;
  const bubbles: SimBubble[] = [];
  let events: GameEvent[] = [];
  let drained: GameEvent[] = [];
  let score = 0;
  let nextId = 1;
  // Infinite so the first step spawns at once.
  let sinceSpawnMs = Number.POSITIVE_INFINITY;
  let hue = rng.range(0, 360);
  // Where the mask has been "person" for a while, so the pop rule can ignore it.
  const occupancy = new StaticOccupancy();
  let ignoring = false;
  const probe = new DiscProbe();
  // The next bubble's plan survives failed placements: see spawner.ts.
  const plan: SpawnPlan = { edge: 'top', r: 0, low: true };
  let planned = false;
  const entry: Entry = { x: 0, y: 0, dirX: 0, dirY: 1 };

  const emit = (type: 'spawn' | 'expire', bubble: SimBubble): void => {
    const { id, x, y, r } = bubble;
    events.push({ type, id, x, y, r, hue: bubble.hue });
  };

  const visibleOf = (bubble: SimBubble): number =>
    visibleFraction(bubble.x, bubble.y, bubble.r, view.worldWidth, view.worldHeight);

  const create = (x: number, y: number, r: number, pinned: boolean): SimBubble => {
    hue = (hue + GOLDEN_ANGLE + rng.range(-HUE_JITTER, HUE_JITTER)) % 360;
    const bubble: SimBubble = {
      id: nextId++,
      x,
      y,
      r,
      vx: 0,
      vy: 0,
      hue,
      ageS: 0,
      seed: rng.next(),
      live: pinned,
      coverage: 0,
      dirX: 0,
      dirY: 1,
      speedOffset: rng.range(-1, 1),
      meanderPhase: rng.range(0, 2 * Math.PI),
      meanderPeriodScale: rng.range(1 - MEANDER_PERIOD_SPREAD, 1 + MEANDER_PERIOD_SPREAD),
      pinned,
      entered: pinned,
      visible: 0,
      holdSinceMs: Number.NaN,
      pushX: 0,
      pushY: 0,
      sidestep: 0,
      avoidX: 0,
      avoidY: 0,
    };
    bubble.visible = visibleOf(bubble);
    bubbles.push(bubble);
    emit('spawn', bubble);
    return bubble;
  };

  /** Spawn the planned bubble if there is room for it; true if it was spawned. */
  const trySpawn = (): boolean => {
    if (!planned) {
      planSpawn(rng, tunables, plan);
      planned = true;
    }
    if (!placeSpawn(rng, plan, view, bubbles, entry)) return false;
    planned = false;
    const bubble = create(entry.x, entry.y, plan.r, false);
    bubble.dirX = entry.dirX;
    bubble.dirY = entry.dirY;
    const speed = driftSpeedOf(bubble, tunables);
    bubble.vx = entry.dirX * speed;
    bubble.vy = entry.dirY * speed;
    return true;
  };

  /**
   * Past the far side of the screen along its heading. Progress along the heading never
   * reverses, so a bubble there can never come back, even one that never got on screen.
   */
  const pastExit = (bubble: SimBubble): boolean => {
    const far =
      Math.max(0, bubble.dirX * view.worldWidth) + Math.max(0, bubble.dirY * view.worldHeight);
    return bubble.x * bubble.dirX + bubble.y * bubble.dirY - bubble.r > far;
  };

  /** Update the bubble's coverage and hold from the probe's mask; true if it pops now. */
  const shouldPop = (bubble: SimBubble, timeMs: number): boolean => {
    if (!bubble.live) {
      bubble.coverage = 0;
      bubble.holdSinceMs = Number.NaN;
      return false;
    }
    probe.measure(bubble.x, bubble.y, bubble.r);
    const needed = popThresholdArea(bubble.r, tunables);
    const covered = probe.covered * probe.texelArea;
    bubble.coverage = covered / needed;
    if (covered < needed) {
      bubble.holdSinceMs = Number.NaN;
      return false;
    }
    // Held time is measured on the caller's clock, never in masks: the mask rate varies from
    // about 10 to 30 per second. A clock that steps backwards restarts the hold.
    if (Number.isNaN(bubble.holdSinceMs) || bubble.holdSinceMs > timeMs) {
      bubble.holdSinceMs = timeMs;
    }
    return timeMs - bubble.holdSinceMs >= Math.max(0, tunables.popHoldMs);
  };

  const tick = (dtS: number): void => {
    sinceSpawnMs += dtS * 1000;
    advance(bubbles, tunables, dtS);

    for (let i = 0; i < bubbles.length; i++) {
      const bubble = bubbles[i] as SimBubble;
      bubble.visible = visibleOf(bubble);
    }
    // `pushesVisible` reads the array while it is compacted below. That is safe: a slot not
    // yet overwritten holds either a bubble still kept or one dropped for being off screen,
    // and the latter has no visible share, so it is ignored.
    let kept = 0;
    for (let i = 0; i < bubbles.length; i++) {
      const bubble = bubbles[i] as SimBubble;
      const visible = bubble.visible;
      if (!bubble.pinned) {
        if (visible > 0) {
          bubble.entered = true;
        } else if (
          (bubble.entered || pastExit(bubble)) &&
          !pushesVisible(bubble, bubbles, tunables)
        ) {
          emit('expire', bubble);
          continue;
        }
        bubble.live = visible > 0 && visible >= tunables.liveVisibleFraction;
      }
      bubbles[kept++] = bubble;
    }
    bubbles.length = kept;

    if (
      bubbles.length < tunables.targetBubbles &&
      sinceSpawnMs >= tunables.spawnIntervalMs &&
      trySpawn()
    ) {
      // Restart rather than carry over, so no two spawns are closer than the interval.
      sinceSpawnMs = 0;
    }
  };

  return {
    get bubbles(): readonly Bubble[] {
      return bubbles;
    },
    get score() {
      return score;
    },
    get ignoredTexels() {
      return ignoring ? occupancy.ignored : null;
    },

    setView(next) {
      const oldWidth = view.worldWidth;
      view = next;
      const width = next.worldWidth;
      if (width === oldWidth) return;
      // On screen, keep each bubble where it was relative to the screen; past the right
      // edge, keep its distance to that edge so it neither pops into view nor falls behind.
      for (let i = 0; i < bubbles.length; i++) {
        const bubble = bubbles[i] as SimBubble;
        if (bubble.x > oldWidth) bubble.x += width - oldWidth;
        else if (bubble.x > 0) bubble.x *= width / oldWidth;
      }
    },

    step(dtS) {
      if (!(dtS > 0)) return;
      const total = Math.min(dtS, MAX_STEP_S);
      const count = Math.ceil(total / MAX_SUBSTEP_S - 1e-9);
      for (let i = 0; i < count; i++) tick(total / count);
    },

    applyMask(mask: PersonMask, timeMs: number) {
      // Static texels are judged from the masks before this one, then this one is folded in,
      // so whatever arrives now counts at once (see staticOccupancy.ts).
      if (tunables.ignoreStatic) {
        occupancy.update(
          mask,
          timeMs,
          tunables.maskThreshold,
          tunables.staticSeconds,
          tunables.staticOccupancy,
        );
        ignoring = true;
      } else if (ignoring) {
        // Turned off: forget, so turning it back on starts like a new session.
        occupancy.clear();
        ignoring = false;
      }
      probe.setMask(view, mask, ignoring ? occupancy.ignored : null, tunables.maskThreshold);
      let kept = 0;
      for (let i = 0; i < bubbles.length; i++) {
        const bubble = bubbles[i] as SimBubble;
        if (!shouldPop(bubble, timeMs)) {
          bubbles[kept++] = bubble;
          continue;
        }
        score++;
        const { id, x, y, r } = bubble;
        events.push({ type: 'pop', id, x, y, r, hue: bubble.hue, score });
      }
      bubbles.length = kept;
    },

    drainEvents() {
      const out = events;
      events = drained;
      events.length = 0;
      drained = out;
      return out;
    },

    reset() {
      bubbles.length = 0;
      events.length = 0;
      score = 0;
      sinceSpawnMs = Number.POSITIVE_INFINITY;
      planned = false;
      occupancy.clear();
      ignoring = false;
    },

    spawnAt(x, y, r) {
      return create(x, y, r, true);
    },
  };
}
