/**
 * The round cycle: wait for players, count down while they gather, play against the clock,
 * show who won, repeat. Pure and deterministic: time comes in through `step` and `observe`.
 *
 * Nobody presses anything. A round is started by people standing in front of the camera and
 * the next one follows by itself, because the players are children across the room from the
 * keyboard.
 */
import type { Tunables } from '../config/tunables';
import { PlayerTracker } from './tracker';
import type { PersonSighting, Round, RoundEvent, RoundPhase } from './types';

export interface RoundOptions {
  /** Live object: read values when they are needed, never cache them. */
  tunables: Tunables;
}

export function createRound(options: RoundOptions): Round {
  const { tunables } = options;
  const tracker = new PlayerTracker();
  let phase: RoundPhase = 'waiting';
  let remainingS = 0;
  /** The last whole second announced in this phase. */
  let announced = 0;
  let roundNumber = 0;
  let lastObservedMs = 0;
  let winners: number[] = [];
  let events: RoundEvent[] = [];
  let drained: RoundEvent[] = [];

  const enter = (next: RoundPhase): void => {
    phase = next;
    remainingS =
      next === 'countdown'
        ? tunables.countdownS
        : next === 'playing'
          ? tunables.roundS
          : next === 'results'
            ? tunables.resultsS
            : 0;
    announced = Math.ceil(remainingS) + 1;
    if (next === 'playing') {
      roundNumber++;
      winners = [];
      for (const player of tracker.players) player.score = 0;
    } else if (next === 'results') {
      let best = 0;
      for (const player of tracker.players) {
        if (player.active && player.score > best) best = player.score;
      }
      winners = [];
      if (best > 0) {
        for (const player of tracker.players) {
          if (player.active && player.score === best) winners.push(player.slot);
        }
      }
    }
    events.push({ type: 'phase', phase: next });
  };

  /** Announce each whole second left, once, as the clock passes it. */
  const announce = (): void => {
    if (phase !== 'countdown' && phase !== 'playing') return;
    const seconds = Math.ceil(remainingS);
    if (seconds < announced && seconds > 0) {
      announced = seconds;
      events.push({ type: 'second', phase, seconds });
    }
  };

  return {
    get phase() {
      return phase;
    },
    get remainingS() {
      return remainingS;
    },
    get players() {
      return tracker.players;
    },
    get playerCount() {
      return tracker.count;
    },
    get winners() {
      return winners;
    },
    get roundNumber() {
      return roundNumber;
    },

    observe(sightings: readonly PersonSighting[], timeMs: number) {
      lastObservedMs = timeMs;
      // Players come and go until the round starts; from then on the roster is fixed, and it
      // stays fixed through the results so the scores shown are the ones that were played.
      tracker.update(sightings, timeMs, phase === 'waiting' || phase === 'countdown');
      for (const slot of tracker.joined) events.push({ type: 'join', slot });
      for (const slot of tracker.left) events.push({ type: 'leave', slot });
      if (phase === 'waiting' && tracker.count > 0) {
        enter('countdown');
        announce();
      } else if (phase === 'countdown' && tracker.count === 0) {
        enter('waiting');
      }
    },

    step(dtS: number) {
      if (phase === 'waiting' || !(dtS > 0)) return;
      remainingS = Math.max(0, remainingS - dtS);
      announce();
      if (remainingS > 0) return;
      if (phase === 'countdown') enter('playing');
      else if (phase === 'playing') enter('results');
      else enter(tracker.count > 0 ? 'countdown' : 'waiting');
      announce();
    },

    creditPop(x, y, r, popper) {
      const slot = tracker.ownerOf(x, y, r, popper, lastObservedMs, tunables.ownerReach);
      if (slot >= 0 && phase === 'playing') {
        const player = tracker.players[slot];
        if (player) {
          player.score++;
          events.push({ type: 'point', slot, x, y, r, score: player.score });
        }
      }
      return slot;
    },

    drainEvents() {
      const out = events;
      events = drained;
      events.length = 0;
      drained = out;
      return out;
    },

    reset() {
      tracker.clear();
      phase = 'waiting';
      remainingS = 0;
      winners = [];
      events.length = 0;
    },
  };
}
