import type { Unsubscribe } from '../core/events';
import { CameraSource } from './cameraSource';
import { ClipSource } from './clipSource';
import { download } from './download';
import { MainThreadSegmenter } from './mainThreadSegmenter';
import { SyntheticSource } from './syntheticSource';
import type { CameraDevice, VisionOptions, VisionPipeline } from './types';
import { Pipeline, type PipelineDeps } from './visionPipeline';
import { WorkerSegmenter } from './workerSegmenter';

export { DEFAULT_LAYOUT } from './regions';
export * from './types';

const browserDeps: PipelineDeps = {
  createSource(request) {
    switch (request.kind) {
      case 'camera':
        return new CameraSource(request.deviceId, request.fallbackToDefault);
      case 'clip':
        return new ClipSource(request.src);
      case 'synthetic':
        return new SyntheticSource();
    }
  },
  createBackend(kind, options) {
    return kind === 'worker' ? new WorkerSegmenter(options) : new MainThreadSegmenter(options);
  },
  download,
  isHidden: () => document.hidden,
  now: () => performance.now(),
};

export function createVision(options: VisionOptions): VisionPipeline {
  return new Pipeline(options, browserDeps);
}

/** Video input devices. Labels are empty until camera permission has been granted. */
export async function listCameras(): Promise<CameraDevice[]> {
  if (!navigator.mediaDevices?.enumerateDevices) return [];
  const devices = await navigator.mediaDevices.enumerateDevices();
  return devices
    .filter((device) => device.kind === 'videoinput')
    .map((device) => ({ deviceId: device.deviceId, label: device.label }));
}

/** Fires when cameras are plugged in or removed. */
export function onCamerasChanged(listener: () => void): Unsubscribe {
  const devices = navigator.mediaDevices;
  if (!devices?.addEventListener) return () => {};
  devices.addEventListener('devicechange', listener);
  return () => devices.removeEventListener('devicechange', listener);
}
