/** URL parameters. All optional; the defaults are the normal game. */
export interface Params {
  /** Open the debug HUD and tuning panel at start. */
  debug: boolean;
  /** Frame source. `clip` is implied when `clip=<url>` is given. */
  source: 'camera' | 'clip' | 'synthetic';
  clip: string | null;
  /** Where segmentation runs. `auto` = worker with main-thread fallback. */
  vision: 'auto' | 'worker' | 'main';
  /** `chroma` treats magenta pixels as "person" (no model): used with the synthetic source. */
  engine: 'mediapipe' | 'chroma';
  delegate: 'GPU' | 'CPU';
  /** Fault injection for tests: `hang` or `throw`, optionally `:<afterFrames>`. */
  fault: { kind: 'hang' | 'throw'; afterFrames: number } | null;
  /** Seed for gameplay randomness (tests). */
  seed: number | null;
  /** Skip the Start click (tests; audio stays locked). */
  autostart: boolean;
  /** Expose `window.__bubble` for automated tests. */
  e2e: boolean;
}

function flag(search: URLSearchParams, name: string): boolean {
  const value = search.get(name);
  return value !== null && value !== '0' && value !== 'false';
}

function oneOf<T extends string>(value: string | null, allowed: readonly T[], fallback: T): T {
  return allowed.includes(value as T) ? (value as T) : fallback;
}

export function parseParams(query: string): Params {
  const search = new URLSearchParams(query);
  const clip = search.get('clip');
  const engineDefault = search.get('source') === 'synthetic' ? 'chroma' : 'mediapipe';

  let fault: Params['fault'] = null;
  const faultRaw = search.get('fault');
  if (faultRaw) {
    const [kind, after] = faultRaw.split(':');
    if (kind === 'hang' || kind === 'throw') {
      const afterFrames = Number.parseInt(after ?? '', 10);
      fault = { kind, afterFrames: Number.isFinite(afterFrames) ? afterFrames : 30 };
    }
  }

  const seedRaw = search.get('seed');
  const seed = seedRaw !== null && seedRaw !== '' ? Number(seedRaw) : Number.NaN;

  return {
    debug: flag(search, 'debug'),
    // `clip` only makes sense with a URL; without one it is just the camera.
    source: clip ? 'clip' : oneOf(search.get('source'), ['camera', 'synthetic'] as const, 'camera'),
    clip,
    vision: oneOf(search.get('vision'), ['auto', 'worker', 'main'] as const, 'auto'),
    engine: oneOf(search.get('engine'), ['mediapipe', 'chroma'] as const, engineDefault),
    delegate: search.get('delegate')?.toUpperCase() === 'CPU' ? 'CPU' : 'GPU',
    fault,
    seed: Number.isFinite(seed) ? seed : null,
    autostart: flag(search, 'autostart'),
    e2e: flag(search, 'e2e'),
  };
}
