/**
 * The vision pipeline: source → scheduler → resilient segmenter → newest mask.
 *
 * It owns the lifecycle (start with its downloads, pause, switch, dispose), the wiring, and
 * the watchdog for a camera that silently stops; the hard parts live in `FrameScheduler`
 * (frame ownership, backpressure, epochs, stats) and `ResilientSegmenter` (restart and
 * fallback). Sources, backends and downloads come from `deps`, so the whole pipeline is
 * unit-tested without a browser.
 */
import { Emitter, type Unsubscribe } from '../core/events';
import type { PersonMask } from '../core/mask';
import type { Backend, BackendOptions, WasmBuild } from './backend';
import type { DownloadProgress } from './download';
import type { RegionLayout } from './protocol';
import { planRegions } from './regions';
import { ResilientSegmenter } from './resilientSegmenter';
import { createStats, FrameScheduler } from './scheduler';
import {
  type DisplaySource,
  type FramePair,
  type FrameSource,
  type FrameTick,
  type SegmenterBackend,
  type SegmenterInfo,
  type SourceInfo,
  type StartProgress,
  type StartStage,
  type SyntheticControl,
  VisionError,
  type VisionOptions,
  type VisionPipeline,
  type VisionStats,
  type VisionStatus,
} from './types';
import { type BlobDownload, WasmLibrary } from './wasmAssets';

export type SourceRequest =
  /** `fallbackToDefault`: use the default camera if this one is gone (remembered choice). */
  | { kind: 'camera'; deviceId: string | null; fallbackToDefault: boolean }
  | { kind: 'clip'; src: string | Blob }
  | { kind: 'synthetic' };

export interface PipelineDeps {
  createSource(request: SourceRequest): FrameSource;
  createBackend(kind: SegmenterBackend, options: BackendOptions): Backend;
  /** Fetch a file into a Blob, with progress and a stall timeout (see `download.ts`). */
  download: BlobDownload;
  /**
   * A hidden tab delivers no frames, so time spent hidden counts neither against start-up
   * nor as a stalled camera.
   */
  isHidden(): boolean;
  /** Monotonic milliseconds. */
  now(): number;
}

const STAGES: readonly StartStage[] = ['camera', 'download', 'wasm', 'warmup'];
/** Visible time allowed from a running segmenter to the first mask of a real frame. */
export const FIRST_MASK_TIMEOUT_MS = 15_000;
/**
 * A camera that delivers no frame for this long, while the tab is visible and nothing is
 * being switched, has stopped without saying so (a frozen driver, a muted track).
 */
export const CAMERA_STALL_MS = 5_000;
/** How often the stall watchdog looks. */
const STALL_CHECK_MS = 1_000;

/** Bytes of one start-up download, for the combined progress of the download stage. */
interface Transfer {
  /** The server has answered, so `total` is as known as it will be. */
  answered: boolean;
  received: number;
  total: number | null;
}

/**
 * Overall progress of several downloads, from those whose size is known; null until every
 * server has answered, since until then the overall size is unknown. One served compressed
 * reports its compressed size and overruns it; it is left out from then on.
 */
function downloadFraction(transfers: readonly Transfer[]): number | null {
  let received = 0;
  let total = 0;
  for (const transfer of transfers) {
    if (!transfer.answered) return null;
    if (transfer.total === null || transfer.received > transfer.total) continue;
    received += transfer.received;
    total += transfer.total;
  }
  return total > 0 ? received / total : null;
}

/** `promise`, or a rejection with the abort reason as soon as `signal` aborts. */
function abortable<T>(promise: Promise<T>, signal: AbortSignal): Promise<T> {
  if (signal.aborted) return Promise.reject(signal.reason);
  return new Promise<T>((resolve, reject) => {
    const onAbort = (): void => reject(signal.reason);
    signal.addEventListener('abort', onAbort, { once: true });
    promise.then(
      (value) => {
        signal.removeEventListener('abort', onAbort);
        resolve(value);
      },
      (error: unknown) => {
        signal.removeEventListener('abort', onAbort);
        reject(error);
      },
    );
  });
}

function asVisionError(error: unknown): VisionError {
  return error instanceof VisionError
    ? error
    : new VisionError('unknown', 'Vision failed to start.', { cause: error });
}

function isSyntheticControl(source: FrameSource | null): source is FrameSource & SyntheticControl {
  return source !== null && source.kind === 'synthetic' && 'setBlobs' in source;
}

export class Pipeline implements VisionPipeline {
  status: VisionStatus = 'idle';
  readonly stats: VisionStats = createStats();

  private source: FrameSource | null = null;
  /** The source info last seen, to notice frame-size changes. */
  private knownInfo: SourceInfo | null = null;
  private readonly segmenter: ResilientSegmenter;
  private readonly scheduler: FrameScheduler;
  private layout: RegionLayout;
  private modelBuffer: ArrayBuffer | null = null;
  private readonly wasm: WasmLibrary;
  private startPromise: Promise<void> | null = null;
  private abortStart: AbortController | null = null;
  /** Resolves the start-up wait for the first mask. */
  private firstMask: (() => void) | null = null;
  /** Source switches run one at a time, in call order. */
  private switching: Promise<unknown> = Promise.resolve();
  /** A source switch is in progress (the stall watchdog holds off meanwhile). */
  private switchingNow = false;
  /** When the current source last delivered a frame, or the watchdog last forgave it. */
  private lastFrameMs = 0;
  private lastStallCheckMs = 0;
  private stallTimer: ReturnType<typeof setInterval> | undefined;
  private readonly errors = new Emitter<VisionError>();
  private readonly sourceChanges = new Emitter<SourceInfo>();

  constructor(
    private readonly options: VisionOptions,
    private readonly deps: PipelineDeps,
  ) {
    this.layout = options.layout;
    this.wasm = new WasmLibrary(options.assets.wasmBaseUrl, deps.download);
    this.segmenter = new ResilientSegmenter({
      backend: options.backend,
      layout: options.layout,
      create: (kind, layout, monitor) =>
        deps.createBackend(kind, {
          engine: options.engine,
          delegate: options.delegate,
          loadWasm: (build) => this.wasm.load(build),
          modelBuffer: this.modelBuffer,
          inputSize: options.inputSize,
          layout,
          fault: options.fault,
          monitor,
        }),
      onRestart: () => {
        this.stats.restarts = this.segmenter.restarts;
        this.scheduler.resetTimings();
      },
      onFailed: (error) => this.onSegmenterFailed(error),
      now: deps.now,
    });
    this.scheduler = new FrameScheduler(this.segmenter, this.stats, deps.now, this.onMask);
  }

  get display(): DisplaySource | null {
    return this.source?.display ?? null;
  }

  get sourceInfo(): SourceInfo | null {
    return this.source?.info ?? null;
  }

  get segmenterInfo(): SegmenterInfo | null {
    return this.segmenter.info;
  }

  get stream(): MediaStream | null {
    return this.source?.stream ?? null;
  }

  get synthetic(): SyntheticControl | null {
    return isSyntheticControl(this.source) ? this.source : null;
  }

  start(onProgress?: (progress: StartProgress) => void): Promise<void> {
    this.startPromise ??= this.run(onProgress);
    return this.startPromise;
  }

  pause(): void {
    if (this.status !== 'running') return;
    this.status = 'paused';
    this.scheduler.accepting = false;
    this.scheduler.bumpEpoch();
    this.stopStallWatch();
    this.source?.pause();
  }

  resume(): void {
    if (this.status !== 'paused') return;
    this.status = 'running';
    this.scheduler.accepting = true;
    this.source?.resume();
    this.watchForStalls();
  }

  dispose(): void {
    if (this.status === 'disposed') return;
    this.status = 'disposed';
    this.abortStarting(new VisionError('unknown', 'Vision was stopped while starting.'));
    this.release();
    this.errors.clear();
    this.sourceChanges.clear();
  }

  takeMask(): PersonMask | null {
    return this.scheduler.takeMask();
  }

  setLayout(layout: RegionLayout): void {
    this.layout = layout;
    this.segmenter.setLayout(layout);
    this.updateRegions();
  }

  setPairing(enabled: boolean): void {
    this.scheduler.setPairing(enabled);
  }

  takePair(): FramePair | null {
    return this.scheduler.takePair();
  }

  switchCamera(deviceId: string): Promise<SourceInfo> {
    return this.serialize(() =>
      this.replaceSource({ kind: 'camera', deviceId, fallbackToDefault: false }),
    );
  }

  loadClip(src: string | Blob): Promise<SourceInfo> {
    return this.serialize(() => this.replaceSource({ kind: 'clip', src }));
  }

  onError(listener: (error: VisionError) => void): Unsubscribe {
    return this.errors.on(listener);
  }

  onSourceChange(listener: (info: SourceInfo) => void): Unsubscribe {
    return this.sourceChanges.on(listener);
  }

  // --- Start-up -------------------------------------------------------------------------

  private async run(onProgress?: (progress: StartProgress) => void): Promise<void> {
    if (this.status !== 'idle') {
      throw new VisionError('unknown', 'A vision pipeline can only be started once.');
    }
    this.status = 'starting';
    // Aborted by dispose() or by a failure reported while waiting (a lost camera); every
    // step below then rejects at once with that reason.
    const abort = new AbortController();
    const { signal } = abort;
    this.abortStart = abort;
    // Stages only move forward, even when a fallback backend starts over.
    let stage = -1;
    const report = (progress: StartProgress): void => {
      const index = STAGES.indexOf(progress.stage);
      if (index < stage) return;
      stage = index;
      onProgress?.(progress);
    };

    try {
      const { options, deps } = this;
      // Download the model and the WASM runtime while the camera opens: the permission
      // prompt alone can take a while, and the downloads are the slowest part of a first
      // visit. Both only have a stall timeout, so a slow connection just takes longer.
      const transfers: Transfer[] = [];
      let shown: number | null = null;
      const reportDownload = (): void => {
        const fraction = downloadFraction(transfers);
        // Never backwards, even when a download drops out of the sum.
        if (fraction !== null) shown = Math.max(shown ?? 0, fraction);
        report({ stage: 'download', fraction: shown });
      };
      const track = (): DownloadProgress => {
        const transfer: Transfer = { answered: false, received: 0, total: null };
        transfers.push(transfer);
        return (received, total) => {
          transfer.answered = true;
          transfer.received = received;
          transfer.total = total;
          if (stage === STAGES.indexOf('download')) reportDownload();
        };
      };
      const downloads =
        options.engine === 'mediapipe'
          ? Promise.all([
              deps
                .download(options.assets.modelUrl, 'application/octet-stream', track(), signal)
                .then((blob) => blob.arrayBuffer()),
              this.wasm.load(this.firstWasmBuild(), track()),
            ])
          : null;
      // Awaited below; this only keeps an early failure from being reported as unhandled.
      downloads?.catch(() => {});

      report({ stage: 'camera', fraction: null });
      const source = deps.createSource(this.initialSource());
      this.source = source;
      await abortable(source.start(), signal);
      source.setEndedHandler(this.onSourceEnded);

      if (downloads) {
        reportDownload();
        [this.modelBuffer] = await abortable(downloads, signal);
      }

      await abortable(this.segmenter.init(report), signal);

      // Warm up on a real frame through the real path, so start() only resolves once
      // frames from this source can actually be segmented.
      report({ stage: 'warmup', fraction: null });
      const firstMask = this.waitForFirstMask(signal);
      this.attach(source);
      this.scheduler.accepting = true;
      await firstMask;
      this.status = 'running';
      this.watchForStalls();
    } catch (error) {
      // Also stops a download that is still running.
      abort.abort();
      if (!this.disposed) {
        this.status = 'error';
        this.release();
      }
      throw asVisionError(error);
    } finally {
      this.abortStart = null;
      this.firstMask = null;
    }
  }

  /** The WASM build the first backend in the chain needs, downloaded during start-up. */
  private firstWasmBuild(): WasmBuild {
    return this.options.backend === 'main' ? 'classic' : 'module';
  }

  private initialSource(): SourceRequest {
    const { options } = this;
    switch (options.source) {
      case 'synthetic':
        return { kind: 'synthetic' };
      case 'clip':
        if (!options.clipUrl) throw new VisionError('clip-failed', 'No video clip was given.');
        return { kind: 'clip', src: options.clipUrl };
      case 'camera':
        return { kind: 'camera', deviceId: options.deviceId, fallbackToDefault: true };
    }
  }

  /** Read through a getter so TypeScript does not carry a narrowed status across awaits. */
  private get disposed(): boolean {
    return this.status === 'disposed';
  }

  private waitForFirstMask(signal: AbortSignal): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      let visibleMs = 0;
      const step = 250;
      const timer = setInterval(() => {
        if (!this.deps.isHidden()) visibleMs += step;
        if (visibleMs < FIRST_MASK_TIMEOUT_MS) return;
        settle();
        reject(new VisionError('segmenter-init', 'The segmenter produced no result.'));
      }, step);
      const onAbort = (): void => {
        settle();
        reject(signal.reason);
      };
      const settle = (): void => {
        clearInterval(timer);
        signal.removeEventListener('abort', onAbort);
        this.firstMask = null;
      };
      signal.addEventListener('abort', onAbort, { once: true });
      this.firstMask = () => {
        settle();
        resolve();
      };
    });
  }

  private readonly onMask = (): void => {
    this.firstMask?.();
  };

  /** Fail start-up from outside its flow (a lost source, a segmenter that cannot run). */
  private abortStarting(error: VisionError): void {
    this.abortStart?.abort(error);
  }

  // --- Running --------------------------------------------------------------------------

  private readonly onTick = (tick: FrameTick): void => {
    this.lastFrameMs = this.deps.now();
    const info = this.source?.info ?? null;
    if (info !== this.knownInfo) {
      // Sources replace their info object when the frame size changes.
      this.knownInfo = info;
      this.updateRegions();
      if (info && this.status !== 'starting') this.sourceChanges.emit(info);
    }
    this.scheduler.onTick(tick);
  };

  private readonly onSourceEnded = (error: VisionError): void => {
    if (this.status === 'starting') this.abortStarting(error);
    else this.fail(error);
  };

  private onSegmenterFailed(error: VisionError): void {
    if (this.status === 'starting') {
      this.abortStarting(
        new VisionError('segmenter-init', 'The segmenter could not process frames.', {
          cause: error,
        }),
      );
      return;
    }
    this.fail(error);
  }

  /** A fatal runtime error: stop processing, keep the display, tell the app. */
  private fail(error: VisionError): void {
    if (this.status !== 'running' && this.status !== 'paused') return;
    this.status = 'error';
    this.scheduler.accepting = false;
    this.scheduler.bumpEpoch();
    this.stopStallWatch();
    this.source?.pause();
    console.warn(`[vision] ${error.code}: ${error.message}`);
    this.errors.emit(error);
  }

  /**
   * Watch for a camera that stops delivering frames without ending its track (a frozen
   * driver, a muted track): those never raise an event of their own.
   */
  private watchForStalls(): void {
    this.stopStallWatch();
    this.lastFrameMs = this.lastStallCheckMs = this.deps.now();
    this.stallTimer = setInterval(this.checkStall, STALL_CHECK_MS);
  }

  private stopStallWatch(): void {
    clearInterval(this.stallTimer);
    this.stallTimer = undefined;
  }

  private readonly checkStall = (): void => {
    const now = this.deps.now();
    // A late check means the timer was throttled (hidden tab), so the gap says nothing.
    const late = now - this.lastStallCheckMs > 2 * STALL_CHECK_MS;
    this.lastStallCheckMs = now;
    // Only a running, visible camera owes frames: a hidden tab gets none, a switch has its
    // own time limits, and a clip goes quiet by design while it seeks back to its start.
    if (
      late ||
      this.status !== 'running' ||
      this.deps.isHidden() ||
      this.switchingNow ||
      this.source?.kind !== 'camera'
    ) {
      this.lastFrameMs = now;
      return;
    }
    if (now - this.lastFrameMs < CAMERA_STALL_MS) return;
    this.fail(new VisionError('camera-lost', 'The camera stopped sending pictures.'));
  };

  private updateRegions(): void {
    const info = this.source?.info;
    this.stats.regionsPerFrame =
      info && info.width > 0 && info.height > 0
        ? planRegions(this.layout, info.width, info.height, this.options.inputSize).regions.length
        : 0;
  }

  // --- Source switching -----------------------------------------------------------------

  private serialize<T>(task: () => Promise<T>): Promise<T> {
    const guarded = async (): Promise<T> => {
      this.switchingNow = true;
      try {
        return await task();
      } finally {
        this.switchingNow = false;
        // The new (or kept) source gets a full stall period from here.
        this.lastFrameMs = this.deps.now();
      }
    };
    const run = this.switching.then(guarded, guarded);
    this.switching = run.catch(() => {});
    return run;
  }

  private async replaceSource(request: SourceRequest): Promise<SourceInfo> {
    this.checkSwitchable();
    const current = this.source;
    if (
      request.kind === 'camera' &&
      current?.kind === 'camera' &&
      current.info &&
      current.info.deviceId === request.deviceId &&
      this.status !== 'error'
    ) {
      return current.info;
    }

    // Open the new source while the old one keeps the game going.
    const next = this.deps.createSource(request);
    try {
      return this.adopt(next, await next.start());
    } catch (error) {
      next.stop();
      const busy = error instanceof VisionError && error.code === 'camera-busy';
      if (!busy || request.kind !== 'camera' || current?.kind !== 'camera') throw error;
    }
    // Some machines cannot run two cameras at once (USB bandwidth, exclusive drivers).
    return this.replaceCameraExclusively(request, current);
  }

  /** Close the current camera first, then open the new one; reopen the old one if that fails. */
  private async replaceCameraExclusively(
    request: SourceRequest,
    current: FrameSource,
  ): Promise<SourceInfo> {
    const previousId = current.info?.deviceId ?? null;
    this.detach(current);
    current.stop();
    const next = this.deps.createSource(request);
    try {
      return this.adopt(next, await next.start());
    } catch (error) {
      next.stop();
      if (this.disposed) throw error;
      const restored = this.deps.createSource({
        kind: 'camera',
        deviceId: previousId,
        fallbackToDefault: true,
      });
      try {
        this.adopt(restored, await restored.start());
      } catch (restoreError) {
        restored.stop();
        this.fail(
          new VisionError('camera-lost', 'The camera could not be reopened.', {
            cause: restoreError,
          }),
        );
      }
      throw error;
    }
  }

  private checkSwitchable(): void {
    const { status } = this;
    const recoverable = status === 'error' && this.segmenter.running;
    if (status !== 'running' && status !== 'paused' && !recoverable) {
      throw new VisionError('unknown', 'The video source can only be changed while running.');
    }
  }

  /** Make a started source the current one. */
  private adopt(next: FrameSource, info: SourceInfo): SourceInfo {
    if (this.disposed) {
      next.stop();
      throw new VisionError('unknown', 'Vision was stopped.');
    }
    const previous = this.source;
    if (previous) this.detach(previous);
    // Nothing captured from the old source may be delivered after this point.
    this.scheduler.bumpEpoch();
    this.source = next;
    if (this.status === 'paused') {
      next.pause();
    } else if (this.status === 'error' && this.segmenter.running) {
      // A new source recovers from a lost camera.
      this.status = 'running';
      this.scheduler.accepting = true;
      this.watchForStalls();
    }
    this.attach(next);
    try {
      this.sourceChanges.emit(info);
    } catch (error) {
      // The switch itself has happened; a failing listener must not undo it.
      console.error('[vision] a source-change listener failed', error);
    }
    // Stopped only now, so the renderer has already moved to the new display.
    if (previous && previous !== next) previous.stop();
    return info;
  }

  private attach(source: FrameSource): void {
    source.setEndedHandler(this.onSourceEnded);
    source.setFrameHandler(this.onTick);
    this.knownInfo = source.info;
    this.updateRegions();
  }

  private detach(source: FrameSource): void {
    source.setFrameHandler(null);
    source.setEndedHandler(null);
  }

  private release(): void {
    this.stopStallWatch();
    this.scheduler.dispose();
    this.wasm.dispose();
    if (this.source) {
      this.detach(this.source);
      this.source.stop();
    }
    this.source = null;
    this.knownInfo = null;
    this.segmenter.dispose();
    this.modelBuffer = null;
  }
}
