/**
 * Renderer resolution (device pixels per CSS pixel) for a canvas of `cssWidth` × `cssHeight`:
 * the device pixel ratio, lowered so the backbuffer stays within `maxPixels`. A 4K TV then
 * renders about 1080p and the browser upscales, which looks the same from across a room and
 * costs a quarter of the fill rate.
 */
export function capResolution(
  cssWidth: number,
  cssHeight: number,
  devicePixelRatio: number,
  maxPixels: number,
): number {
  const width = Math.max(1, cssWidth);
  const height = Math.max(1, cssHeight);
  const dpr = devicePixelRatio > 0 ? devicePixelRatio : 1;
  let resolution = Math.min(dpr, Math.sqrt(Math.max(1, maxPixels) / (width * height)));
  // The renderer rounds the buffer size, which could overshoot the cap by a row or column.
  while (
    resolution > MIN_RESOLUTION &&
    Math.round(width * resolution) * Math.round(height * resolution) > maxPixels
  ) {
    resolution *= 0.999;
  }
  return Math.max(MIN_RESOLUTION, resolution);
}

/** Below this the picture turns to mush; a cap that low is a misconfiguration. */
const MIN_RESOLUTION = 0.25;
