import { createSfx } from '../audio';
import { resolveAssetUrls } from '../config/assets';
import { parseParams } from '../config/params';
import { createTunables } from '../config/tunables';
import { loadSavedTunables, resetTunables, saveTunables } from '../config/tunablesStore';
import { createDebugUi } from '../debug';
import { createStage } from '../render';
import {
  createBootOverlay,
  createErrorOverlay,
  createToast,
  describeStartProgress,
  describeVisionError,
} from '../ui';
import { createVision, listCameras, onCamerasChanged, VisionError } from '../vision';
import {
  enterFullscreen,
  exitFullscreen,
  IdleCursor,
  isTypingTarget,
  toggleFullscreen,
  WakeLock,
} from './platform';
import { layoutFor, MODEL_INPUT_SIZE, PlaySession } from './playSession';

const CAMERA_KEY = 'bubble-game.camera';

function element(id: string): HTMLElement {
  const found = document.getElementById(id);
  if (!found) throw new Error(`#${id} missing from index.html`);
  return found;
}

function readSavedCamera(): string | null {
  try {
    return localStorage.getItem(CAMERA_KEY);
  } catch {
    return null;
  }
}

function saveCamera(deviceId: string | null): void {
  if (!deviceId) return;
  try {
    localStorage.setItem(CAMERA_KEY, deviceId);
  } catch {
    // Persistence is a convenience.
  }
}

function asVisionError(error: unknown): VisionError {
  return error instanceof VisionError
    ? error
    : new VisionError('unknown', error instanceof Error ? error.message : String(error), {
        cause: error,
      });
}

/** Composition root: builds the services and runs the boot screen → play → boot screen cycle. */
export async function startApp(): Promise<void> {
  const params = parseParams(location.search);
  const tunables = createTunables();
  loadSavedTunables(tunables);

  const appRoot = element('app');
  const uiRoot = element('ui');
  const stage = createStage({ container: element('stage'), tunables });
  const sfx = createSfx(tunables);
  const boot = createBootOverlay(uiRoot);
  const errorOverlay = createErrorOverlay(uiRoot);
  const toast = createToast(uiRoot);
  const wakeLock = new WakeLock();
  const cursor = new IdleCursor(appRoot);

  let session: PlaySession | null = null;
  let starting = false;
  let switchingCamera = false;

  const debug = createDebugUi({
    root: uiRoot,
    tunables,
    getVision: () => session?.vision ?? null,
    getRenderStats: () => stage.stats,
    getWorld: () => session?.world ?? null,
    getLastMask: () => session?.lastMask ?? null,
    onTunablesChanged: () => {
      saveTunables(tunables);
      session?.applySettings();
    },
    actions: {
      resetTunables: () => {
        resetTunables(tunables);
        session?.applySettings();
      },
      listCameras,
      // Both hand back the promise so the debug panel can report a failure.
      switchCamera: (deviceId) =>
        session?.vision.switchCamera(deviceId).then(() => saveCamera(deviceId)),
      loadClip: (src) => session?.vision.loadClip(src),
    },
  });
  debug.setVisible(params.debug);

  const refreshCameras = (): void => {
    void listCameras().then(
      (cameras) => boot.setCameras(cameras, readSavedCamera()),
      () => boot.setCameras([], null),
    );
  };

  /** Leave play and return to the boot screen, optionally explaining why. */
  const endSession = (error: VisionError | null): void => {
    session?.dispose();
    session = null;
    wakeLock.release();
    cursor.stop();
    boot.setProgress(null);
    boot.setError(error ? describeVisionError(error) : null);
    boot.show();
    refreshCameras();
  };

  const begin = async (deviceId: string | null): Promise<void> => {
    if (starting || session) return;
    starting = true;
    boot.setError(null);
    boot.setProgress({ label: 'Starting…', fraction: null });

    const vision = createVision({
      source: params.source,
      deviceId,
      clipUrl: params.clip,
      backend: params.vision,
      engine: params.engine,
      delegate: params.delegate,
      fault: params.fault,
      assets: resolveAssetUrls(),
      inputSize: MODEL_INPUT_SIZE,
      layout: layoutFor(tunables),
    });
    try {
      await vision.start((progress) => boot.setProgress(describeStartProgress(progress)));
    } catch (error) {
      vision.dispose();
      starting = false;
      // Fixing a failed start usually needs the browser's own controls (the camera
      // permission lives in the address bar), which fullscreen hides.
      exitFullscreen();
      boot.setProgress(null);
      boot.setError(describeVisionError(asVisionError(error)));
      refreshCameras();
      return;
    }

    // Remember only a camera that was asked for and actually opened. If the pipeline fell
    // back to another one (the remembered webcam was unplugged), keep the old preference.
    if (deviceId && vision.sourceInfo?.deviceId === deviceId) saveCamera(deviceId);
    const created = new PlaySession({ params, tunables, stage, sfx, debug, vision });
    vision.onError((error) => endSession(error));
    session = created;
    starting = false;
    created.start();
    boot.setProgress(null);
    boot.hide();
    cursor.start();
    void wakeLock.acquire();
    // The tab may have been hidden while the model loaded.
    if (document.hidden) created.pause();
  };

  // Exposed before anything is awaited, so test scripts can rely on it from the first frame.
  if (params.e2e) {
    Object.assign(window, {
      __bubble: {
        params,
        tunables,
        stage,
        sfx,
        boot,
        errorOverlay,
        toast,
        debug,
        get session() {
          return session;
        },
        get vision() {
          return session?.vision ?? null;
        },
        get world() {
          return session?.world ?? null;
        },
        get round() {
          return session?.round ?? null;
        },
        get lastMask() {
          return session?.lastMask ?? null;
        },
        get view() {
          return session?.view ?? null;
        },
      },
    });
  }

  try {
    await stage.init();
  } catch (cause) {
    console.error(cause);
    boot.hide();
    errorOverlay.show({
      title: 'This browser cannot run the game',
      detail: 'Try the latest Chrome on a computer with a graphics card.',
      actionLabel: 'Reload',
      onAction: () => location.reload(),
    });
    return;
  }

  /** Switch to the next camera: the way to fix "it opened the laptop's own camera". */
  const cycleCamera = async (): Promise<void> => {
    const vision = session?.vision;
    if (!vision || switchingCamera || vision.sourceInfo?.kind !== 'camera') return;
    switchingCamera = true;
    try {
      const cameras = await listCameras();
      if (cameras.length < 2) {
        toast.show('No other camera found');
        return;
      }
      const current = cameras.findIndex((c) => c.deviceId === vision.sourceInfo?.deviceId);
      const index = (current + 1) % cameras.length;
      const next = cameras[index];
      if (!next) return;
      const info = await vision.switchCamera(next.deviceId);
      saveCamera(next.deviceId);
      toast.show(`Camera: ${info.label || `Camera ${index + 1}`}`);
    } catch {
      toast.show('Could not switch camera');
    } finally {
      switchingCamera = false;
    }
  };

  stage.onResize(() => session?.applyView());
  // Plugging a screen in or out can reset the graphics context. It normally comes back by
  // itself within a moment; the Reload button is for when it does not.
  stage.onContextLost(() => {
    errorOverlay.show({
      title: 'The display was reset',
      detail: 'One moment… If the game does not come back by itself, reload the page.',
      actionLabel: 'Reload',
      onAction: () => location.reload(),
    });
  });
  stage.onContextRestored(() => errorOverlay.hide());

  boot.onStart(({ deviceId }) => {
    // Both need the user gesture, so they happen before anything is awaited.
    void sfx.unlock();
    sfx.startMusic(resolveAssetUrls().musicUrl);
    enterFullscreen();
    void begin(deviceId);
  });
  boot.show();
  refreshCameras();
  onCamerasChanged(() => {
    if (!session) refreshCameras();
  });

  // The stage ticker only runs during play; keep the debug HUD live on the boot screen too.
  window.setInterval(() => {
    if (!session) debug.update(performance.now());
  }, 250);

  document.addEventListener('visibilitychange', () => {
    if (!session) return;
    if (document.hidden) {
      session.pause();
    } else {
      session.resume();
      // The browser drops the wake lock whenever the tab is hidden.
      void wakeLock.acquire();
    }
  });

  window.addEventListener('keydown', (event) => {
    if (event.repeat || event.ctrlKey || event.metaKey || event.altKey) return;
    if (isTypingTarget(event.target)) return;
    switch (event.key.toLowerCase()) {
      case 'd':
        debug.toggle();
        break;
      case 'm':
        sfx.setMuted(!sfx.muted);
        toast.show(sfx.muted ? 'Sound off' : 'Sound on');
        break;
      case 'c':
        void cycleCamera();
        break;
      case 'f':
        toggleFullscreen();
        break;
    }
  });

  if (params.autostart) void begin(readSavedCamera());
}
