/**
 * What the HUD shows, as plain data: one row per topic, each a list of cells with a
 * severity. Free of the DOM so the thresholds can be unit-tested.
 */
import type { RenderStats } from '../render/types';
import type { SegmenterInfo, SourceInfo, VisionStats, VisionStatus } from '../vision/types';

export type Level = 'ok' | 'dim' | 'warn' | 'bad';

export interface HudCell {
  text: string;
  level: Level;
  /** Long text that may be truncated on screen; shown in full as a tooltip. */
  full?: string;
}

export interface HudRow {
  label: string;
  cells: HudCell[];
}

export interface HudInput {
  /** `performance.now()`, the clock mask capture times use. */
  nowMs: number;
  render: RenderStats | null;
  status: VisionStatus | null;
  stats: VisionStats | null;
  source: SourceInfo | null;
  segmenter: SegmenterInfo | null;
  mask: { width: number; height: number; captureTimeMs: number } | null;
  bubbles: number | null;
  score: number | null;
  /** Source frames dropped per second, smoothed by the caller. */
  droppedPerS: number;
}

/** Where a value starts to look wrong ("warn") and clearly is ("bad"). */
export const LIMITS = {
  renderFps: { warn: 50, bad: 30 },
  frameMsP95: { warn: 20, bad: 34 },
  /** Measured camera rate as a fraction of the rate the device reports. */
  cameraRate: { warn: 0.8, bad: 0.5 },
  /** Mask rate as a fraction of the camera rate: below it the segmenter is not keeping up. */
  maskRate: { warn: 0.85, bad: 0.5 },
  /** Inference p95 as a fraction of the camera frame interval. */
  inferP95: { warn: 0.8, bad: 1.5 },
  /** Capture to mask-available; past ~100 ms pops start to feel late. */
  maskAgeMs: { warn: 100, bad: 200 },
  /** How old the newest mask is now; large means masks stopped arriving. */
  maskStaleMs: { warn: 300, bad: 1000 },
  /** The pipeline should hold at most two frames. */
  openFrames: { warn: 2, bad: 2 },
  droppedPerS: { warn: 2, bad: Number.POSITIVE_INFINITY },
} as const;

const SOFTWARE_GL = /swiftshader|llvmpipe|softpipe|software|basic render/i;

function fixed(value: number | null | undefined, digits: number): string {
  return value === null || value === undefined || !Number.isFinite(value)
    ? '–'
    : value.toFixed(digits);
}

/** Level for a value where higher is worse. */
function above(value: number, limit: { warn: number; bad: number }): Level {
  if (value > limit.bad) return 'bad';
  return value > limit.warn ? 'warn' : 'ok';
}

/** Level for a value where lower is worse. */
function below(value: number, limit: { warn: number; bad: number }): Level {
  if (value < limit.bad) return 'bad';
  return value < limit.warn ? 'warn' : 'ok';
}

const cell = (text: string, level: Level = 'ok', full?: string): HudCell =>
  full === undefined ? { text, level } : { text, level, full };

const NONE: HudCell[] = [cell('–', 'dim')];

const STATUS_LEVEL: Record<VisionStatus, Level> = {
  idle: 'dim',
  starting: 'dim',
  running: 'ok',
  paused: 'warn',
  error: 'bad',
  disposed: 'bad',
};

function renderRows({ render }: HudInput): HudRow[] {
  if (!render) {
    return [
      { label: 'render', cells: NONE },
      { label: 'buffer', cells: NONE },
    ];
  }
  const megapixels = (render.bufferWidth * render.bufferHeight) / 1e6;
  return [
    {
      label: 'render',
      cells: [
        cell(`${fixed(render.fps, 0)} fps`, below(render.fps, LIMITS.renderFps)),
        cell(`p95 ${fixed(render.frameMsP95, 1)} ms`, above(render.frameMsP95, LIMITS.frameMsP95)),
      ],
    },
    {
      label: 'buffer',
      cells: [
        cell(`${render.bufferWidth}×${render.bufferHeight}`),
        cell(`@${fixed(render.resolution, 2)}×`, 'dim'),
        cell(`${fixed(megapixels, 1)} MP`, 'dim'),
      ],
    },
  ];
}

function sourceRows({ source, stats }: HudInput): HudRow[] {
  if (!source) {
    return [
      { label: 'source', cells: NONE },
      { label: 'device', cells: NONE },
    ];
  }
  const fps = stats?.cameraFps ?? 0;
  const reported = source.frameRate;
  let level: Level = 'ok';
  if (stats && reported && reported > 0) level = below(fps / reported, LIMITS.cameraRate);
  return [
    {
      label: 'source',
      cells: [
        cell(`${fixed(fps, 1)} fps`, level),
        cell(`${source.width}×${source.height}`),
        cell(reported ? `@${fixed(reported, 0)} Hz` : '@? Hz', 'dim'),
      ],
    },
    {
      label: 'device',
      cells: [cell(source.kind, 'dim'), cell(source.label || '(no label)', 'ok', source.label)],
    },
  ];
}

function maskRows(input: HudInput): HudRow[] {
  const { stats, mask, nowMs, status } = input;
  if (!stats) {
    return [
      { label: 'mask', cells: NONE },
      { label: 'infer', cells: NONE },
      { label: 'age', cells: NONE },
      { label: 'frames', cells: NONE },
    ];
  }
  const cameraFps = stats.cameraFps;
  // Relative limits only mean something once the camera rate has settled.
  const settled = cameraFps > 5;
  const maskLevel = settled ? below(stats.maskFps / cameraFps, LIMITS.maskRate) : 'ok';
  const frameIntervalMs = settled ? 1000 / cameraFps : Number.POSITIVE_INFINITY;
  const inferLevel = above(stats.inferMsP95 / frameIntervalMs, LIMITS.inferP95);
  const staleMs = mask ? nowMs - mask.captureTimeMs : null;
  // A paused pipeline is meant to stop delivering masks.
  const staleLevel =
    staleMs !== null && status === 'running' ? above(staleMs, LIMITS.maskStaleMs) : 'dim';
  return [
    {
      label: 'mask',
      cells: [
        cell(`${fixed(stats.maskFps, 1)} fps`, maskLevel),
        cell(mask ? `${mask.width}×${mask.height}` : '–×–'),
        cell(`${stats.regionsPerFrame} region${stats.regionsPerFrame === 1 ? '' : 's'}`, 'dim'),
      ],
    },
    {
      label: 'infer',
      cells: [
        cell(`p50 ${fixed(stats.inferMsP50, 1)}`),
        cell(`p95 ${fixed(stats.inferMsP95, 1)} ms`, inferLevel),
      ],
    },
    {
      label: 'age',
      cells: [
        cell(
          `${fixed(stats.maskAgeMs, 0)} ms on arrival`,
          above(stats.maskAgeMs, LIMITS.maskAgeMs),
        ),
        cell(`${staleMs === null ? '–' : fixed(staleMs, 0)} ms now`, staleLevel),
      ],
    },
    {
      label: 'frames',
      cells: [
        cell(`open ${stats.openFrames}`, above(stats.openFrames, LIMITS.openFrames)),
        cell(`dropped ${stats.droppedFrames}`, 'dim'),
        cell(`${fixed(input.droppedPerS, 1)}/s`, above(input.droppedPerS, LIMITS.droppedPerS)),
        cell(`restarts ${stats.restarts}`, stats.restarts > 0 ? 'warn' : 'ok'),
      ],
    },
  ];
}

function modelRows({ segmenter, render }: HudInput): HudRow[] {
  const gl = segmenter?.glRenderer ?? render?.glRenderer ?? null;
  const glCell = gl ? cell(gl, SOFTWARE_GL.test(gl) ? 'warn' : 'ok', gl) : cell('–', 'dim');
  if (!segmenter) {
    return [
      { label: 'model', cells: NONE },
      { label: 'gpu', cells: [glCell] },
    ];
  }
  return [
    {
      label: 'model',
      cells: [
        // The worker is the normal path; the main thread is the fallback.
        cell(segmenter.backend, segmenter.backend === 'worker' ? 'ok' : 'warn'),
        cell(segmenter.engine, segmenter.engine === 'mediapipe' ? 'ok' : 'dim'),
        // The chroma test engine never uses the GPU, so only the model's delegate matters.
        cell(
          segmenter.delegate,
          segmenter.delegate === 'CPU' && segmenter.engine === 'mediapipe' ? 'warn' : 'ok',
        ),
        cell(`${segmenter.inputSize}px`, 'dim'),
        cell(`warm-up ${fixed(segmenter.warmupMs, 0)} ms`, 'dim'),
      ],
    },
    { label: 'gpu', cells: [glCell] },
  ];
}

export function buildHudRows(input: HudInput): HudRow[] {
  const status = input.status;
  return [
    {
      label: 'vision',
      cells: [status ? cell(status, STATUS_LEVEL[status]) : cell('not started', 'dim')],
    },
    ...renderRows(input),
    ...sourceRows(input),
    ...maskRows(input),
    ...modelRows(input),
    {
      label: 'game',
      cells:
        input.bubbles === null
          ? NONE
          : [
              cell(`${input.bubbles} bubble${input.bubbles === 1 ? '' : 's'}`),
              cell(`score ${input.score ?? 0}`),
            ],
    },
  ];
}
