/**
 * The single source of truth for where things are.
 *
 * World space: origin top-left, y down, always WORLD_HEIGHT units high; width follows the
 * screen aspect ratio. Gameplay sizes and speeds are in world units so they look the same
 * on a monitor and on a TV.
 *
 * The video is cover-fitted into the world rectangle and (normally) mirrored. Masks stay in
 * camera orientation; the mirror and the cover-fit crop are folded into the world → mask
 * mapping here. Nothing else in the codebase computes placement or mirroring.
 */

export const WORLD_HEIGHT = 1080;

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ViewInput {
  /** Screen (canvas) size in CSS pixels. */
  screenWidth: number;
  screenHeight: number;
  /** Source frame size in pixels. */
  sourceWidth: number;
  sourceHeight: number;
  /** Mask size in texels. */
  maskWidth: number;
  maskHeight: number;
  mirrored: boolean;
  /** HUD inset as a fraction of world height (TV overscan). */
  safeMargin: number;
}

export interface ViewTransform {
  readonly worldWidth: number;
  readonly worldHeight: number;
  /** CSS pixels per world unit. */
  readonly screenScale: number;
  /** Where the full video frame sits in world units. Cover-fit, so it may extend past the world rect. */
  readonly videoRect: Rect;
  readonly mirrored: boolean;
  /**
   * World → mask texel coordinates (continuous; texel i covers [i, i+1)):
   *   u = maskScaleX * x + maskOffsetX
   *   v = maskScaleY * y + maskOffsetY
   * maskScaleX is negative when mirrored.
   */
  readonly maskScaleX: number;
  readonly maskOffsetX: number;
  readonly maskScaleY: number;
  readonly maskOffsetY: number;
  readonly maskWidth: number;
  readonly maskHeight: number;
  /** Area of one mask texel in world units². */
  readonly maskTexelArea: number;
  /** HUD-safe rectangle in world units. */
  readonly safeRect: Rect;
}

export function computeView(input: ViewInput): ViewTransform {
  const screenWidth = Math.max(1, input.screenWidth);
  const screenHeight = Math.max(1, input.screenHeight);
  const sourceWidth = Math.max(1, input.sourceWidth);
  const sourceHeight = Math.max(1, input.sourceHeight);
  const maskWidth = Math.max(1, input.maskWidth);
  const maskHeight = Math.max(1, input.maskHeight);

  const worldHeight = WORLD_HEIGHT;
  const worldWidth = (worldHeight * screenWidth) / screenHeight;
  const screenScale = screenHeight / worldHeight;

  // Cover-fit the source frame into the world rectangle.
  const cover = Math.max(worldWidth / sourceWidth, worldHeight / sourceHeight);
  const videoWidth = sourceWidth * cover;
  const videoHeight = sourceHeight * cover;
  const videoRect: Rect = {
    x: (worldWidth - videoWidth) / 2,
    y: (worldHeight - videoHeight) / 2,
    width: videoWidth,
    height: videoHeight,
  };

  // Unmirrored: u = (x - videoRect.x) / videoWidth * maskWidth.
  // Mirrored:   u = (1 - (x - videoRect.x) / videoWidth) * maskWidth.
  const sx = maskWidth / videoWidth;
  const maskScaleX = input.mirrored ? -sx : sx;
  const maskOffsetX = input.mirrored ? maskWidth + videoRect.x * sx : -videoRect.x * sx;
  const maskScaleY = maskHeight / videoHeight;
  const maskOffsetY = -videoRect.y * maskScaleY;

  const inset = Math.max(0, input.safeMargin) * worldHeight;
  const safeRect: Rect = {
    x: inset,
    y: inset,
    width: Math.max(0, worldWidth - 2 * inset),
    height: Math.max(0, worldHeight - 2 * inset),
  };

  return {
    worldWidth,
    worldHeight,
    screenScale,
    videoRect,
    mirrored: input.mirrored,
    maskScaleX,
    maskOffsetX,
    maskScaleY,
    maskOffsetY,
    maskWidth,
    maskHeight,
    maskTexelArea: (videoWidth / maskWidth) * (videoHeight / maskHeight),
    safeRect,
  };
}

/** Continuous mask u coordinate for a world x. */
export function worldToMaskU(view: ViewTransform, x: number): number {
  return view.maskScaleX * x + view.maskOffsetX;
}

/** Continuous mask v coordinate for a world y. */
export function worldToMaskV(view: ViewTransform, y: number): number {
  return view.maskScaleY * y + view.maskOffsetY;
}

/** World x of the centre of mask texel column `u`. */
export function maskToWorldX(view: ViewTransform, u: number): number {
  return (u + 0.5 - view.maskOffsetX) / view.maskScaleX;
}

/** World y of the centre of mask texel row `v`. */
export function maskToWorldY(view: ViewTransform, v: number): number {
  return (v + 0.5 - view.maskOffsetY) / view.maskScaleY;
}

/** World position of a source-frame pixel (e.g. where a camera pixel appears on screen). */
export function sourceToWorld(
  view: ViewTransform,
  sourceX: number,
  sourceY: number,
  sourceWidth: number,
  sourceHeight: number,
): { x: number; y: number } {
  const s = sourceX / sourceWidth;
  const t = sourceY / sourceHeight;
  return {
    x: view.videoRect.x + (view.mirrored ? 1 - s : s) * view.videoRect.width,
    y: view.videoRect.y + t * view.videoRect.height,
  };
}
