/** Frame delivery from a <video> element, shared by the camera and clip sources. */
import type { FrameTick } from './types';

/**
 * Calls `handler` once per presented frame, via requestVideoFrameCallback (which works on
 * a <video> that is not in the DOM). The ticker is itself the `FrameTick` it hands out, so
 * no objects are created per frame apart from the VideoFrame a `grab()` returns.
 */
export class VideoTicker implements FrameTick {
  captureTimeMs = 0;
  handler: ((tick: FrameTick) => void) | null = null;

  private callbackId = 0;
  private running = false;
  private readonly frameInit: VideoFrameInit = { timestamp: 0 };

  constructor(private readonly video: HTMLVideoElement) {}

  start(): void {
    if (this.running) return;
    this.running = true;
    this.callbackId = this.video.requestVideoFrameCallback(this.onFrame);
  }

  stop(): void {
    this.running = false;
    this.video.cancelVideoFrameCallback(this.callbackId);
  }

  grab(): VideoFrame {
    return new VideoFrame(this.video, this.frameInit);
  }

  private readonly onFrame = (now: number, metadata: VideoFrameCallbackMetadata): void => {
    if (!this.running) return;
    this.callbackId = this.video.requestVideoFrameCallback(this.onFrame);
    // Camera frames carry the time they were captured, which makes mask age honest. Clips
    // do not; and a capture time from an odd clock would poison the stats, so check it.
    const capture = metadata.captureTime;
    this.captureTimeMs =
      capture !== undefined && capture <= now && now - capture < 1000 ? capture : now;
    this.frameInit.timestamp = Math.round(this.captureTimeMs * 1000);
    this.handler?.(this);
  };
}

export function supportsVideoFrames(): boolean {
  return (
    typeof VideoFrame !== 'undefined' &&
    typeof HTMLVideoElement !== 'undefined' &&
    'requestVideoFrameCallback' in HTMLVideoElement.prototype
  );
}

/** A muted, inline <video> for frame capture; it is never added to the DOM. */
export function createVideoElement(): HTMLVideoElement {
  const video = document.createElement('video');
  video.muted = true;
  video.playsInline = true;
  video.disablePictureInPicture = true;
  return video;
}

/**
 * Start playback and wait until a frame can be grabbed. Rejects on a media error, a
 * refused `play()`, or when nothing arrives within `timeoutMs`.
 */
export function playUntilFirstFrame(video: HTMLVideoElement, timeoutMs: number): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    let settled = false;
    const finish = (error?: unknown): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      video.removeEventListener('loadeddata', check);
      video.removeEventListener('playing', check);
      video.removeEventListener('error', onError);
      if (error === undefined) resolve();
      else reject(error);
    };
    const check = (): void => {
      if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA && !video.paused) finish();
    };
    const onError = (): void => finish(video.error ?? new Error('The video could not be loaded.'));
    const timer = setTimeout(() => finish(new Error('No video frame arrived in time.')), timeoutMs);
    video.addEventListener('loadeddata', check);
    video.addEventListener('playing', check);
    video.addEventListener('error', onError);
    video.play().then(check, (error: unknown) => finish(error ?? new Error('play() failed')));
  });
}
