/**
 * Everything the round shows on top of the picture: a numbered tag over each player's head,
 * score chips along the top, the clock, and the big messages in the middle (waiting,
 * countdown, GO, the winner). Sized in world units to be read from across a room.
 */
import { Container, NineSliceSprite, Text, type Texture } from 'pixi.js';
import type { ViewTransform } from '../core/view';
import {
  MAX_PLAYERS,
  type Player,
  type Round,
  type RoundEvent,
  type RoundPhase,
} from '../game/types';

/** One colour per player slot, far apart in hue and bright enough to read on video. */
export const PLAYER_COLORS: readonly number[] = [0xff5470, 0x45a5ff, 0xffcc33, 0x47e08a];
/** The same colours as hues, for tinting particle bursts. */
export const PLAYER_HUES: readonly number[] = [350, 212, 45, 146];

const FONT_FAMILY = [
  'Nunito',
  'Fredoka',
  'Varela Round',
  'Arial Rounded MT Bold',
  'Segoe UI',
  'system-ui',
  'sans-serif',
];
const OUTLINE = 0x0b2545;

const CHIP_HEIGHT = 116;
const CHIP_PAD = 28;
const CHIP_GAP = 20;
const CHIP_NAME_SIZE = 62;
const CHIP_SCORE_SIZE = 96;
const TAG_HEIGHT = 84;
const TAG_SIZE = 58;
/** The tag floats this far above the top of the head. */
const TAG_LIFT = 70;
/** How quickly a tag follows its player: higher is tighter. */
const TAG_FOLLOW = 14;
const BIG_SIZE = 400;
const TITLE_SIZE = 116;
const SUBTITLE_SIZE = 64;
/** The clock turns red and pulses for the last seconds of a round. */
const HURRY_SECONDS = 5;
const HURRY_COLOR = 0xff5470;
const GO_SHOWN_S = 0.9;
const PLUS_POOL = 12;
const PLUS_LIFE_S = 0.7;
const PLUS_RISE = 170;
/** Confetti for the winner: one burst this often for this long. */
const CONFETTI_EVERY_S = 0.16;
const CONFETTI_FOR_S = 3;

/** Swell and settle, the same shape for every "something happened" bounce. */
function bounce(t: number, peak: number): number {
  const attack = 0.06;
  if (t < attack) {
    const k = t / attack;
    return 1 + peak * k * (2 - k);
  }
  const s = t - attack;
  const settle = Math.exp(-s * 9);
  if (settle < 0.002) return 1;
  return 1 + peak * settle * Math.cos(2 * Math.PI * 2.6 * s);
}

function makeText(size: number, fill = 0xffffff, anchorX = 0.5): Text {
  return new Text({
    text: '',
    anchor: { x: anchorX, y: 0.5 },
    style: {
      fontFamily: FONT_FAMILY,
      fontWeight: '900',
      fontSize: size,
      fill,
      stroke: { color: OUTLINE, width: Math.max(6, size * 0.1), join: 'round' },
      dropShadow: { color: 0x000000, alpha: 0.4, blur: 6, distance: 5, angle: Math.PI / 2 },
      padding: Math.ceil(size * 0.12),
    },
  });
}

/** Width of the glyphs alone: the style's padding is part of `text.width`. */
function inkWidth(text: Text): number {
  return text.text === '' ? 0 : text.width - 2 * (text.style.padding ?? 0);
}

function makeCapsule(texture: Texture, height: number): NineSliceSprite {
  const slice = texture.width / 2;
  const sprite = new NineSliceSprite({
    texture,
    leftWidth: slice,
    rightWidth: slice,
    topHeight: slice,
    bottomHeight: slice,
  });
  sprite.height = height;
  sprite.y = -height / 2;
  return sprite;
}

function playerName(slot: number): string {
  return `Player ${slot + 1}`;
}

interface Chip {
  container: Container;
  capsule: NineSliceSprite;
  name: Text;
  score: Text;
  shownScore: number;
  showsScore: boolean;
  width: number;
  bounceS: number;
}

interface Tag {
  container: Container;
  placed: boolean;
  bounceS: number;
}

interface Plus {
  text: Text;
  ageS: number;
  x: number;
  y: number;
}

export class RoundHud {
  readonly container = new Container();

  private readonly chips: Chip[] = [];
  private readonly tags: Tag[] = [];
  private readonly pluses: Plus[] = [];
  private readonly clock = new Container();
  private readonly clockCapsule: NineSliceSprite;
  private readonly clockText = makeText(CHIP_SCORE_SIZE);
  private readonly big = makeText(BIG_SIZE);
  private readonly title = makeText(TITLE_SIZE);
  private readonly subtitle = makeText(SUBTITLE_SIZE);
  private readonly texts: Text[];

  private view: ViewTransform | null = null;
  private phase: RoundPhase | null = null;
  private phaseS = 0;
  private shownSeconds = -1;
  private shownCount = -1;
  private secondS = Number.POSITIVE_INFINITY;
  private confettiS = 0;

  constructor(capsule: Texture) {
    const tagLayer = new Container();
    const chipLayer = new Container();
    const plusLayer = new Container();
    for (let slot = 0; slot < MAX_PLAYERS; slot++) {
      const color = PLAYER_COLORS[slot] as number;

      const chip: Chip = {
        container: new Container(),
        capsule: makeCapsule(capsule, CHIP_HEIGHT),
        name: makeText(CHIP_NAME_SIZE, color, 0),
        score: makeText(CHIP_SCORE_SIZE, 0xffffff, 0),
        shownScore: -1,
        showsScore: false,
        width: 0,
        bounceS: Number.POSITIVE_INFINITY,
      };
      chip.name.text = `P${slot + 1}`;
      chip.name.position.set(CHIP_PAD, 3);
      chip.container.addChild(chip.capsule, chip.name, chip.score);
      chip.container.visible = false;
      chipLayer.addChild(chip.container);
      this.chips.push(chip);

      const tag: Tag = {
        container: new Container(),
        placed: false,
        bounceS: Number.POSITIVE_INFINITY,
      };
      const tagText = makeText(TAG_SIZE, color);
      tagText.text = `P${slot + 1}`;
      tagText.y = 2;
      const tagBack = makeCapsule(capsule, TAG_HEIGHT);
      tagBack.width = inkWidth(tagText) + 2 * CHIP_PAD;
      tagBack.x = -tagBack.width / 2;
      tag.container.addChild(tagBack, tagText);
      tag.container.visible = false;
      tagLayer.addChild(tag.container);
      this.tags.push(tag);
    }
    for (let i = 0; i < PLUS_POOL; i++) {
      const text = makeText(84);
      text.text = '+1';
      text.visible = false;
      plusLayer.addChild(text);
      this.pluses.push({ text, ageS: Number.POSITIVE_INFINITY, x: 0, y: 0 });
    }

    this.clockCapsule = makeCapsule(capsule, CHIP_HEIGHT);
    this.clockText.y = 4;
    this.clock.addChild(this.clockCapsule, this.clockText);
    this.clock.visible = false;

    this.container.addChild(tagLayer, plusLayer, chipLayer, this.clock);
    this.container.addChild(this.big, this.title, this.subtitle);
    this.texts = [
      this.clockText,
      this.big,
      this.title,
      this.subtitle,
      ...this.pluses.map((plus) => plus.text),
      ...this.chips.flatMap((chip) => [chip.name, chip.score]),
      ...this.tags.map((tag) => tag.container.children[1] as Text),
    ];
  }

  setView(view: ViewTransform): void {
    this.view = view;
    // Forces the middle texts to be re-fitted to the new width.
    this.phase = null;
  }

  /** Render text at the device pixel density it ends up at, bounces included. */
  setPixelsPerUnit(pixelsPerUnit: number): void {
    for (const text of this.texts) text.resolution = pixelsPerUnit * 1.25;
  }

  /**
   * Follow the round. `confetti` is called with a place, a size and a hue whenever a burst
   * of particles should go off (the stage owns the particles).
   */
  update(
    round: Round,
    events: readonly RoundEvent[],
    dtS: number,
    confetti: (x: number, y: number, r: number, hue: number) => void,
  ): void {
    const view = this.view;
    if (!view) return;

    for (const event of events) {
      if (event.type === 'join') {
        const tag = this.tags[event.slot];
        const chip = this.chips[event.slot];
        if (tag) {
          tag.bounceS = 0;
          tag.placed = false;
        }
        if (chip) chip.bounceS = 0;
      } else if (event.type === 'point') {
        const chip = this.chips[event.slot];
        if (chip) chip.bounceS = 0;
        this.spawnPlus(event.slot, event.x, event.y - event.r * 0.6);
      }
    }

    if (round.phase !== this.phase) this.enterPhase(round, view);
    this.phaseS += dtS;
    this.secondS += dtS;

    const seconds = Math.ceil(round.remainingS);
    if (round.phase === 'countdown') {
      if (seconds !== this.shownSeconds) {
        this.shownSeconds = seconds;
        this.big.text = String(Math.max(1, seconds));
        this.secondS = 0;
      }
      if (round.playerCount !== this.shownCount) {
        this.shownCount = round.playerCount;
        const count = round.playerCount;
        this.subtitle.text =
          count >= MAX_PLAYERS
            ? `${count} players`
            : `${count} player${count === 1 ? '' : 's'} · wave to join`;
        this.fit(this.subtitle, view);
      }
      this.big.scale.set(bounce(this.secondS, 0.18));
    } else if (round.phase === 'playing') {
      if (seconds !== this.shownSeconds) {
        this.shownSeconds = seconds;
        this.clockText.text = String(seconds);
        const hurry = seconds <= HURRY_SECONDS;
        this.clockText.style.fill = hurry ? HURRY_COLOR : 0xffffff;
        if (hurry) this.secondS = 0;
        this.clockCapsule.width = Math.max(
          CHIP_HEIGHT * 1.6,
          inkWidth(this.clockText) + 2 * CHIP_PAD,
        );
        this.clockCapsule.x = -this.clockCapsule.width;
        this.clockText.x = -this.clockCapsule.width / 2;
      }
      this.clock.scale.set(seconds <= HURRY_SECONDS ? bounce(this.secondS, 0.2) : 1);
      // "GO!" swells and fades out over the first moment of play.
      const go = this.phaseS / GO_SHOWN_S;
      this.big.visible = go < 1;
      this.big.alpha = Math.min(1, 2.5 * (1 - go));
      this.big.scale.set(0.8 + 0.5 * go);
    } else if (round.phase === 'results') {
      this.title.scale.set(this.titleFit * bounce(this.phaseS, 0.25));
      const winner = round.winners[0];
      if (winner !== undefined && this.phaseS < CONFETTI_FOR_S) {
        this.confettiS -= dtS;
        if (this.confettiS <= 0) {
          this.confettiS = CONFETTI_EVERY_S;
          const pick = round.winners[Math.floor(Math.random() * round.winners.length)] ?? winner;
          confetti(
            view.worldWidth * (0.1 + 0.8 * Math.random()),
            view.worldHeight * (0.12 + 0.6 * Math.random()),
            60 + 50 * Math.random(),
            PLAYER_HUES[pick] ?? 0,
          );
        }
      }
    } else {
      // Waiting: a slow breath so the screen does not look frozen.
      this.title.scale.set(this.titleFit * (1 + 0.025 * Math.sin(this.phaseS * 2.2)));
    }

    this.layoutChips(round, view, dtS);
    this.followPlayers(round, view, dtS);
    this.animatePluses(dtS);
  }

  /** Back to nothing shown, as before the first session. */
  reset(): void {
    this.phase = null;
    this.shownSeconds = -1;
    this.shownCount = -1;
    for (const chip of this.chips) chip.container.visible = false;
    for (const tag of this.tags) {
      tag.container.visible = false;
      tag.placed = false;
    }
    for (const plus of this.pluses) {
      plus.text.visible = false;
      plus.ageS = Number.POSITIVE_INFINITY;
    }
    this.clock.visible = false;
    this.big.visible = false;
    this.title.visible = false;
    this.subtitle.visible = false;
  }

  dispose(): void {
    this.container.destroy({ children: true });
  }

  /** Scale that makes the title fit the safe width; bounces multiply it. */
  private titleFit = 1;

  private fit(text: Text, view: ViewTransform): number {
    text.scale.set(1);
    const scale = Math.min(1, view.safeRect.width / Math.max(1, inkWidth(text)));
    text.scale.set(scale);
    return scale;
  }

  private enterPhase(round: Round, view: ViewTransform): void {
    const { big, title, subtitle } = this;
    this.phase = round.phase;
    this.phaseS = 0;
    this.shownSeconds = -1;
    this.shownCount = -1;
    this.secondS = Number.POSITIVE_INFINITY;
    this.confettiS = 0;
    const centreX = view.worldWidth / 2;
    const h = view.worldHeight;
    big.visible = false;
    big.alpha = 0.95;
    big.scale.set(1);
    title.visible = true;
    subtitle.visible = true;
    title.style.fill = 0xffffff;
    this.clock.visible = round.phase === 'playing';
    this.clock.position.set(
      view.safeRect.x + view.safeRect.width,
      view.safeRect.y + CHIP_HEIGHT / 2,
    );

    switch (round.phase) {
      case 'waiting':
        title.text = 'Wave to join!';
        subtitle.text = 'Up to 4 players';
        title.position.set(centreX, h * 0.42);
        subtitle.position.set(centreX, h * 0.55);
        break;
      case 'countdown':
        title.text = 'Get ready!';
        subtitle.text = '';
        big.visible = true;
        title.position.set(centreX, h * 0.2);
        big.position.set(centreX, h * 0.5);
        subtitle.position.set(centreX, h * 0.8);
        break;
      case 'playing':
        title.visible = false;
        subtitle.visible = false;
        big.text = 'GO!';
        big.visible = true;
        big.position.set(centreX, h * 0.5);
        break;
      case 'results': {
        const { winners, players } = round;
        const first = winners[0];
        if (first === undefined) {
          title.text = "Time's up!";
          subtitle.text = 'Nobody popped a bubble';
        } else if (winners.length === 1) {
          const score = players[first]?.score ?? 0;
          title.text = round.playerCount > 1 ? `${playerName(first)} wins!` : 'Well done!';
          title.style.fill = PLAYER_COLORS[first] ?? 0xffffff;
          subtitle.text = `${score} bubble${score === 1 ? '' : 's'}`;
        } else {
          const score = players[first]?.score ?? 0;
          title.text = "It's a tie!";
          subtitle.text = `${winners.map((slot) => playerName(slot)).join(' & ')} · ${score} each`;
        }
        title.position.set(centreX, h * 0.4);
        subtitle.position.set(centreX, h * 0.54);
        break;
      }
    }
    this.titleFit = this.fit(title, view);
    this.fit(subtitle, view);
  }

  private layoutChips(round: Round, view: ViewTransform, dtS: number): void {
    const showScores = round.phase === 'playing' || round.phase === 'results';
    let x = view.safeRect.x;
    const y = view.safeRect.y + CHIP_HEIGHT / 2;
    for (let slot = 0; slot < MAX_PLAYERS; slot++) {
      const chip = this.chips[slot] as Chip;
      const player = round.players[slot] as Player;
      chip.container.visible = player.active;
      if (!player.active) {
        chip.shownScore = -1;
        continue;
      }
      if (
        chip.width === 0 ||
        chip.showsScore !== showScores ||
        (showScores && chip.shownScore !== player.score)
      ) {
        chip.showsScore = showScores;
        chip.shownScore = player.score;
        chip.score.text = showScores ? String(player.score) : '';
        const nameEnd = CHIP_PAD + inkWidth(chip.name);
        chip.score.position.set(nameEnd + 18, 4);
        chip.width = (showScores ? chip.score.x + inkWidth(chip.score) : nameEnd) + CHIP_PAD;
        chip.capsule.width = chip.width;
      }
      chip.bounceS += dtS;
      const winner = round.phase === 'results' && round.winners.includes(slot);
      // Scale about the chip's left middle, so a bounce never pushes it out of the margin.
      chip.container.position.set(x, y);
      chip.container.scale.set(bounce(chip.bounceS, 0.22) * (winner ? 1.12 : 1));
      chip.container.alpha =
        round.phase === 'results' && round.winners.length > 0 && !winner ? 0.7 : 1;
      x += chip.width * (winner ? 1.12 : 1) + CHIP_GAP;
    }
  }

  private followPlayers(round: Round, view: ViewTransform, dtS: number): void {
    const follow = 1 - Math.exp(-dtS * TAG_FOLLOW);
    const half = TAG_HEIGHT / 2;
    for (let slot = 0; slot < MAX_PLAYERS; slot++) {
      const tag = this.tags[slot] as Tag;
      const player = round.players[slot] as Player;
      tag.container.visible = player.active;
      if (!player.active) {
        tag.placed = false;
        continue;
      }
      // Keep the tag on screen even when the head is above or beside the picture.
      const targetX = Math.min(view.worldWidth - 80, Math.max(80, player.headX));
      const targetY = Math.min(view.worldHeight - half, Math.max(half, player.headY - TAG_LIFT));
      const { position } = tag.container;
      if (tag.placed) {
        position.set(
          position.x + (targetX - position.x) * follow,
          position.y + (targetY - position.y) * follow,
        );
      } else {
        position.set(targetX, targetY);
        tag.placed = true;
      }
      tag.bounceS += dtS;
      tag.container.scale.set(bounce(tag.bounceS, 0.5));
      tag.container.alpha = player.seen ? 1 : 0.4;
    }
  }

  private spawnPlus(slot: number, x: number, y: number): void {
    // Reuse the oldest: a burst of points never waits for a free one.
    let oldest = this.pluses[0] as Plus;
    for (const plus of this.pluses) {
      if (plus.ageS > oldest.ageS) oldest = plus;
    }
    oldest.ageS = 0;
    oldest.x = x;
    oldest.y = y;
    oldest.text.style.fill = PLAYER_COLORS[slot] ?? 0xffffff;
    oldest.text.visible = true;
  }

  private animatePluses(dtS: number): void {
    for (const plus of this.pluses) {
      if (!plus.text.visible) continue;
      plus.ageS += dtS;
      const t = plus.ageS / PLUS_LIFE_S;
      if (t >= 1) {
        plus.text.visible = false;
        plus.ageS = Number.POSITIVE_INFINITY;
        continue;
      }
      // Fast at first, easing out; solid for the first half, then fading.
      plus.text.position.set(plus.x, plus.y - PLUS_RISE * (1 - (1 - t) * (1 - t)));
      plus.text.alpha = Math.min(1, 2 * (1 - t));
      plus.text.scale.set(bounce(plus.ageS, 0.3));
    }
  }
}
