/**
 * Procedural artwork. Every texture the stage draws is computed here at init into a
 * premultiplied RGBA buffer; there are no image files. Pure functions (no Pixi, no DOM) so
 * they can be unit-tested.
 *
 * Premultiplied alpha is what lets one texture both glow and occlude: RGB is light added on
 * top of the picture and A is how much of the picture it hides. A bubble rim can then
 * brighten a dark room and still darken a white wall, so it reads over both.
 */
import { createRng } from '../core/rng';

export interface Image {
  readonly width: number;
  readonly height: number;
  /** Premultiplied RGBA, row-major. */
  readonly data: Uint8Array;
}

export interface Frame {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
}

const clamp01 = (x: number): number => (x < 0 ? 0 : x > 1 ? 1 : x);

const smoothstep = (edge0: number, edge1: number, x: number): number => {
  const t = clamp01((x - edge0) / (edge1 - edge0));
  return t * t * (3 - 2 * t);
};

const gauss = (x: number, mu: number, sigma: number): number => {
  const t = (x - mu) / sigma;
  return Math.exp(-0.5 * t * t);
};

/** Angle difference wrapped to [-π, π]. */
const angleDelta = (a: number, b: number): number => {
  let d = a - b;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  return d;
};

function writePixel(
  data: Uint8Array,
  index: number,
  r: number,
  g: number,
  b: number,
  a: number,
): void {
  const offset = index * 4;
  data[offset] = Math.round(clamp01(r) * 255);
  data[offset + 1] = Math.round(clamp01(g) * 255);
  data[offset + 2] = Math.round(clamp01(b) * 255);
  data[offset + 3] = Math.round(clamp01(a) * 255);
}

// ---------------------------------------------------------------------------
// Thin-film interference
// ---------------------------------------------------------------------------

const FILM_INDEX = 1.33;
/** Thickest film the colour table covers, in nm. Thicker films wash out to white anyway. */
const FILM_MAX_NM = 1400;
const LUT_SIZE = 1024;

/** One lobe of the Wyman–Sloan–Shirley analytic fit to the CIE 1931 colour matching functions. */
const lobe = (x: number, mu: number, below: number, above: number): number =>
  gauss(x, mu, x < mu ? below : above);

/**
 * Colour reflected by a soap film as a function of thickness: sRGB triples (0..1) for
 * thicknesses 0..FILM_MAX_NM. Two-beam interference, R(λ) ∝ sin²(2π n d / λ), integrated
 * against the colour matching functions and normalised so a white spectrum maps to white.
 * This gives the real sequence of soap-bubble colours (black, silver, gold, magenta, blue,
 * green, pastel) rather than a rainbow.
 */
export function thinFilmTable(): Float32Array {
  const wavelengths: number[] = [];
  const weights: Array<[number, number, number]> = [];
  for (let lambda = 380; lambda <= 730; lambda += 5) {
    const x =
      1.056 * lobe(lambda, 599.8, 37.9, 31.0) +
      0.362 * lobe(lambda, 442.0, 16.0, 26.7) -
      0.065 * lobe(lambda, 501.1, 20.4, 26.2);
    const y = 0.821 * lobe(lambda, 568.8, 46.9, 40.5) + 0.286 * lobe(lambda, 530.9, 16.3, 31.1);
    const z = 1.217 * lobe(lambda, 437.0, 11.8, 36.0) + 0.681 * lobe(lambda, 459.0, 26.0, 13.8);
    wavelengths.push(lambda);
    weights.push([
      3.2406 * x - 1.5372 * y - 0.4986 * z,
      -0.9689 * x + 1.8758 * y + 0.0415 * z,
      0.0557 * x - 0.204 * y + 1.057 * z,
    ]);
  }
  const white = [0, 0, 0];
  for (const weight of weights) for (let c = 0; c < 3; c++) white[c] += weight[c] as number;

  const table = new Float32Array(LUT_SIZE * 3);
  for (let i = 0; i < LUT_SIZE; i++) {
    const thickness = (i / (LUT_SIZE - 1)) * FILM_MAX_NM;
    const rgb = [0, 0, 0];
    for (let w = 0; w < wavelengths.length; w++) {
      const s = Math.sin((2 * Math.PI * FILM_INDEX * thickness) / (wavelengths[w] as number));
      const reflect = s * s;
      const weight = weights[w] as [number, number, number];
      for (let c = 0; c < 3; c++) rgb[c] += reflect * weight[c];
    }
    // Normalise to white, push saturation a little (real film colours are subtle on camera),
    // then encode to sRGB because Pixi blends in display space.
    const linear = rgb.map((value, c) => Math.max(0, value / (white[c] as number)));
    const grey = (linear[0] + linear[1] + linear[2]) / 3;
    for (let c = 0; c < 3; c++) {
      const saturated = clamp01(grey + ((linear[c] as number) - grey) * 1.35);
      table[i * 3 + c] = saturated ** (1 / 2.2);
    }
  }
  return table;
}

interface FilmParams {
  /** Mean film thickness in nm; sets the dominant colour. */
  base: number;
  /** Swirl amplitude in nm. */
  swirl: number;
  phases: number[];
}

/** Film thickness at a point on the bubble (unit disc, y down), in nm. */
function filmThickness(u: number, v: number, params: FilmParams): number {
  const p = params.phases as [number, number, number, number, number, number];
  // Gravity drains the film: thin at the top, thick at the bottom.
  const drain = 0.55 + 0.6 * (v * 0.5 + 0.5);
  // Domain-warped waves read as the marbled swirls of a real film.
  const wu = u + 0.3 * Math.sin(2.7 * v + p[0]) + 0.12 * Math.sin(5.3 * v + 4.1 * u + p[1]);
  const wv = v + 0.3 * Math.sin(2.3 * u + p[2]);
  const swirl =
    0.55 * Math.sin(3.4 * wu + 2.2 * wv + p[3]) +
    0.3 * Math.sin(-2.6 * wu + 4.4 * wv + p[4]) +
    0.15 * Math.sin(7.9 * wu - 6.7 * wv + p[5]);
  return params.base * drain + params.swirl * swirl;
}

// ---------------------------------------------------------------------------
// Bubble
// ---------------------------------------------------------------------------

/** Distinct film looks; a bubble's hue picks one. */
export const SHELL_VARIANTS = 4;
const VARIANT_BASE_NM = [330, 450, 560, 700];

/** Fraction of the texture's half-size where the bubble's edge sits (the rest is padding). */
export const SHELL_EDGE = 0.985;

/**
 * The bubble's body and rim, meant to be drawn at radius r with the sprite `2r / SHELL_EDGE`
 * wide. Rotationally symmetric apart from the film pattern, so it can turn freely:
 * - a nearly clear body (the child stays visible) with faint film colour,
 * - film reflection that strengthens toward the rim (Fresnel), coloured by thickness,
 * - a thin bright line just inside the edge, for dark rooms,
 * - a thin dark line at the very edge, for bright walls.
 */
export function bubbleShell(size: number, variant: number, table: Float32Array): Image {
  const data = new Uint8Array(size * size * 4);
  const rng = createRng(0x5eed + variant * 7919);
  const params: FilmParams = {
    base: VARIANT_BASE_NM[variant % VARIANT_BASE_NM.length] as number,
    swirl: 150 + 60 * rng.next(),
    phases: Array.from({ length: 6 }, () => rng.range(0, 2 * Math.PI)),
  };
  const half = size / 2;
  const radius = half * SHELL_EDGE;
  const profile = shellProfile(radius);

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const u = (x + 0.5 - half) / radius;
      const v = (y + 0.5 - half) / radius;
      const rho = Math.sqrt(u * u + v * v);
      const step = Math.round(rho * PROFILE_STEPS);
      if (step >= profile.coverage.length) continue;
      const coverage = profile.coverage[step] as number;
      if (coverage <= 0) continue;

      const thickness = filmThickness(u, v, params) * (profile.cosT[step] as number);
      const t = Math.round(clamp01(thickness / FILM_MAX_NM) * (LUT_SIZE - 1)) * 3;
      const fr = table[t] as number;
      const fg = table[t + 1] as number;
      const fb = table[t + 2] as number;

      // Body haze: barely there, slightly cool.
      let a = 0.03;
      let cr = 0.024;
      let cg = 0.026;
      let cb = 0.03;

      // Film reflection over the body. Part occludes (so it tints bright walls), part adds
      // (so it glows over a dark room).
      const reflect = profile.reflect[step] as number;
      const filmAlpha = 0.32 * reflect;
      const filmLight = filmAlpha + 0.4 * reflect;
      cr = fr * filmLight + cr * (1 - filmAlpha);
      cg = fg * filmLight + cg * (1 - filmAlpha);
      cb = fb * filmLight + cb * (1 - filmAlpha);
      a = filmAlpha + a * (1 - filmAlpha);

      // Bright inner rim, mostly additive, lightly film-tinted.
      const rim = profile.rim[step] as number;
      cr += 0.42 * rim * (0.6 + 0.4 * fr);
      cg += 0.42 * rim * (0.6 + 0.4 * fg);
      cb += 0.42 * rim * (0.6 + 0.4 * fb);
      a = 0.1 * rim + a * (1 - 0.1 * rim);

      // Dark outline at the very edge: deep blue-violet, mostly occluding.
      const edge = profile.edge[step] as number;
      cr = 0.07 * edge + cr * (1 - edge);
      cg = 0.06 * edge + cg * (1 - edge);
      cb = 0.14 * edge + cb * (1 - edge);
      a = edge + a * (1 - edge);

      writePixel(data, y * size + x, cr * coverage, cg * coverage, cb * coverage, a * coverage);
    }
  }
  return { width: size, height: size, data };
}

/** Radial resolution of the shell's profile table, in steps per unit radius. */
const PROFILE_STEPS = 2048;

/**
 * Everything about the shell that depends only on distance from the centre, tabulated once
 * so the per-pixel loop is mostly the film pattern.
 */
function shellProfile(radiusPx: number) {
  const steps = PROFILE_STEPS + Math.ceil((2 * PROFILE_STEPS) / radiusPx) + 1;
  const coverage = new Float32Array(steps);
  const cosT = new Float32Array(steps);
  const reflect = new Float32Array(steps);
  const rim = new Float32Array(steps);
  const edge = new Float32Array(steps);
  const aa = 1.25 / radiusPx;
  for (let i = 0; i < steps; i++) {
    const rho = i / PROFILE_STEPS;
    const r = Math.min(rho, 1);
    coverage[i] = smoothstep(1 + aa, 1 - aa, rho);
    // Light crosses the film at a slant near the rim, so the path is shorter and the
    // colour shifts, as on a real bubble.
    cosT[i] = Math.sqrt(1 - (r * r) / (FILM_INDEX * FILM_INDEX));
    // Fresnel-like: the centre stays clear so the child shows through; colour gathers at the rim.
    reflect[i] = 0.05 + 0.95 * smoothstep(0.45, 0.99, r) ** 2;
    rim[i] = gauss(r, 0.955, 0.017);
    edge[i] = 0.55 * gauss(r, 0.99, 0.011);
  }
  return { coverage, cosT, reflect, rim, edge };
}

/**
 * Lighting that stays put while the shell turns: a curved window reflection at the upper
 * left, a sharp glint, a fainter bounce light at the lower right, and a touch of shade along
 * the bottom rim so the bubble looks round over a bright background. Same layout as
 * `bubbleShell` (edge at SHELL_EDGE).
 */
export function bubbleLight(size: number): Image {
  const data = new Uint8Array(size * size * 4);
  const half = size / 2;
  const radius = half * SHELL_EDGE;
  const aa = 1.25 / radius;
  const band = (rho: number, centre: number, halfWidth: number, soft: number): number =>
    smoothstep(centre - halfWidth - soft, centre - halfWidth + soft, rho) *
    (1 - smoothstep(centre + halfWidth - soft, centre + halfWidth + soft, rho));
  const arc = (
    rho: number,
    angle: number,
    centreAngle: number,
    halfAngle: number,
    centre: number,
    halfWidth: number,
  ): number => {
    const d = Math.abs(angleDelta(angle, centreAngle));
    if (d >= halfAngle) return 0;
    const along = 1 - d / halfAngle;
    // Taper toward the ends, like a window reflected on a sphere.
    const width = halfWidth * (0.3 + 0.7 * Math.sqrt(along));
    return smoothstep(0, 0.45, along) * band(rho, centre, width, 0.03);
  };

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const u = (x + 0.5 - half) / radius;
      const v = (y + 0.5 - half) / radius;
      const rho = Math.sqrt(u * u + v * v);
      const coverage = smoothstep(1 + aa, 1 - aa, rho);
      if (coverage <= 0) continue;
      const angle = Math.atan2(v, u);

      const window = 0.85 * arc(rho, angle, -2.3, 0.75, 0.79, 0.075);
      const glint = gauss(Math.hypot(u + 0.34, v + 0.43), 0, 0.045);
      const bounce = 0.32 * arc(rho, angle, 0.8, 0.5, 0.86, 0.035);
      const light = 1 - (1 - window) * (1 - glint) * (1 - bounce);

      const shadeAngle = smoothstep(1.5, 0.2, Math.abs(angleDelta(angle, Math.PI / 2)));
      const shade = 0.13 * shadeAngle * gauss(rho, 0.93, 0.05);

      // White light over a dark shade, premultiplied.
      const lightAlpha = 0.78 * light;
      const a = lightAlpha + shade * (1 - lightAlpha);
      const c = light + 0.02 * shade * (1 - lightAlpha);
      writePixel(data, y * size + x, c * coverage, c * coverage, c * coverage, a * coverage);
    }
  }
  return { width: size, height: size, data };
}

/**
 * A dark glass disc with a light rim, for a nine-slice capsule behind the score: it keeps
 * white digits legible over a white wall without hiding the picture.
 */
export function capsule(size: number): Image {
  const data = new Uint8Array(size * size * 4);
  const half = size / 2;
  const radius = half - 4;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const d = Math.hypot(x + 0.5 - half, y + 0.5 - half) - radius;
      const fill = 0.42 * smoothstep(0.8, -0.8, d);
      const rim = 0.5 * gauss(d, -1.8, 1.1);
      const shadow = d > 0 ? 0.16 * Math.exp(-d / 2) : 0;
      const a = rim * 0.6 + (fill + shadow) * (1 - rim * 0.6);
      writePixel(
        data,
        y * size + x,
        0.38 * rim + 0.02 * fill,
        0.4 * rim + 0.04 * fill,
        0.45 * rim + 0.08 * fill,
        a,
      );
    }
  }
  return { width: size, height: size, data };
}

// ---------------------------------------------------------------------------
// Pop effects: one atlas so every particle shares a texture source
// ---------------------------------------------------------------------------

export type EffectFrameName = 'ring' | 'flash' | 'droplet' | 'spark';

export interface EffectAtlas {
  image: Image;
  frames: Record<EffectFrameName, Frame>;
}

export function effectAtlas(): EffectAtlas {
  const width = 512;
  const height = 256;
  const data = new Uint8Array(width * height * 4);
  const frames: Record<EffectFrameName, Frame> = {
    ring: { x: 0, y: 0, width: 256, height: 256 },
    flash: { x: 256, y: 0, width: 128, height: 128 },
    droplet: { x: 384, y: 0, width: 64, height: 64 },
    spark: { x: 448, y: 0, width: 64, height: 64 },
  };

  const paint = (
    frame: Frame,
    shade: (u: number, v: number, rho: number) => [number, number],
  ): void => {
    const half = frame.width / 2;
    for (let y = 0; y < frame.height; y++) {
      for (let x = 0; x < frame.width; x++) {
        const u = (x + 0.5 - half) / half;
        const v = (y + 0.5 - half) / half;
        const rho = Math.sqrt(u * u + v * v);
        // Keep a transparent margin so neighbouring cells never bleed in under filtering.
        const fade = smoothstep(0.97, 0.9, rho);
        const [light, alpha] = shade(u, v, rho);
        const index = (frame.y + y) * width + frame.x + x;
        writePixel(data, index, light * fade, light * fade, light * fade, alpha * fade);
      }
    }
  };

  // A ring with a soft inner halo: the shock of the film snapping. Mostly opaque, so its
  // tint shows on a white wall as well as glowing in a dark room.
  paint(frames.ring, (_u, _v, rho) => {
    const light = Math.min(1, gauss(rho, 0.84, 0.045) + 0.3 * gauss(rho, 0.76, 0.1));
    // A thin dark edge outside the bright band, like the bubble's own rim, for bright walls.
    const shade = 0.4 * gauss(rho, 0.9, 0.018);
    return [light, Math.min(1, 0.7 * light + shade)];
  });
  // A soft glow that flashes over the bubble for a frame or two; additive, so subtle on white.
  paint(frames.flash, (_u, _v, rho) => {
    const light = Math.exp(-rho * rho * 3.2);
    return [light, 0.12 * light];
  });
  // A droplet: a solid coloured bead with an offset highlight, visible on any background.
  paint(frames.droplet, (u, v, rho) => {
    const body = smoothstep(0.86, 0.68, rho);
    const core = gauss(Math.hypot(u + 0.25, v + 0.25), 0, 0.22);
    return [Math.min(1, body * (0.72 + 0.4 * core)), 0.88 * body];
  });
  // A four-point glint.
  paint(frames.spark, (u, v, rho) => {
    const ax = Math.abs(u);
    const ay = Math.abs(v);
    const star =
      Math.exp(-ax * 9) * Math.exp(-ay * ay * 90) + Math.exp(-ay * 9) * Math.exp(-ax * ax * 90);
    const light = Math.min(1, star + 0.8 * Math.exp(-rho * rho * 30));
    return [light, 0.45 * light];
  });

  return { image: { width, height, data }, frames };
}
