import { ImageSource, Sprite, Texture } from 'pixi.js';
import type { ViewTransform } from '../core/view';
import type { DisplaySource } from '../vision/types';

/**
 * A <canvas> source gives no signal when it is redrawn, so it is re-uploaded at this rate.
 * The synthetic source draws at 30 fps.
 */
const CANVAS_UPLOAD_INTERVAL_MS = 1000 / 30 - 2;

/**
 * Stretch `sprite` over the full source frame as placed by the view, mirrored with it.
 * Anything covering the source frame (video, mask) goes through here so they line up.
 */
export function placeOnVideo(sprite: Sprite, view: ViewTransform): void {
  const rect = view.videoRect;
  const { width, height } = sprite.texture;
  sprite.scale.set(
    ((view.mirrored ? -1 : 1) * rect.width) / Math.max(1, width),
    rect.height / Math.max(1, height),
  );
  sprite.position.set(view.mirrored ? rect.x + rect.width : rect.x, rect.y);
}

/**
 * The camera picture. A <video> is uploaded only when it has presented a new frame; a
 * paired VideoFrame (debug) replaces the live picture until it is cleared.
 */
export class VideoLayer {
  readonly sprite = new Sprite();

  private view: ViewTransform | null = null;
  private element: DisplaySource | null = null;
  private source: ImageSource | null = null;
  private texture: Texture | null = null;
  private running = false;
  private frameCallback = 0;
  private newFrame = false;
  private lastCanvasUploadMs = Number.NEGATIVE_INFINITY;

  private paired: VideoFrame | null = null;
  private pairedSource: ImageSource | null = null;
  private pairedTexture: Texture | null = null;

  /** What the sprite was last laid out for, to re-place it only when something changed. */
  private placedTexture: Texture | null = null;
  private placedWidth = 0;
  private placedHeight = 0;
  private placedView: ViewTransform | null = null;

  constructor() {
    this.sprite.visible = false;
  }

  setView(view: ViewTransform): void {
    this.view = view;
  }

  setSource(element: DisplaySource | null): void {
    if (element === this.element) return;
    this.unwatch();
    this.releaseLive();
    this.element = element;
    this.newFrame = true;
    this.lastCanvasUploadMs = Number.NEGATIVE_INFINITY;
    if (this.running) this.watch();
  }

  /** Takes ownership of `frame`; the previous one is closed. */
  setPairedFrame(frame: VideoFrame | null): void {
    if (frame === this.paired) return;
    this.paired?.close();
    this.paired = frame;
    if (!frame) {
      // Back to live: show the current picture, not whatever was uploaded before pairing.
      this.newFrame = true;
      return;
    }
    if (!this.pairedSource) {
      this.pairedSource = new ImageSource({
        resource: frame,
        alphaMode: 'premultiplied-alpha',
        autoGarbageCollect: false,
        label: 'paired-frame',
      });
      this.pairedTexture = new Texture({ source: this.pairedSource });
    } else {
      this.pairedSource.resource = frame;
      this.pairedSource.update();
    }
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.newFrame = true;
    this.watch();
  }

  stop(): void {
    this.running = false;
    this.unwatch();
  }

  /** Upload a new frame if there is one and keep the sprite placed. Call once per render. */
  sync(nowMs: number): void {
    let shown: Texture | null = null;
    if (this.paired && this.pairedTexture) {
      shown = this.pairedTexture;
    } else {
      this.ensureLiveTexture();
      const source = this.source;
      if (source) {
        const due =
          this.element instanceof HTMLVideoElement
            ? this.newFrame
            : nowMs - this.lastCanvasUploadMs >= CANVAS_UPLOAD_INTERVAL_MS;
        if (due) {
          this.newFrame = false;
          this.lastCanvasUploadMs = nowMs;
          // Also picks up a change of frame size: the source resizes to the element.
          source.update();
        }
      }
      shown = this.texture;
    }
    this.place(shown);
  }

  dispose(): void {
    this.stop();
    this.releaseLive();
    this.element = null;
    this.paired?.close();
    this.paired = null;
    this.pairedTexture?.destroy();
    this.pairedSource?.destroy();
    this.pairedTexture = null;
    this.pairedSource = null;
    this.sprite.destroy();
  }

  private place(texture: Texture | null): void {
    const { sprite, view } = this;
    sprite.visible = Boolean(texture && view);
    if (!texture || !view) return;
    if (
      texture === this.placedTexture &&
      texture.width === this.placedWidth &&
      texture.height === this.placedHeight &&
      view === this.placedView
    ) {
      return;
    }
    sprite.texture = texture;
    placeOnVideo(sprite, view);
    this.placedTexture = texture;
    this.placedWidth = texture.width;
    this.placedHeight = texture.height;
    this.placedView = view;
  }

  /** The element may have no size until its first frame; the texture waits for one. */
  private ensureLiveTexture(): void {
    const element = this.element;
    if (this.source || !element) return;
    const width = element instanceof HTMLVideoElement ? element.videoWidth : element.width;
    const height = element instanceof HTMLVideoElement ? element.videoHeight : element.height;
    if (width === 0 || height === 0) return;
    this.source = new ImageSource({
      resource: element,
      // Camera frames are opaque: skip the premultiply pass on every upload.
      alphaMode: 'premultiplied-alpha',
      autoGarbageCollect: false,
      label: 'video',
    });
    this.texture = new Texture({ source: this.source });
    this.newFrame = true;
  }

  private releaseLive(): void {
    this.texture?.destroy();
    this.source?.destroy();
    this.texture = null;
    this.source = null;
  }

  private watch(): void {
    const element = this.element;
    if (element instanceof HTMLVideoElement) {
      this.frameCallback = element.requestVideoFrameCallback(this.onVideoFrame);
    }
  }

  private unwatch(): void {
    const element = this.element;
    if (element instanceof HTMLVideoElement && this.frameCallback) {
      element.cancelVideoFrameCallback(this.frameCallback);
    }
    this.frameCallback = 0;
  }

  private readonly onVideoFrame = (): void => {
    const element = this.element;
    if (!this.running || !(element instanceof HTMLVideoElement)) return;
    this.newFrame = true;
    this.frameCallback = element.requestVideoFrameCallback(this.onVideoFrame);
  };
}
