/**
 * Bubble kinematics: a drift along a fixed heading, a sinusoidal meander across it, and a
 * soft push that steers crowding bubbles apart. Drift and meander are integrated in closed
 * form, so they are exact at any step; the push is a smoothed exponential approach,
 * accurate for the short substeps the world takes.
 *
 * Every bubble reaches an exit in bounded time: the heading never changes and the push may
 * not cut progress along it below MIN_PROGRESS of the drift speed, while the meander only
 * acts across it.
 */
import type { Tunables } from '../config/tunables';
import type { SimBubble } from './bubble';

/** Drift speed floor in world units/s, so every bubble keeps heading for an exit. */
const MIN_DRIFT_SPEED = 10;
const MAX_SPEED_JITTER = 0.9;
/** The push may cut a bubble's progress along its heading to no less than this share. */
const MIN_PROGRESS = 0.5;
/**
 * Rate (1/s, per unit of `separation`) at which a crowded pair eases apart. Kept gentle so
 * bubbles drift past each other instead of ricocheting; the long anticipation below gives
 * them the time to do it.
 */
const SEPARATION_RATE = 5;
/** Firmer rate for discs that actually overlap, so a crowded screen does not interpenetrate. */
const CONTACT_RATE = 20;
/**
 * Bubbles start easing apart this fraction of their radii before they touch. The spawner
 * keeps new bubbles outside this zone.
 */
export const SEPARATION_GAP = 0.25;
/**
 * The zone also widens by how far the two drifts close on each other in this time, so
 * bubbles on colliding paths (head-on, or a side entry crossing a falling one) start to
 * part well before they meet.
 */
const ANTICIPATION_S = 1.5;
/** Closing speed (world units/s) at which a pair steers fully across its relative drift. */
const STEER_CLOSING_SPEED = 30;
/** Sine of the miss angle at which steering is at full strength (about 15°). */
const STEER_FULL_OFFSET = 0.25;
/** Push speed cap in multiples of `driftSpeed`, so a deep overlap eases apart, not jumps. */
const MAX_PUSH_SPEED = 1.5;
/**
 * The push velocity follows its target with this time constant, so the edges of the push
 * zone (where the target starts or stops rising) do not show as kinks in the path.
 */
const PUSH_SMOOTH_S = 0.08;
/** Presence of a bubble wholly off screen, relative to 1 for one in full view. */
const YIELD_FLOOR = 0.05;
const MIN_MEANDER_PERIOD_S = 0.1;
const TAU = 2 * Math.PI;

/** Current drift speed of one bubble, in world units/s (0 for a pinned one). */
export function driftSpeedOf(bubble: SimBubble, tunables: Tunables): number {
  if (bubble.pinned) return 0;
  const jitter = Math.min(MAX_SPEED_JITTER, Math.max(0, tunables.speedJitter));
  return Math.max(MIN_DRIFT_SPEED, tunables.driftSpeed * (1 + jitter * bubble.speedOffset));
}

/** Advance every bubble by `dtS` seconds; the world keeps this short (see world.ts). */
export function advance(bubbles: readonly SimBubble[], tunables: Tunables, dtS: number): void {
  gatherPush(bubbles, tunables, dtS);
  const amplitude = Math.max(0, tunables.meanderAmplitude);
  const period = Math.max(MIN_MEANDER_PERIOD_S, tunables.meanderPeriodS);
  const maxPushSpeed = MAX_PUSH_SPEED * Math.max(MIN_DRIFT_SPEED, tunables.driftSpeed);
  const follow = 1 - Math.exp(-dtS / PUSH_SMOOTH_S);

  for (let i = 0; i < bubbles.length; i++) {
    const bubble = bubbles[i] as SimBubble;
    bubble.ageS += dtS;
    if (bubble.pinned) continue;
    const { dirX, dirY } = bubble;
    const along = driftSpeedOf(bubble, tunables) * dtS;

    // Lateral velocity amplitude·sin(phase), integrated exactly over the step. Advancing a
    // stored phase (rather than using age) keeps the path smooth when the period is tuned live.
    const omega = TAU / (period * bubble.meanderPeriodScale);
    const phase = bubble.meanderPhase + omega * dtS;
    const lateral = (amplitude / omega) * (Math.cos(bubble.meanderPhase) - Math.cos(phase));
    bubble.meanderPhase = phase % TAU;

    // The push asked for this step, as a capped velocity that the actual push follows.
    let targetX = bubble.pushX / dtS;
    let targetY = bubble.pushY / dtS;
    const target = Math.hypot(targetX, targetY);
    if (target > maxPushSpeed) {
      targetX *= maxPushSpeed / target;
      targetY *= maxPushSpeed / target;
    }
    bubble.avoidX += (targetX - bubble.avoidX) * follow;
    bubble.avoidY += (targetY - bubble.avoidY) * follow;
    let pushX = bubble.avoidX * dtS;
    let pushY = bubble.avoidY * dtS;
    // The push may slow a bubble but never stall it or send it back, so bubbles meeting
    // head-on cannot hold each other on screen forever. What it may not take from forward
    // progress becomes a sidestep instead, so such bubbles slide around each other rather
    // than through. The side is chosen when the sidestep starts and kept until it ends:
    // re-deciding every step flips it back and forth when the sideways push is near zero.
    const shortfall = pushX * dirX + pushY * dirY + (1 - MIN_PROGRESS) * along;
    if (shortfall < 0) {
      // With no sideways push to follow, step right (y is down), which parts a head-on pair.
      if (bubble.sidestep === 0) bubble.sidestep = dirX * pushY - dirY * pushX >= 0 ? 1 : -1;
      const side = bubble.sidestep;
      pushX -= shortfall * (dirX - side * dirY);
      pushY -= shortfall * (dirY + side * dirX);
    } else {
      bubble.sidestep = 0;
    }

    const dx = dirX * along - dirY * lateral + pushX;
    const dy = dirY * along + dirX * lateral + pushY;
    bubble.x += dx;
    bubble.y += dy;
    bubble.vx = dx / dtS;
    bubble.vy = dy / dtS;
  }
}

/**
 * True while `bubble` is close enough to push a bubble that is on screen. A bubble that has
 * left waits to expire until this is false, since removing it would end that push in one
 * step and jolt the neighbour.
 */
export function pushesVisible(
  bubble: SimBubble,
  bubbles: readonly SimBubble[],
  tunables: Tunables,
): boolean {
  const speed = driftSpeedOf(bubble, tunables);
  for (let i = 0; i < bubbles.length; i++) {
    const other = bubbles[i] as SimBubble;
    if (other === bubble || other.visible <= 0) continue;
    const dx = other.x - bubble.x;
    const dy = other.y - bubble.y;
    const distance = Math.hypot(dx, dy);
    if (distance < 1e-6) return true;
    const otherSpeed = driftSpeedOf(other, tunables);
    const closing =
      ((bubble.dirX * speed - other.dirX * otherSpeed) * dx +
        (bubble.dirY * speed - other.dirY * otherSpeed) * dy) /
      distance;
    if (distance < reachOf(bubble, other, closing)) return true;
  }
  return false;
}

/** Centre distance below which two bubbles push apart, given how fast their drifts close. */
function reachOf(a: SimBubble, b: SimBubble, closing: number): number {
  return (a.r + b.r) * (1 + SEPARATION_GAP) + ANTICIPATION_S * Math.max(0, closing);
}

/** Weight of a bubble's claim to stay put, from its share on screen. */
function presence(bubble: SimBubble): number {
  return YIELD_FLOOR + bubble.visible;
}

/**
 * Sum, per bubble, the displacement that eases crowded pairs apart over this step. Pairs are
 * resolved together from the same positions (no ordering bias), and each pair's gap closes
 * by the fraction 1 − e^(−k·dt), which never overshoots, so the push cannot jitter.
 *
 * While a pair is closing, the push acts across their relative drift rather than along the
 * line between them, so they slide past each other. A push along that line would shove
 * one bubble in the direction the other is travelling: a bubble falling just ahead of a
 * side entry would then carry it down to the floor, the two stuck together.
 */
function gatherPush(bubbles: readonly SimBubble[], tunables: Tunables, dtS: number): void {
  for (let i = 0; i < bubbles.length; i++) {
    const bubble = bubbles[i] as SimBubble;
    bubble.pushX = 0;
    bubble.pushY = 0;
  }
  const separation = tunables.separation;
  if (!(separation > 0)) return;
  const ease = 1 - Math.exp(-SEPARATION_RATE * separation * dtS);
  const easeContact = 1 - Math.exp(-CONTACT_RATE * separation * dtS);
  // Cheap upper bound on any pair's reach, to skip distant pairs before the exact test.
  const maxSpeed =
    Math.max(MIN_DRIFT_SPEED, tunables.driftSpeed) *
    (1 + Math.min(MAX_SPEED_JITTER, Math.max(0, tunables.speedJitter)));
  const maxWiden = ANTICIPATION_S * 2 * maxSpeed;

  for (let i = 0; i < bubbles.length; i++) {
    const a = bubbles[i] as SimBubble;
    const speedA = driftSpeedOf(a, tunables);
    for (let j = i + 1; j < bubbles.length; j++) {
      const b = bubbles[j] as SimBubble;
      if (a.pinned && b.pinned) continue;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const bound = (a.r + b.r) * (1 + SEPARATION_GAP) + maxWiden;
      const distanceSq = dx * dx + dy * dy;
      if (distanceSq >= bound * bound) continue;
      const distance = Math.sqrt(distanceSq);
      // Coincident centres have no direction; split them sideways rather than divide by 0.
      const nx = distance > 1e-6 ? dx / distance : 1;
      const ny = distance > 1e-6 ? dy / distance : 0;
      // Drift of b relative to a, and how fast it closes the gap between them.
      const speedB = driftSpeedOf(b, tunables);
      const wx = b.dirX * speedB - a.dirX * speedA;
      const wy = b.dirY * speedB - a.dirY * speedA;
      const closing = -(wx * nx + wy * ny);
      const reach = reachOf(a, b, closing);
      if (distance >= reach) continue;
      const shift = (reach - distance) * ease + Math.max(0, a.r + b.r - distance) * easeContact;

      let px = nx;
      let py = ny;
      const w = Math.hypot(wx, wy);
      if (closing > 0 && w > 1e-6) {
        // Unit offset of b from a across the relative drift; its length is the sine of the
        // angle between their line and the drift.
        const along = (nx * wx + ny * wy) / w;
        const lx = nx - (along * wx) / w;
        const ly = ny - (along * wy) / w;
        const lateral = Math.hypot(lx, ly);
        if (lateral > 1e-9) {
          // Ramp in with the closing speed and with the offset, so the direction stays
          // continuous as either passes zero. A pair dead on course keeps the push along
          // their line, which the sidestep in `advance` turns aside.
          const blend =
            Math.min(1, closing / STEER_CLOSING_SPEED) * Math.min(1, lateral / STEER_FULL_OFFSET);
          px = nx + blend * (lx / lateral - nx);
          py = ny + blend * (ly / lateral - ny);
          const length = Math.hypot(px, py);
          px /= length;
          py /= length;
        }
      }
      // Each moves in proportion to the other's presence on screen. Bubbles in full view
      // share the push, while one still entering or nearly gone gives way, so neither a
      // spawn nor an expiry jolts a visible bubble, and the shares change smoothly as
      // bubbles cross the edge. Pinned bubbles never move.
      const shareA = a.pinned ? 0 : b.pinned ? 1 : presence(b) / (presence(a) + presence(b));
      const shareB = 1 - shareA;
      a.pushX -= px * shift * shareA;
      a.pushY -= py * shift * shareA;
      b.pushX += px * shift * shareB;
      b.pushY += py * shift * shareB;
    }
  }
}
