/**
 * Short synthesized signals for the round: someone joined, the countdown, go, the last
 * seconds, time's up, the winner. A few plain notes each, in one key so they sit together.
 * Works on any BaseAudioContext.
 */

export type Cue =
  /** A player took a slot. */
  | 'join'
  /** A second of the countdown passing. */
  | 'tick'
  /** One of the last three seconds of the countdown. */
  | 'ready'
  | 'go'
  /** One of the last seconds of the round. */
  | 'hurry'
  /** The round ended without a winner. */
  | 'end'
  | 'win';

interface Note {
  hz: number;
  /** Seconds after the cue starts. */
  at: number;
  lengthS: number;
  level: number;
  type: OscillatorType;
}

const note = (
  hz: number,
  at: number,
  lengthS: number,
  level = 0.3,
  type: OscillatorType = 'triangle',
): Note => ({
  hz,
  at,
  lengthS,
  level,
  type,
});

// C major: C5 523, E5 659, G5 784, C6 1047, E6 1319, G6 1568.
const CUES: Record<Cue, readonly Note[]> = {
  join: [note(784, 0, 0.09), note(1047, 0.08, 0.16)],
  tick: [note(784, 0, 0.06, 0.16, 'sine')],
  ready: [note(784, 0, 0.16, 0.32)],
  go: [note(1047, 0, 0.5, 0.3), note(1319, 0, 0.5, 0.2), note(1568, 0, 0.5, 0.2)],
  hurry: [note(1319, 0, 0.07, 0.24)],
  end: [note(784, 0, 0.16), note(659, 0.15, 0.16), note(523, 0.3, 0.4)],
  win: [
    note(523, 0, 0.13),
    note(659, 0.12, 0.13),
    note(784, 0.24, 0.13),
    note(1047, 0.36, 0.6, 0.32),
    note(1319, 0.36, 0.6, 0.2),
    note(1568, 0.48, 0.5, 0.18),
  ],
};

/** Attack short enough to sound struck, long enough not to click. */
const ATTACK_S = 0.008;

/** Schedule `cue` at `when` into `destination`. Returns the time it ends. */
export function playCue(
  context: BaseAudioContext,
  destination: AudioNode,
  cue: Cue,
  when: number,
): number {
  let end = when;
  for (const { hz, at, lengthS, level, type } of CUES[cue]) {
    const start = when + at;
    const stop = start + lengthS;
    const oscillator = context.createOscillator();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(hz, start);
    const gain = context.createGain();
    gain.gain.setValueAtTime(0, start);
    gain.gain.linearRampToValueAtTime(level, start + ATTACK_S);
    gain.gain.exponentialRampToValueAtTime(0.001, stop);
    oscillator.connect(gain).connect(destination);
    oscillator.start(start);
    oscillator.stop(stop + 0.02);
    oscillator.onended = () => {
      oscillator.disconnect();
      gain.disconnect();
    };
    if (stop > end) end = stop;
  }
  return end;
}
