import type { Cue, Sfx } from '../audio';
import type { Params } from '../config/params';
import type { Tunables } from '../config/tunables';
import type { Unsubscribe } from '../core/events';
import type { PersonMask } from '../core/mask';
import { createRng } from '../core/rng';
import { computeView, type ViewTransform } from '../core/view';
import type { DebugUi } from '../debug';
import {
  BlobFinder,
  createRound,
  createWorld,
  type Round,
  type RoundEvent,
  type World,
} from '../game';
import type { Stage } from '../render';
import { DEFAULT_LAYOUT, type RegionLayout, type VisionPipeline } from '../vision';

/** Side of the segmentation model's square input. */
export const MODEL_INPUT_SIZE = 256;

export function layoutFor(tunables: Tunables): RegionLayout {
  if (tunables.stretchInput || DEFAULT_LAYOUT.mode !== 'tiles') return { mode: 'stretch' };
  return { ...DEFAULT_LAYOUT, tileHeight: tunables.tileHeight };
}

export interface SessionDeps {
  params: Params;
  tunables: Tunables;
  stage: Stage;
  sfx: Sfx;
  debug: DebugUi;
  /** Already started. The session owns it from here and disposes it. */
  vision: VisionPipeline;
}

/** The last seconds of the countdown and of the round each get a more urgent sound. */
const READY_SECONDS = 3;
const HURRY_SECONDS = 5;

/** The sound for a round event, if it has one. */
function cueFor(event: RoundEvent, round: Round): Cue | null {
  switch (event.type) {
    case 'join':
      return 'join';
    case 'second':
      if (event.phase === 'countdown') return event.seconds <= READY_SECONDS ? 'ready' : 'tick';
      return event.seconds <= HURRY_SECONDS ? 'hurry' : null;
    case 'phase':
      if (event.phase === 'playing') return 'go';
      if (event.phase === 'results') return round.winners.length > 0 ? 'win' : 'end';
      return null;
    default:
      return null;
  }
}

/**
 * One run of the game, from a successful start until the camera is lost. Owns the world,
 * the round and the per-frame order of operations:
 * newest mask and people → pops → simulation step → who scored → sounds → visuals.
 */
export class PlaySession {
  readonly vision: VisionPipeline;
  readonly world: World;
  readonly round: Round;
  lastMask: PersonMask | null = null;
  view: ViewTransform;

  private readonly tunables: Tunables;
  private readonly stage: Stage;
  private readonly sfx: Sfx;
  private readonly debug: DebugUi;
  private readonly people = new BlobFinder();
  private readonly unsubscribe: Unsubscribe[] = [];
  // The mask size depends on the layout and the camera's aspect ratio, so it is only known
  // once a mask arrives. Until then any size works because nothing samples a mask.
  private maskWidth = MODEL_INPUT_SIZE;
  private maskHeight = MODEL_INPUT_SIZE;
  private pairing = false;
  private overlayShown = false;
  private paused = false;
  private disposed = false;

  constructor(deps: SessionDeps) {
    this.vision = deps.vision;
    this.tunables = deps.tunables;
    this.stage = deps.stage;
    this.sfx = deps.sfx;
    this.debug = deps.debug;
    this.view = this.computeView();
    this.world = createWorld({
      tunables: deps.tunables,
      rng: createRng(deps.params.seed ?? Date.now() & 0xffffffff),
      view: this.view,
    });
    this.round = createRound({ tunables: deps.tunables });
  }

  start(): void {
    const { stage, vision } = this;
    this.unsubscribe.push(
      vision.onSourceChange(() => {
        stage.setVideoSource(vision.display);
        this.applyView();
      }),
    );
    stage.setVideoSource(vision.display);
    stage.setView(this.view);
    this.applySettings();
    stage.setTick(this.tick);
    stage.start();
  }

  /** Tab hidden: stop everything that costs CPU, GPU or attention. */
  pause(): void {
    if (this.paused || this.disposed) return;
    this.paused = true;
    this.vision.pause();
    this.stage.stop();
    this.sfx.suspend();
  }

  resume(): void {
    if (!this.paused || this.disposed) return;
    this.paused = false;
    this.vision.resume();
    this.stage.start();
    this.sfx.resume();
  }

  /** Re-read the tunables that are applied on change rather than every frame. */
  applySettings(): void {
    const { tunables, vision, stage } = this;
    this.sfx.applyVolume();
    vision.setLayout(layoutFor(tunables));
    if (tunables.pairVideoToMask !== this.pairing) {
      this.pairing = tunables.pairVideoToMask;
      vision.setPairing(this.pairing);
      if (!this.pairing) stage.setPairedFrame(null);
    }
    if (!tunables.showMask && this.overlayShown) {
      this.overlayShown = false;
      stage.setMaskOverlay(null);
    }
    this.applyView();
  }

  /** Recompute placement after the screen, source, mask size or view tunables change. */
  applyView(): void {
    if (this.disposed) return;
    this.view = this.computeView();
    this.stage.setView(this.view);
    this.world.setView(this.view);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const off of this.unsubscribe) off();
    // A session can end while the tab is hidden (the camera drops on wake). Leave the
    // sound running for the next session rather than suspended with nobody to resume it.
    if (this.paused) this.sfx.resume();
    const { stage } = this;
    stage.setTick(null);
    // Leave the stage as it was before this session: no bubbles, bursts or score.
    stage.clear();
    stage.setPairedFrame(null);
    stage.setMaskOverlay(null);
    stage.setVideoSource(null);
    stage.stop();
    this.vision.dispose();
  }

  private computeView(): ViewTransform {
    const source = this.vision.sourceInfo;
    return computeView({
      screenWidth: this.stage.screenWidth,
      screenHeight: this.stage.screenHeight,
      sourceWidth: source?.width ?? 16,
      sourceHeight: source?.height ?? 9,
      maskWidth: this.maskWidth,
      maskHeight: this.maskHeight,
      mirrored: this.tunables.mirror,
      safeMargin: this.tunables.safeMargin,
    });
  }

  private readonly tick = (dtMs: number, nowMs: number): void => {
    const { vision, world, round, stage, tunables } = this;

    const mask = vision.takeMask();
    if (mask) {
      this.lastMask = mask;
      if (mask.width !== this.maskWidth || mask.height !== this.maskHeight) {
        this.maskWidth = mask.width;
        this.maskHeight = mask.height;
        this.applyView();
      }
      // Who is where, from the same mask that is about to pop bubbles.
      round.observe(this.people.find(mask, this.view, tunables.maskThreshold), nowMs);
      world.applyMask(mask, nowMs);
    }

    // Debug views. With pairing on, the overlay must match the frame being shown, not the
    // newest mask.
    if (this.pairing) {
      const pair = vision.takePair();
      if (pair) {
        stage.setPairedFrame(pair.image);
        if (tunables.showMask) this.showOverlay(pair.mask);
      }
    } else if (mask && tunables.showMask) {
      this.showOverlay(mask);
    }

    world.step(dtMs / 1000);
    const events = world.drainEvents();
    for (const event of events) {
      if (event.type === 'pop') {
        this.sfx.pop(event.r, (event.x / this.view.worldWidth) * 2 - 1);
        const { x, y, r } = event;
        round.creditPop(x, y, r, this.people.personAt(x, y, r));
      }
    }
    round.step(dtMs / 1000);
    const roundEvents = round.drainEvents();
    for (const event of roundEvents) {
      const cue = cueFor(event, round);
      if (cue) this.sfx.cue(cue);
    }
    stage.update(world, events, dtMs);
    stage.updateRound(round, roundEvents, dtMs);
    this.debug.update(nowMs);
  };

  private showOverlay(mask: PersonMask): void {
    this.overlayShown = true;
    // The second argument tints person texels the pop rule is ignoring as static shapes.
    this.stage.setMaskOverlay(mask, this.world.ignoredTexels);
  }
}
