/**
 * Full-screen message over the game for problems that stop play (camera unplugged, display
 * reset), with one action. The action button takes focus so Enter or Space answers it.
 */
import type { ErrorOverlay } from './types';

const FADE_IN_MS = 250;

let instances = 0;

export function createErrorOverlay(root: HTMLElement): ErrorOverlay {
  const id = `error-overlay-${++instances}`;
  const element = document.createElement('div');
  element.className = 'error-overlay';
  element.hidden = true;
  element.setAttribute('role', 'alertdialog');
  element.setAttribute('aria-modal', 'true');
  element.setAttribute('aria-labelledby', `${id}-title`);
  element.setAttribute('aria-describedby', `${id}-detail`);
  element.innerHTML = `
    <div class="error-overlay-card">
      <svg class="error-overlay-icon" viewBox="0 0 48 48" aria-hidden="true">
        <circle cx="24" cy="24" r="21" fill="none" stroke="currentColor" stroke-width="3.5" />
        <path d="M24 13.5v13" stroke="currentColor" stroke-width="4.5" stroke-linecap="round" />
        <circle cx="24" cy="34" r="2.9" fill="currentColor" />
      </svg>
      <h2 class="error-overlay-title" id="${id}-title"></h2>
      <p class="error-overlay-detail" id="${id}-detail"></p>
      <button class="error-overlay-action" type="button"></button>
      <p class="error-overlay-technical" hidden></p>
    </div>
  `;
  root.appendChild(element);

  const pick = <T extends Element>(selector: string): T => {
    const found = element.querySelector<T>(selector);
    if (!found) throw new Error(`error overlay markup is missing ${selector}`);
    return found;
  };
  const title = pick<HTMLElement>('.error-overlay-title');
  const detail = pick<HTMLElement>('.error-overlay-detail');
  const button = pick<HTMLButtonElement>('.error-overlay-action');
  const technical = pick<HTMLElement>('.error-overlay-technical');

  let action: (() => void) | null = null;
  let fade: Animation | null = null;

  button.addEventListener('click', () => action?.());

  // Keep focus on the button when the backdrop is clicked, so Enter still works.
  element.addEventListener('mousedown', (event) => {
    const target = event.target as Element;
    if (!target.closest('button, .error-overlay-technical')) event.preventDefault();
  });

  // Enter or Space with nothing focused (focus lost to the page) answers the overlay too.
  const onKeyDown = (event: KeyboardEvent): void => {
    if (element.hidden || event.repeat || event.defaultPrevented) return;
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (event.key !== 'Enter' && event.key !== ' ') return;
    if (event.target instanceof Element && event.target !== document.body) return;
    event.preventDefault();
    action?.();
  };
  window.addEventListener('keydown', onKeyDown);

  return {
    get visible() {
      return !element.hidden;
    },
    show(content) {
      title.textContent = content.title;
      detail.textContent = content.detail;
      technical.textContent = content.technical ?? '';
      technical.hidden = !content.technical;
      button.textContent = content.actionLabel;
      action = content.onAction;
      if (element.hidden) {
        element.hidden = false;
        fade = element.animate([{ opacity: 0 }, { opacity: 1 }], {
          duration: FADE_IN_MS,
          easing: 'ease-out',
        });
      }
      button.focus({ preventScroll: true });
    },
    hide() {
      fade?.cancel();
      fade = null;
      element.hidden = true;
      action = null;
    },
    dispose() {
      fade?.cancel();
      fade = null;
      action = null;
      window.removeEventListener('keydown', onKeyDown);
      element.remove();
    },
  };
}
