import {
  type Backend,
  type BackendOptions,
  INIT_TIMEOUT_MS,
  LATE_TIMER_MS,
  SEGMENT_TIMEOUT_MS,
  SegmentFailure,
} from './backend';
import type { RegionLayout, SegmenterConfig, WorkerRequest, WorkerResponse } from './protocol';
import { type SegmenterInfo, type SegmentResult, type StartProgress, VisionError } from './types';

interface Pending {
  resolve(result: SegmentResult): void;
  reject(error: VisionError): void;
  timer: ReturnType<typeof setTimeout>;
  /** `performance.now()` at which the reply is overdue. */
  deadline: number;
}

type SegmentRequest = Extract<WorkerRequest, { type: 'segment' }>;

/**
 * One segmenter worker for its whole life: it is never restarted in place. When it times
 * out or crashes it reports that through `monitor` and refuses further work; the owner
 * (`ResilientSegmenter`) disposes it and creates a fresh one.
 */
export class WorkerSegmenter implements Backend {
  info: SegmenterInfo | null = null;

  private worker: Worker | null = null;
  private nextId = 1;
  private readonly pending = new Map<number, Pending>();
  private spare: ArrayBuffer | null = null;
  private broken = false;
  private started = false;
  private disposed = false;
  private cancelInit: ((error: VisionError) => void) | null = null;
  // Reused for every frame: postMessage copies the message synchronously.
  private readonly request: SegmentRequest = {
    type: 'segment',
    id: 0,
    frame: null as unknown as VideoFrame,
    recycle: null,
  };
  private readonly transferFrame: Transferable[] = [];
  private readonly transferBoth: Transferable[] = [];

  constructor(private readonly options: BackendOptions) {}

  async init(onProgress?: (progress: StartProgress) => void): Promise<SegmenterInfo> {
    if (this.started || this.disposed) {
      throw new VisionError('segmenter-init', 'A segmenter worker can only be started once.');
    }
    this.started = true;
    const { options } = this;
    // Fetched here, before the init timeout starts, so a slow connection cannot make a
    // healthy worker look hung. Usually already in hand: the pipeline prefetches it.
    const wasm = options.engine === 'mediapipe' ? await options.loadWasm('module') : null;
    if (this.disposed) throw new VisionError('segmenter-init', 'The segmenter was stopped.');
    onProgress?.({ stage: 'wasm', fraction: null });

    const config: SegmenterConfig = {
      engine: options.engine,
      delegate: options.delegate,
      wasmLoaderUrl: wasm?.loaderUrl ?? '',
      wasmBinary: wasm?.binary ?? null,
      modelBuffer: options.modelBuffer,
      inputSize: options.inputSize,
      layout: options.layout,
      fault: options.fault,
    };

    let worker: Worker;
    try {
      worker = new Worker(new URL('./segmenter.worker.ts', import.meta.url), {
        type: 'module',
        name: 'segmenter',
      });
    } catch (cause) {
      throw new VisionError('segmenter-init', 'This browser cannot start the segmenter worker.', {
        cause,
      });
    }
    this.worker = worker;

    let info: SegmenterInfo;
    try {
      info = await new Promise<SegmenterInfo>((resolve, reject) => {
        const finish = (): void => {
          clearTimeout(timer);
          this.cancelInit = null;
        };
        const fail = (message: string): void => {
          finish();
          reject(new VisionError('segmenter-init', message));
        };
        const timer = setTimeout(
          () => fail('The segmenter took too long to start.'),
          INIT_TIMEOUT_MS,
        );
        this.cancelInit = (error) => {
          finish();
          reject(error);
        };
        worker.onerror = (event) => {
          // Handled here; without this the browser also reports it as an uncaught error.
          event.preventDefault();
          fail(event.message || 'The segmenter worker failed to load.');
        };
        worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
          const message = event.data;
          if (message.type === 'warmup') {
            onProgress?.({ stage: 'warmup', fraction: null });
          } else if (message.type === 'ready') {
            finish();
            resolve({ backend: 'worker', ...message.info });
          } else if (message.type === 'init-error') {
            fail(message.message);
          }
        };
        worker.postMessage({ type: 'init', config } satisfies WorkerRequest);
      });
    } catch (error) {
      this.terminate();
      throw error;
    }

    worker.onmessage = (event: MessageEvent<WorkerResponse>) => this.onMessage(event.data);
    worker.onerror = (event) => {
      event.preventDefault();
      this.crash(event.message || 'The segmenter worker crashed.');
    };
    this.info = info;
    return info;
  }

  setLayout(layout: RegionLayout): void {
    // A recycled buffer would have the wrong size for the new layout.
    this.spare = null;
    // The worker applies it after any frame already queued, or once its core exists.
    this.worker?.postMessage({ type: 'layout', layout } satisfies WorkerRequest);
  }

  segment(frame: VideoFrame): Promise<SegmentResult> {
    const { worker } = this;
    if (!worker || !this.info || this.broken) {
      frame.close();
      return Promise.reject(new SegmentFailure('The segmenter worker is not running.', true));
    }
    const id = this.nextId++;
    return new Promise<SegmentResult>((resolve, reject) => {
      const timer = setTimeout(this.onTimeout, SEGMENT_TIMEOUT_MS, id);
      this.pending.set(id, {
        resolve,
        reject,
        timer,
        deadline: performance.now() + SEGMENT_TIMEOUT_MS,
      });
      const recycle = this.spare;
      this.spare = null;
      // After the transfer these only point at a closed frame and a detached buffer.
      const { request } = this;
      request.id = id;
      request.frame = frame;
      request.recycle = recycle;
      const transfer = recycle ? this.transferBoth : this.transferFrame;
      transfer[0] = frame;
      if (recycle) transfer[1] = recycle;
      try {
        worker.postMessage(request, transfer);
      } catch (cause) {
        // Typically a frame that was already closed: only this frame is lost.
        clearTimeout(timer);
        this.pending.delete(id);
        frame.close();
        this.settleFailure(
          reject,
          new SegmentFailure('The frame could not be sent to the segmenter.', false, { cause }),
        );
      }
    });
  }

  recycle(data: Uint8Array): void {
    const { buffer } = data;
    if (
      buffer instanceof ArrayBuffer &&
      data.byteOffset === 0 &&
      data.byteLength === buffer.byteLength
    ) {
      this.spare = buffer;
    }
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.cancelInit?.(new VisionError('segmenter-init', 'The segmenter was stopped.'));
    this.rejectAll(new SegmentFailure('The segmenter was stopped.', true));
    this.terminate();
  }

  private terminate(): void {
    // Terminating also frees the worker's GL context and any frame it still holds.
    this.worker?.terminate();
    this.worker = null;
  }

  private onMessage(message: WorkerResponse): void {
    if (message.type !== 'mask' && message.type !== 'segment-error') return;
    const pending = this.pending.get(message.id);
    if (!pending) return; // Timed out earlier; drop the late reply.
    this.pending.delete(message.id);
    clearTimeout(pending.timer);
    if (message.type === 'mask') {
      pending.resolve({
        data: new Uint8Array(message.data),
        width: message.width,
        height: message.height,
        inferMs: message.inferMs,
        regions: message.regions,
      });
      this.options.monitor?.(null);
    } else {
      const { contextLost } = message;
      // Without its GPU context the worker can never segment again.
      if (contextLost) this.broken = true;
      this.settleFailure(
        pending.reject,
        new SegmentFailure(message.message, contextLost, { contextLost }),
      );
    }
  }

  private readonly onTimeout = (id: number): void => {
    const pending = this.pending.get(id);
    if (!pending) return;
    const now = performance.now();
    if (now - pending.deadline > LATE_TIMER_MS) {
      // The main thread was not running on time, so the reply may be sitting in the queue.
      pending.deadline = now + SEGMENT_TIMEOUT_MS;
      pending.timer = setTimeout(this.onTimeout, SEGMENT_TIMEOUT_MS, id);
      return;
    }
    this.pending.delete(id);
    // A worker that misses a deadline is not trusted with another frame.
    this.broken = true;
    this.settleFailure(
      pending.reject,
      new SegmentFailure('The segmenter worker stopped responding.', true),
    );
  };

  private crash(message: string): void {
    console.warn(`[vision] ${message}`);
    this.broken = true;
    const failure = new SegmentFailure(message, true);
    this.rejectAll(failure);
    // Reported even with no frame in flight, so the owner replaces the worker right away.
    this.options.monitor?.(failure);
  }

  private settleFailure(reject: (error: VisionError) => void, failure: SegmentFailure): void {
    reject(failure);
    this.options.monitor?.(failure);
  }

  private rejectAll(failure: SegmentFailure): void {
    for (const pending of this.pending.values()) {
      clearTimeout(pending.timer);
      pending.reject(failure);
    }
    this.pending.clear();
  }
}
