/** Quadrature samples for `visibleFraction`; the error is a small fraction of a percent. */
const VISIBLE_SAMPLES = 32;

/**
 * Fraction of the disc (x, y, r) that lies inside the rectangle [0, width] × [0, height].
 *
 * Integrates the clipped chord length over the disc's height with y = cy + r·sin θ. The
 * substitution removes the square-root singularity at the top and bottom of the disc, and
 * clipping the θ range handles the horizontal edges exactly, so only the vertical edges
 * leave kinks in the integrand (second-order error under the midpoint rule).
 */
export function visibleFraction(
  x: number,
  y: number,
  r: number,
  width: number,
  height: number,
): number {
  if (x - r >= 0 && x + r <= width && y - r >= 0 && y + r <= height) return 1;
  if (x + r <= 0 || x - r >= width || y + r <= 0 || y - r >= height || r <= 0) return 0;
  const lo = Math.asin(Math.max(-1, -y / r));
  const hi = Math.asin(Math.min(1, (height - y) / r));
  const step = (hi - lo) / VISIBLE_SAMPLES;
  let sum = 0;
  for (let k = 0; k < VISIBLE_SAMPLES; k++) {
    const cos = Math.cos(lo + (k + 0.5) * step);
    const half = r * cos;
    const chord = Math.min(width, x + half) - Math.max(0, x - half);
    if (chord > 0) sum += chord * cos;
  }
  // Area = ∫ chord · r cos θ dθ, divided by the disc's area π r².
  return Math.min(1, (sum * step) / (Math.PI * r));
}
