import { type FrameSource, type FrameTick, type SourceInfo, VisionError } from './types';
import {
  createVideoElement,
  playUntilFirstFrame,
  supportsVideoFrames,
  VideoTicker,
} from './videoTicker';

const CONSTRAINTS: MediaTrackConstraints = {
  width: { ideal: 1280 },
  height: { ideal: 720 },
  frameRate: { ideal: 30 },
};
/** An open camera that shows nothing for this long is not going to. */
const FIRST_FRAME_TIMEOUT_MS = 10_000;

function errorName(error: unknown): string {
  // Not every browser makes OverconstrainedError a DOMException, so go by name.
  return typeof error === 'object' && error !== null && 'name' in error ? String(error.name) : '';
}

function toVisionError(cause: unknown): VisionError {
  switch (errorName(cause)) {
    case 'NotAllowedError':
    case 'SecurityError':
      return new VisionError('permission-denied', 'Camera access was not allowed.', { cause });
    case 'NotFoundError':
    case 'OverconstrainedError':
      return new VisionError('no-camera', 'No camera was found.', { cause });
    case 'NotReadableError':
    case 'AbortError':
      return new VisionError('camera-busy', 'The camera is in use by another app.', { cause });
    default:
      return new VisionError('unknown', 'The camera could not be started.', { cause });
  }
}

function stopTracks(stream: MediaStream): void {
  for (const track of stream.getTracks()) track.stop();
}

/** Live camera via getUserMedia, one tick per presented frame. */
export class CameraSource implements FrameSource {
  readonly kind = 'camera' as const;
  info: SourceInfo | null = null;
  display: HTMLVideoElement | null = null;
  stream: MediaStream | null = null;

  private ticker: VideoTicker | null = null;
  private track: MediaStreamTrack | null = null;
  private handler: ((tick: FrameTick) => void) | null = null;
  private endedHandler: ((error: VisionError) => void) | null = null;
  private paused = false;
  private stopped = false;

  /**
   * @param fallbackToDefault use the default camera if `deviceId` is gone (a remembered
   *   camera); off for an explicit choice, which should fail rather than silently differ.
   */
  constructor(
    private readonly deviceId: string | null,
    private readonly fallbackToDefault = true,
  ) {}

  async start(): Promise<SourceInfo> {
    if (this.stopped || this.stream)
      throw new VisionError('unknown', 'The camera source was reused.');
    if (!navigator.mediaDevices?.getUserMedia || !supportsVideoFrames()) {
      throw new VisionError('unsupported', 'This browser cannot access the camera here.');
    }
    const stream = await this.open();
    if (this.stopped) {
      stopTracks(stream);
      throw new VisionError('unknown', 'The camera was closed while it was starting.');
    }
    const track = stream.getVideoTracks()[0];
    if (!track) {
      stopTracks(stream);
      throw new VisionError('no-camera', 'The camera produced no video.');
    }
    const video = createVideoElement();
    video.srcObject = stream;
    // Owned from here on, so stop() releases them whatever happens next.
    this.stream = stream;
    this.track = track;
    this.display = video;

    try {
      await playUntilFirstFrame(video, FIRST_FRAME_TIMEOUT_MS);
    } catch (cause) {
      this.stop();
      throw new VisionError('unknown', 'The camera opened but sent no picture.', { cause });
    }
    if (this.stopped)
      throw new VisionError('unknown', 'The camera was closed while it was starting.');

    track.addEventListener('ended', this.onEnded);
    video.addEventListener('resize', this.onResize);
    this.info = this.describe();
    const ticker = new VideoTicker(video);
    ticker.handler = this.handler;
    this.ticker = ticker;
    if (!this.paused) ticker.start();
    return this.info;
  }

  pause(): void {
    this.paused = true;
    this.ticker?.stop();
  }

  resume(): void {
    if (this.stopped) return;
    this.paused = false;
    this.ticker?.start();
  }

  stop(): void {
    this.stopped = true;
    this.ticker?.stop();
    this.ticker = null;
    this.handler = null;
    this.endedHandler = null;
    this.track?.removeEventListener('ended', this.onEnded);
    this.display?.removeEventListener('resize', this.onResize);
    if (this.stream) stopTracks(this.stream);
    if (this.display) this.display.srcObject = null;
    this.stream = null;
    this.track = null;
  }

  setFrameHandler(handler: ((tick: FrameTick) => void) | null): void {
    this.handler = handler;
    if (this.ticker) this.ticker.handler = handler;
  }

  setEndedHandler(handler: ((error: VisionError) => void) | null): void {
    this.endedHandler = handler;
  }

  private async open(): Promise<MediaStream> {
    const { deviceId } = this;
    const request = (video: MediaTrackConstraints) =>
      navigator.mediaDevices.getUserMedia({ video, audio: false });
    try {
      return await request(
        deviceId ? { ...CONSTRAINTS, deviceId: { exact: deviceId } } : CONSTRAINTS,
      );
    } catch (error) {
      const name = errorName(error);
      const missing = name === 'OverconstrainedError' || name === 'NotFoundError';
      if (!deviceId || !missing || !this.fallbackToDefault) throw toVisionError(error);
      console.info('[vision] the remembered camera is not available; using the default one');
    }
    try {
      return await request(CONSTRAINTS);
    } catch (error) {
      throw toVisionError(error);
    }
  }

  /** What the camera actually delivers, which may differ from what was asked for. */
  private describe(): SourceInfo {
    const settings = this.track?.getSettings() ?? {};
    const video = this.display;
    return {
      kind: 'camera',
      width: video?.videoWidth || settings.width || 0,
      height: video?.videoHeight || settings.height || 0,
      frameRate: settings.frameRate ?? null,
      label: this.track?.label ?? '',
      deviceId: settings.deviceId ?? this.deviceId,
    };
  }

  private readonly onEnded = (): void => {
    this.endedHandler?.(new VisionError('camera-lost', 'The camera was disconnected.'));
  };

  private readonly onResize = (): void => {
    const video = this.display;
    if (!video || !this.info || video.videoWidth === 0) return;
    if (video.videoWidth === this.info.width && video.videoHeight === this.info.height) return;
    // A new object, so the pipeline notices the change on the next frame.
    this.info = this.describe();
  };
}
