/**
 * Turns per-frame sightings of people into players with stable numbers.
 *
 * The camera side reports who it sees in each frame, in no particular order and with no
 * memory. Each sighting is matched to the track nearest to it (measured in torso lengths, so
 * the same rule works near and far). A newcomer takes a slot once they have stayed in view
 * for a moment and moved: the mask also contains things that are not people (a coat on a
 * hook), and those never wave. A player who drops out of sight keeps their slot: for a
 * couple of seconds while players are being gathered, for the whole round once it has
 * started.
 *
 * Two players who touch are seen as one body. The one matched to it stays "seen"; the other
 * is remembered as sharing it, and the body's width is divided between them in the order
 * they were last seen standing apart.
 */
import { MAX_PLAYERS, type PersonSighting } from './types';

/** How far a person can plausibly move between two sightings, in torso lengths. */
const MATCH_DISTANCE = 2.5;
/** The match distance grows by this factor per second out of sight, up to the cap. */
const MATCH_GROWTH_PER_S = 2;
const MATCH_DISTANCE_MAX = 10;
/**
 * Once the roster is fixed, a player out of sight this long takes any unclaimed sighting,
 * however far away: someone who ran out one side and came back in the other is far likelier
 * than a stranger.
 */
const ANYWHERE_AFTER_MS = 1000;
/** A newcomer becomes a player after being seen for this long... */
const JOIN_AFTER_MS = 600;
/** ...and having moved or changed shape by this much, in torso lengths (a step, a wave). */
const JOIN_MOVEMENT = 0.4;
/** A newcomer is forgotten if it disappears for this long (a flicker of the detector). */
const CANDIDATE_LOST_MS = 400;
/** While gathering players, one who has been out of sight this long has left. */
const LEAVE_AFTER_MS = 2500;
/** A player hidden inside another's body for longer than this no longer shares its pops. */
const SHARE_MEMORY_MS = 5000;
/** Smallest torso length used as a yardstick, in world units. */
const MIN_SIZE = 20;

export interface Track {
  /** Player slot, or -1 for a newcomer who has not joined yet. */
  slot: number;
  active: boolean;
  x: number;
  y: number;
  headX: number;
  headY: number;
  size: number;
  left: number;
  right: number;
  top: number;
  bottom: number;
  seen: boolean;
  score: number;
  /** The sighting matched in the newest frame, if any. */
  sighting: PersonSighting | null;
  /** x when this player was last seen with a body of their own. */
  soloX: number;
  firstSeenMs: number;
  lastSeenMs: number;
  /** Newcomers: where and how wide they were when first seen, and whether they have moved. */
  startX: number;
  startY: number;
  startTop: number;
  startWidth: number;
  moved: boolean;
}

function emptyTrack(slot: number): Track {
  return {
    slot,
    active: false,
    x: 0,
    y: 0,
    headX: 0,
    headY: 0,
    size: MIN_SIZE,
    left: 0,
    right: 0,
    top: 0,
    bottom: 0,
    seen: false,
    score: 0,
    sighting: null,
    soloX: 0,
    firstSeenMs: 0,
    lastSeenMs: 0,
    startX: 0,
    startY: 0,
    startTop: 0,
    startWidth: 0,
    moved: false,
  };
}

function place(track: Track, sighting: PersonSighting, timeMs: number): void {
  track.x = sighting.x;
  track.y = sighting.y;
  track.headX = sighting.headX;
  track.headY = sighting.headY;
  track.size = Math.max(MIN_SIZE, sighting.size);
  track.left = sighting.left;
  track.right = sighting.right;
  track.top = sighting.top;
  track.bottom = sighting.bottom;
  track.seen = true;
  track.sighting = sighting;
  track.lastSeenMs = timeMs;
}

function inside(track: Track, sighting: PersonSighting): boolean {
  return (
    track.x >= sighting.left &&
    track.x <= sighting.right &&
    track.y >= sighting.top &&
    track.y <= sighting.bottom
  );
}

export class PlayerTracker {
  /** Indexed by slot, always `MAX_PLAYERS` long. */
  readonly players: Track[] = [];
  count = 0;
  /** Slots that joined or left during the last `update`. */
  readonly joined: number[] = [];
  readonly left: number[] = [];

  private readonly candidates: Track[] = [];
  private readonly used: boolean[] = [];
  private readonly sharing: Track[] = [];

  constructor() {
    for (let slot = 0; slot < MAX_PLAYERS; slot++) this.players.push(emptyTrack(slot));
  }

  /**
   * Fold in the people seen in one frame. While `recruiting`, newcomers can join and players
   * who stay out of sight leave; otherwise the roster is fixed.
   */
  update(sightings: readonly PersonSighting[], timeMs: number, recruiting: boolean): void {
    const { players, candidates, used } = this;
    this.joined.length = 0;
    this.left.length = 0;
    for (const player of players) {
      player.seen = false;
      player.sighting = null;
    }
    for (const candidate of candidates) {
      candidate.seen = false;
      candidate.sighting = null;
    }
    used.length = sightings.length;
    used.fill(false);

    // Players first, so a newcomer standing next to a player never takes their sighting.
    this.match(players, sightings, timeMs, !recruiting);
    this.match(candidates, sightings, timeMs, false);

    for (const player of players) {
      const { sighting } = player;
      if (player.active && sighting && !this.hiddenIn(sighting, timeMs)) player.soloX = player.x;
    }

    if (recruiting) {
      for (let i = 0; i < sightings.length; i++) {
        if (used[i]) continue;
        const sighting = sightings[i] as PersonSighting;
        const candidate = emptyTrack(-1);
        candidate.active = true;
        candidate.firstSeenMs = timeMs;
        place(candidate, sighting, timeMs);
        candidate.startX = sighting.x;
        candidate.startY = sighting.y;
        candidate.startTop = sighting.top;
        candidate.startWidth = sighting.right - sighting.left;
        candidates.push(candidate);
      }
      for (const player of players) {
        if (player.active && timeMs - player.lastSeenMs > LEAVE_AFTER_MS) {
          player.active = false;
          this.count--;
          this.left.push(player.slot);
        }
      }
    }

    // Newcomers: promote the ones that have lasted and moved, drop the ones that vanished.
    let kept = 0;
    for (const candidate of candidates) {
      if (timeMs - candidate.lastSeenMs > CANDIDATE_LOST_MS) continue;
      if (candidate.seen && !candidate.moved) {
        const change = Math.max(
          Math.abs(candidate.x - candidate.startX),
          Math.abs(candidate.y - candidate.startY),
          Math.abs(candidate.top - candidate.startTop),
          Math.abs(candidate.right - candidate.left - candidate.startWidth) / 2,
        );
        candidate.moved = change >= JOIN_MOVEMENT * candidate.size;
      }
      if (
        recruiting &&
        candidate.seen &&
        candidate.moved &&
        candidate.sighting &&
        timeMs - candidate.firstSeenMs >= JOIN_AFTER_MS
      ) {
        const free = players.find((player) => !player.active);
        if (free) {
          free.active = true;
          free.score = 0;
          free.firstSeenMs = candidate.firstSeenMs;
          place(free, candidate.sighting, timeMs);
          free.soloX = free.x;
          this.count++;
          this.joined.push(free.slot);
          continue;
        }
      }
      candidates[kept++] = candidate;
    }
    candidates.length = recruiting ? kept : 0;
  }

  /**
   * Who popped the bubble at (x, y) of radius r. `popper` is the sighting whose body covered
   * it, when that is known; otherwise the player whose bounding box is nearest gets it, if
   * it is within `reach` torso lengths of the bubble's edge. -1 if it was nobody's.
   */
  ownerOf(
    x: number,
    y: number,
    r: number,
    popper: PersonSighting | null,
    timeMs: number,
    reach: number,
  ): number {
    if (popper) {
      const sharing = this.playersIn(popper, timeMs);
      if (sharing.length === 0) return -1;
      // Several players in one body: its width is split between them, left to right.
      const width = Math.max(1, popper.right - popper.left);
      const strip = Math.floor(((x - popper.left) / width) * sharing.length);
      const index = Math.min(sharing.length - 1, Math.max(0, strip));
      return (sharing[index] as Track).slot;
    }

    let best = -1;
    let bestGap = Number.POSITIVE_INFINITY;
    for (const player of this.players) {
      if (!player.active || !player.seen) continue;
      const dx = Math.max(player.left - x, 0, x - player.right);
      const dy = Math.max(player.top - y, 0, y - player.bottom);
      const gap = Math.max(0, Math.hypot(dx, dy) - r) / player.size;
      if (gap <= reach && gap < bestGap) {
        bestGap = gap;
        best = player.slot;
      }
    }
    return best;
  }

  clear(): void {
    for (const player of this.players) {
      player.active = false;
      player.seen = false;
      player.sighting = null;
      player.score = 0;
    }
    this.candidates.length = 0;
    this.joined.length = 0;
    this.left.length = 0;
    this.count = 0;
  }

  /** Whether some other player is out of sight inside this body. */
  private hiddenIn(sighting: PersonSighting, timeMs: number): boolean {
    for (const player of this.players) {
      if (
        player.active &&
        !player.seen &&
        timeMs - player.lastSeenMs <= SHARE_MEMORY_MS &&
        inside(player, sighting)
      ) {
        return true;
      }
    }
    return false;
  }

  /**
   * The players in this body, left to right: the one matched to it and any who vanished
   * inside it. The returned array is reused.
   */
  private playersIn(sighting: PersonSighting, timeMs: number): Track[] {
    const { sharing } = this;
    sharing.length = 0;
    for (const player of this.players) {
      if (!player.active) continue;
      if (
        player.sighting === sighting ||
        (!player.seen && timeMs - player.lastSeenMs <= SHARE_MEMORY_MS && inside(player, sighting))
      ) {
        sharing.push(player);
      }
    }
    if (sharing.length > 1) sharing.sort((a, b) => a.soloX - b.soloX);
    return sharing;
  }

  /** Give each track its nearest free sighting, closest pairs first. */
  private match(
    tracks: readonly Track[],
    sightings: readonly PersonSighting[],
    timeMs: number,
    locked: boolean,
  ): void {
    const { used } = this;
    for (;;) {
      let bestTrack: Track | null = null;
      let bestSighting = -1;
      let bestCost = Number.POSITIVE_INFINITY;
      for (const track of tracks) {
        if (!track.active || track.seen) continue;
        const unseenS = Math.max(0, timeMs - track.lastSeenMs) / 1000;
        const limit =
          locked && unseenS * 1000 >= ANYWHERE_AFTER_MS
            ? Number.POSITIVE_INFINITY
            : Math.min(MATCH_DISTANCE_MAX, MATCH_DISTANCE * (1 + MATCH_GROWTH_PER_S * unseenS));
        for (let i = 0; i < sightings.length; i++) {
          if (used[i]) continue;
          const sighting = sightings[i] as PersonSighting;
          const scale = Math.max(MIN_SIZE, track.size, sighting.size);
          const cost = Math.hypot(sighting.x - track.x, sighting.y - track.y) / scale;
          if (cost <= limit && cost < bestCost) {
            bestCost = cost;
            bestTrack = track;
            bestSighting = i;
          }
        }
      }
      if (!bestTrack) return;
      used[bestSighting] = true;
      place(bestTrack, sightings[bestSighting] as PersonSighting, timeMs);
    }
  }
}
