/** Uploads the procedural artwork as Pixi textures. Created once at init, destroyed on dispose. */
import { BufferImageSource, CanvasSource, Rectangle, Texture, type TextureSource } from 'pixi.js';
import {
  bubbleLight,
  bubbleShell,
  capsule,
  type EffectFrameName,
  effectAtlas,
  type Frame,
  type Image,
  SHELL_VARIANTS,
  thinFilmTable,
} from './art';

/** Bubble texture side. Covers the largest tunable radius at the capped resolution. */
const SHELL_SIZE = 512;

/** Characters the coverage labels use, in atlas order. */
export const GLYPHS = '0123456789.-';

export interface StageTextures {
  shells: Texture[];
  light: Texture;
  effects: Record<EffectFrameName, Texture>;
  /** One texture per character of GLYPHS, all the same cell size. */
  glyphs: Texture[];
  /** A short rounded dash for the coverage gauge. */
  dash: Texture;
  /** Dark glass disc for the score's nine-slice backdrop. */
  capsule: Texture;
  destroy(): void;
}

function upload(image: Image, label: string): BufferImageSource {
  return new BufferImageSource({
    resource: image.data,
    width: image.width,
    height: image.height,
    format: 'rgba8unorm',
    alphaMode: 'premultiplied-alpha',
    autoGenerateMipmaps: true,
    scaleMode: 'linear',
    label,
  });
}

function framed(source: TextureSource, frame: Frame): Texture {
  return new Texture({
    source,
    frame: new Rectangle(frame.x, frame.y, frame.width, frame.height),
  });
}

/** Digits with a dark outline, drawn by the browser's text engine (debug view only). */
function drawGlyphs(): { canvas: HTMLCanvasElement; cell: Frame; dash: Frame } {
  const cellWidth = 40;
  const cellHeight = 64;
  const canvas = document.createElement('canvas');
  canvas.width = cellWidth * GLYPHS.length + 64;
  canvas.height = cellHeight;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.font = '700 50px "DejaVu Sans Mono", Menlo, Consolas, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.lineWidth = 8;
    ctx.strokeStyle = 'rgba(0, 0, 0, 0.85)';
    ctx.fillStyle = '#ffffff';
    for (let i = 0; i < GLYPHS.length; i++) {
      const x = i * cellWidth + cellWidth / 2;
      ctx.strokeText(GLYPHS[i] as string, x, cellHeight / 2);
      ctx.fillText(GLYPHS[i] as string, x, cellHeight / 2);
    }
    // The gauge dash, after the glyphs: white, rounded, with a dark rim so it reads anywhere.
    const dashX = GLYPHS.length * cellWidth + 8;
    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.beginPath();
    ctx.roundRect(dashX, 20, 48, 24, 12);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.roundRect(dashX + 4, 24, 40, 16, 8);
    ctx.fill();
  }
  return {
    canvas,
    cell: { x: 0, y: 0, width: cellWidth, height: cellHeight },
    dash: { x: GLYPHS.length * cellWidth + 8, y: 20, width: 48, height: 24 },
  };
}

export function createStageTextures(): StageTextures {
  const table = thinFilmTable();
  const sources: TextureSource[] = [];
  const own = <T extends TextureSource>(source: T): T => {
    sources.push(source);
    return source;
  };

  const shells: Texture[] = [];
  for (let variant = 0; variant < SHELL_VARIANTS; variant++) {
    const source = own(upload(bubbleShell(SHELL_SIZE, variant, table), `bubble-shell-${variant}`));
    shells.push(new Texture({ source }));
  }
  const light = new Texture({ source: own(upload(bubbleLight(SHELL_SIZE), 'bubble-light')) });
  const backdrop = new Texture({ source: own(upload(capsule(128), 'hud-capsule')) });

  // Every particle must share one source, so the effects live in one atlas.
  const atlas = effectAtlas();
  const effectSource = own(upload(atlas.image, 'pop-effects'));
  const effects = {
    ring: framed(effectSource, atlas.frames.ring),
    flash: framed(effectSource, atlas.frames.flash),
    droplet: framed(effectSource, atlas.frames.droplet),
    spark: framed(effectSource, atlas.frames.spark),
  };

  const glyphArt = drawGlyphs();
  const glyphSource = own(
    new CanvasSource({
      resource: glyphArt.canvas,
      autoGenerateMipmaps: true,
      scaleMode: 'linear',
      label: 'coverage-glyphs',
    }),
  );
  const glyphs = Array.from(GLYPHS, (_, i) =>
    framed(glyphSource, { ...glyphArt.cell, x: i * glyphArt.cell.width }),
  );
  const dash = framed(glyphSource, glyphArt.dash);

  const textures = [...shells, light, backdrop, ...Object.values(effects), ...glyphs, dash];
  return {
    shells,
    light,
    capsule: backdrop,
    effects,
    glyphs,
    dash,
    destroy() {
      for (const texture of textures) texture.destroy();
      for (const source of sources) source.destroy();
    },
  };
}
