/**
 * A short message over the game ("Sound off", "Camera: Logitech BRIO"): feedback for the few
 * keys that work during play. Large enough to read from across the room, gone in a moment,
 * and never in the way of input.
 */
import type { Toast } from './types';

const VISIBLE_MS = 2200;

export function createToast(root: HTMLElement): Toast {
  const element = document.createElement('div');
  element.className = 'game-toast';
  element.setAttribute('role', 'status');
  element.hidden = true;
  root.appendChild(element);

  let timer: ReturnType<typeof setTimeout> | undefined;

  return {
    show(text) {
      element.textContent = text;
      element.hidden = false;
      // Restart the entrance animation when one message replaces another.
      element.classList.remove('is-shown');
      void element.offsetWidth;
      element.classList.add('is-shown');
      clearTimeout(timer);
      timer = setTimeout(() => {
        element.hidden = true;
      }, VISIBLE_MS);
    },
    dispose() {
      clearTimeout(timer);
      element.remove();
    },
  };
}
