import type { StartProgress, StartStage, VisionError, VisionErrorCode } from '../vision/types';
import type { BootProgress, OverlayMessage } from './types';

// Shown on the boot screen, both when a start fails and when play ends because of a problem
// (a lost camera returns there). The button reads "Start" or "Try again" depending on the
// state, so the details never name it.
const ERROR_MESSAGES: Record<VisionErrorCode, OverlayMessage> = {
  'permission-denied': {
    title: 'The camera is blocked',
    detail:
      'Click the camera icon at the right end of the address bar, choose Allow, then try again.',
  },
  'no-camera': {
    title: 'No camera found',
    detail: 'Check that a webcam is plugged in and switched on, then try again.',
  },
  'camera-busy': {
    title: 'The camera is busy',
    detail:
      'Another app or browser tab is using it, such as a video call. Close that, then try again.',
  },
  'camera-lost': {
    title: 'The camera was disconnected',
    detail: 'Check that its cable is plugged in, then try again.',
  },
  'clip-failed': {
    title: 'The video could not be played',
    detail: 'The file may be damaged or in a format this browser cannot play. Try another video.',
  },
  'model-download': {
    title: 'The game did not finish loading',
    detail:
      'Part of the game could not be downloaded. Check the internet connection, then try again.',
  },
  'segmenter-init': {
    title: 'The game could not get ready',
    detail:
      'The part of the game that sees the players would not start. Try again, or restart the browser.',
  },
  'segmenter-failed': {
    title: 'The game stopped seeing the players',
    detail: 'Something went wrong while watching the camera. Try again to keep playing.',
  },
  unsupported: {
    title: 'This browser cannot run the game',
    detail: 'Open this page in the latest Google Chrome on a laptop or desktop computer.',
  },
  unknown: {
    title: 'Something went wrong',
    detail:
      'The game hit an unexpected problem. Try again; if it keeps happening, reload the page.',
  },
};

/** The camera API only exists on HTTPS pages and localhost, which `unsupported` hides. */
const INSECURE_PAGE: OverlayMessage = {
  title: 'The camera only works on a secure page',
  detail: 'Open the game from its usual web address, the one that starts with https://.',
};

/** Plain-language explanation of a vision failure, written for a parent, not a developer. */
export function describeVisionError(error: VisionError): OverlayMessage {
  const insecure = error.code === 'unsupported' && globalThis.isSecureContext === false;
  const message = insecure ? INSECURE_PAGE : (ERROR_MESSAGES[error.code] ?? ERROR_MESSAGES.unknown);
  return { ...message, technical: `${error.code}: ${error.message}` };
}

const STAGE_LABELS: Record<StartStage, string> = {
  camera: 'Turning on the camera. Choose Allow if asked.',
  download: 'Downloading the game…',
  wasm: 'Getting things ready…',
  warmup: 'Almost ready…',
};

export function describeStartProgress(progress: StartProgress): BootProgress {
  return { label: STAGE_LABELS[progress.stage], fraction: progress.fraction };
}
