/**
 * Small wrappers around browser features the game needs while it runs on a TV with nobody
 * at the keyboard: keeping the screen awake, fullscreen, and hiding the idle cursor.
 * All of them fail quietly; none is essential to play.
 */

/** Keeps the display from dimming or sleeping. The lock is lost when the tab is hidden. */
export class WakeLock {
  private sentinel: WakeLockSentinel | null = null;
  private wanted = false;

  /** Request the lock. Call again after the tab becomes visible. */
  async acquire(): Promise<void> {
    this.wanted = true;
    if (this.sentinel || !('wakeLock' in navigator)) return;
    try {
      const sentinel = await navigator.wakeLock.request('screen');
      if (!this.wanted) {
        void sentinel.release();
        return;
      }
      this.sentinel = sentinel;
      sentinel.addEventListener('release', () => {
        if (this.sentinel === sentinel) this.sentinel = null;
      });
    } catch {
      // Denied (for example on battery saver): the game still works.
    }
  }

  release(): void {
    this.wanted = false;
    void this.sentinel?.release();
    this.sentinel = null;
  }
}

/** Must be called from a user gesture. */
export function enterFullscreen(): void {
  if (document.fullscreenElement) return;
  document.documentElement.requestFullscreen?.({ navigationUI: 'hide' }).catch(() => {
    // Not allowed here (embedded, or no gesture): stay windowed.
  });
}

export function exitFullscreen(): void {
  const leave = (): void => {
    if (document.fullscreenElement) void document.exitFullscreen().catch(() => {});
  };
  if (document.fullscreenElement) {
    leave();
    return;
  }
  // A request made a moment ago may still be pending: leave as soon as it lands.
  document.addEventListener('fullscreenchange', leave, { once: true });
  setTimeout(() => document.removeEventListener('fullscreenchange', leave), 1500);
}

export function toggleFullscreen(): void {
  if (document.fullscreenElement) void document.exitFullscreen().catch(() => {});
  else enterFullscreen();
}

const CURSOR_IDLE_MS = 2500;

/**
 * Hides the mouse cursor over `element` after a short idle period by toggling the
 * `cursor-idle` class (styled in index.html), and shows it again on movement.
 */
export class IdleCursor {
  private timer: ReturnType<typeof setTimeout> | null = null;
  private active = false;

  constructor(private readonly element: HTMLElement) {}

  start(): void {
    if (this.active) return;
    this.active = true;
    window.addEventListener('mousemove', this.onMove);
    this.arm();
  }

  stop(): void {
    if (!this.active) return;
    this.active = false;
    window.removeEventListener('mousemove', this.onMove);
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    this.element.classList.remove('cursor-idle');
  }

  private readonly onMove = (): void => {
    this.element.classList.remove('cursor-idle');
    this.arm();
  };

  private arm(): void {
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => this.element.classList.add('cursor-idle'), CURSOR_IDLE_MS);
  }
}

/** True when a key press is meant for a form control rather than the game. */
export function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target.isContentEditable ||
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement
  );
}
