/**
 * Finds the separate people in a person mask.
 *
 * The mask says "person" per texel but not which person. Bodies that do not touch form
 * separate connected regions, so each large enough region is taken as one person, and a
 * bubble belongs to the region that supplied the texels covering it. Two people who touch
 * are one region; `PlayerTracker` deals with that.
 */
import type { PersonMask } from '../core/mask';
import { type ViewTransform, worldToMaskU, worldToMaskV } from '../core/view';
import type { PersonSighting } from './types';

/** A region must be at least this tall (fraction of the mask height) to be a person... */
const MIN_HEIGHT = 0.2;
/** ...and cover at least this fraction of the mask. Smaller ones are stray hands and noise. */
const MIN_AREA = 0.004;
/**
 * ...and the model must be sure of it: the mean probability over a real body is close to 1,
 * while the things it mistakes for people (a punching bag, a coat) are mostly half-hearted.
 */
const MIN_CONFIDENCE = 0.8;
/** A person's torso is about this fraction of their height on screen. */
const TORSO_OF_HEIGHT = 0.3;
/** The head's x is the centre of the region's rows within this fraction of its top. */
const HEAD_BAND = 0.08;

export class BlobFinder {
  /** The people in the last mask given to `find`. Objects are new each time. */
  sightings: PersonSighting[] = [];

  /** Region number per texel, 0 for none; `owner[n]` is region n's sighting, if it is a person. */
  private labels = new Uint16Array(0);
  private stack = new Int32Array(0);
  private owner: Array<PersonSighting | null> = [null];
  private votes = new Int32Array(1);
  private width = 0;
  private height = 0;
  private view: ViewTransform | null = null;
  private scaleX = 1;
  private scaleY = 1;

  find(mask: PersonMask, view: ViewTransform, threshold: number): PersonSighting[] {
    const { data, width, height } = mask;
    const length = width * height;
    if (this.labels.length !== length) {
      this.labels = new Uint16Array(length);
      this.stack = new Int32Array(length);
    }
    const { labels, stack } = this;
    labels.fill(0);
    this.width = width;
    this.height = height;
    this.view = view;
    // The view may still describe the previous mask size: see DiscProbe.setMask.
    this.scaleX = width / view.maskWidth;
    this.scaleY = height / view.maskHeight;
    const level = threshold * 255;
    const worldX = (u: number): number => (u / this.scaleX - view.maskOffsetX) / view.maskScaleX;
    const worldY = (v: number): number => (v / this.scaleY - view.maskOffsetY) / view.maskScaleY;

    const owner: Array<PersonSighting | null> = [null];
    const sightings: PersonSighting[] = [];
    for (let start = 0; start < length; start++) {
      if (labels[start] !== 0 || (data[start] as number) < level) continue;
      // Uint16 labels: a mask noisy enough to have 65535 regions has no people to find.
      if (owner.length > 0xffff) break;
      const label = owner.length;
      let minX = width;
      let maxX = 0;
      let minY = height;
      let maxY = 0;
      let texels = 0;
      let sumX = 0;
      let sumY = 0;
      let sumP = 0;
      let top = 0;
      stack[top++] = start;
      labels[start] = label;
      while (top > 0) {
        const index = stack[--top] as number;
        const x = index % width;
        const y = (index - x) / width;
        texels++;
        sumX += x;
        sumY += y;
        sumP += data[index] as number;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
        if (x > 0 && labels[index - 1] === 0 && (data[index - 1] as number) >= level) {
          labels[index - 1] = label;
          stack[top++] = index - 1;
        }
        if (x < width - 1 && labels[index + 1] === 0 && (data[index + 1] as number) >= level) {
          labels[index + 1] = label;
          stack[top++] = index + 1;
        }
        if (y > 0 && labels[index - width] === 0 && (data[index - width] as number) >= level) {
          labels[index - width] = label;
          stack[top++] = index - width;
        }
        if (
          y < height - 1 &&
          labels[index + width] === 0 &&
          (data[index + width] as number) >= level
        ) {
          labels[index + width] = label;
          stack[top++] = index + width;
        }
      }

      const tall = maxY - minY + 1;
      if (
        tall < MIN_HEIGHT * height ||
        texels < MIN_AREA * length ||
        sumP < MIN_CONFIDENCE * 255 * texels
      ) {
        owner.push(null);
        continue;
      }
      // Centre of the topmost rows: where the head is.
      const band = Math.max(1, Math.round(tall * HEAD_BAND));
      let headSum = 0;
      let headCount = 0;
      for (let y = minY; y < minY + band; y++) {
        for (let x = minX; x <= maxX; x++) {
          if (labels[y * width + x] === label) {
            headSum += x;
            headCount++;
          }
        }
      }
      const headU = headCount > 0 ? headSum / headCount + 0.5 : (minX + maxX + 1) / 2;
      // Mirroring flips which mask edge is the left one on screen.
      const edgeA = worldX(minX);
      const edgeB = worldX(maxX + 1);
      const topY = worldY(minY);
      const bottomY = worldY(maxY + 1);
      const sighting: PersonSighting = {
        x: worldX(sumX / texels + 0.5),
        y: worldY(sumY / texels + 0.5),
        headX: worldX(headU),
        headY: topY,
        size: Math.max(1, TORSO_OF_HEIGHT * (bottomY - topY)),
        left: Math.min(edgeA, edgeB),
        right: Math.max(edgeA, edgeB),
        top: topY,
        bottom: bottomY,
      };
      owner.push(sighting);
      sightings.push(sighting);
    }
    this.owner = owner;
    if (this.votes.length < owner.length) this.votes = new Int32Array(owner.length * 2);
    this.sightings = sightings;
    return sightings;
  }

  /**
   * The person who supplied most of the mask texels inside the disc at (x, y) of radius r,
   * or null if most of them belong to no person-sized region (or there are none).
   */
  personAt(x: number, y: number, r: number): PersonSighting | null {
    const view = this.view;
    if (!view || !(r > 0)) return null;
    const { labels, width, height, votes, owner } = this;
    const cu = worldToMaskU(view, x) * this.scaleX;
    const cv = worldToMaskV(view, y) * this.scaleY;
    const ru = Math.abs(view.maskScaleX * this.scaleX) * r;
    const rv = view.maskScaleY * this.scaleY * r;
    const vFirst = Math.max(0, Math.ceil(cv - rv - 0.5));
    const vLast = Math.min(height - 1, Math.floor(cv + rv - 0.5));
    votes.fill(0, 0, owner.length);
    let best = 0;
    for (let v = vFirst; v <= vLast; v++) {
      const dv = (v + 0.5 - cv) / rv;
      const half = ru * Math.sqrt(Math.max(0, 1 - dv * dv));
      const uFirst = Math.max(0, Math.ceil(cu - half - 0.5));
      const uLast = Math.min(width - 1, Math.floor(cu + half - 0.5));
      for (let i = v * width + uFirst; i <= v * width + uLast; i++) {
        const label = labels[i] as number;
        if (label === 0) continue;
        const count = (votes[label] as number) + 1;
        votes[label] = count;
        if (count > (votes[best] as number) || best === 0) best = label;
      }
    }
    return best === 0 ? null : (owner[best] ?? null);
  }
}
